    const matchesEvent = !Number.isFinite(numericId) || (latest && latest.message_id === numericId);
    if (!latest || latest.role !== 'user' || !matchesEvent || latest.message_id <= 0) return null;
    const assistants = getMessages(`0-${latest.message_id - 1}`, {
      role: 'assistant', hide_state: 'unhidden', include_swipes: false,
    }) || [];
    const assistant = assistants.length ? assistants[assistants.length - 1] : null;
    return assistant ? { user: latest, assistant } : null;
  }

  function patchAdviceContextMessage(messageId, nextText) {
    const context = hostContext();
    const chat = context && Array.isArray(context.chat) ? context.chat : null;
    const row = chat && chat[messageId];
    if (!row) return false;
    row.mes = nextText;
    const swipeId = Number(row.swipe_id);
    if (Array.isArray(row.swipes) && Number.isInteger(swipeId) && swipeId >= 0) {
      row.swipes[swipeId] = nextText;
    }
    return true;
  }

  function adviceMessageUpdatePayload(message, nextText, extra) {
    const payload = { message_id: message.message_id, message: nextText };
    if (extra && typeof extra === 'object') payload.extra = clone(extra);
    const context = hostContext();
    const row = context && Array.isArray(context.chat) ? context.chat[message.message_id] : null;
    const rowSwipeId = Number(row && row.swipe_id);
    if (row && Array.isArray(row.swipes) && Number.isInteger(rowSwipeId) && rowSwipeId >= 0) {
      const swipes = row.swipes.slice();
      swipes[rowSwipeId] = nextText;
      payload.swipes = swipes;
      return payload;
    }
    const getMessages = hostFunction('getChatMessages');
    if (!getMessages) return payload;
    try {
      const swiped = (getMessages(message.message_id, {
        role: message.role, hide_state: 'unhidden', include_swipes: true,
      }) || [])[0];
      const swipeId = Number(swiped && swiped.swipe_id);
      if (swiped && Array.isArray(swiped.swipes) && Number.isInteger(swipeId) && swipeId >= 0) {
        const swipes = swiped.swipes.slice();
        swipes[swipeId] = nextText;
        payload.swipes = swipes;
      }
    } catch (_) {}
    return payload;
  }

  function adviceMetaFromRow(row) {
    const meta = row && row.extra && row.extra.izumi_advice;
    if (!meta || typeof meta !== 'object' || Array.isArray(meta) || meta.version !== 1
      || typeof meta.text !== 'string' || !Number.isInteger(meta.assistantId) || meta.assistantId < 0
      || (meta.revision !== undefined && (!Number.isInteger(meta.revision) || meta.revision < 0))) return null;
    const hasReplacement = Object.prototype.hasOwnProperty.call(meta, 'replacementText');
    // 损坏的快照不归一成默认句：它不能因此获得历史转移凭据。
    if (hasReplacement && (typeof meta.replacementText !== 'string' || !meta.replacementText.trim())) return null;
    return {
      text: meta.text,
      assistantId: meta.assistantId,
      revision: meta.revision || 0,
      replacementText: hasReplacement ? meta.replacementText : LEGACY_ADVICE_CONTINUE_TEXT,
    };
  }

  function previousAdviceAssistantId(userId) {
    const context = hostContext();
    const chat = context && Array.isArray(context.chat) ? context.chat : null;
    if (!chat || !Number.isInteger(userId)) return -1;
    for (let index = userId - 1; index >= 0; index -= 1) {
      const row = chat[index];
      if (row && contextChatMessageRole(row) === 'assistant' && !row.is_system) {
        // assistantId 只作为冗余校验；楼层插入/删除后，以当前最近 AI 为准，避免串楼。
        return index;
      }
    }
    return -1;
  }

  function pairedAdviceUserId(assistantId) {
    const context = hostContext();
    const chat = context && Array.isArray(context.chat) ? context.chat : null;
    if (!chat || !Number.isInteger(assistantId)) return -1;
    for (let index = assistantId + 1; index < chat.length; index += 1) {
      const row = chat[index];
      if (!row || row.is_system || contextChatMessageRole(row) === 'system') continue;
      const role = contextChatMessageRole(row);
      if (role === 'assistant') return -1;
      if (role !== 'user') continue;
      const record = adviceRecordForUser(index);
      return record && record.assistantId === assistantId ? index : -1;
    }
    return -1;
  }

  function setAdviceUserMeta(userId, text, assistantId, replacementText) {
    const context = hostContext();
    const chat = context && Array.isArray(context.chat) ? context.chat : null;
    const row = chat && chat[userId];
    if (!row) return null;
    const previous = adviceMetaFromRow(row);
    const extra = Object.assign({}, row.extra || {});
    extra.izumi_advice = {
      version: 1,
      text: String(text == null ? '' : text),
      assistantId: Number(assistantId),
      revision: (previous ? previous.revision : 0) + 1,
      replacementText: normalizeReplacementText(replacementText === undefined && previous ? previous.replacementText : replacementText),
    };
    row.extra = extra;
    return extra;
  }

  function adviceRecordForUser(userId, { includeActive = true, allowLegacy = true } = {}) {
    const context = hostContext();
    const chat = context && Array.isArray(context.chat) ? context.chat : null;
    const row = chat && chat[userId];
    if (!row || contextChatMessageRole(row) !== 'user' || row.is_system) return null;
    const assistantId = previousAdviceAssistantId(userId);
    const meta = adviceMetaFromRow(row);
    if (meta) return Object.assign({}, meta, { assistantId });
    const draft = adviceUserEditDrafts.get(userId);
    if (draft && draft.chatKey === adviceChatKey()) {
      return { text: draft.text, replacementText: draft.replacementText, assistantId, revision: 0 };
    }
    const active = latestAdviceTransfer;
    if (includeActive && active && active.chatKey === adviceChatKey() && active.userId === userId && active.assistantId === assistantId) {
      return { text: active.userText, replacementText: active.replacementText, assistantId, revision: 0 };
    }
    // 只有完全没有元数据的旧固定句可借最近 AI 的完整标签识别；模型 Advice 本身不证明转移。
    if (!allowLegacy || (row.extra && Object.prototype.hasOwnProperty.call(row.extra, 'izumi_advice'))) return null;
    if (String(row.mes == null ? '' : row.mes) !== LEGACY_ADVICE_CONTINUE_TEXT || assistantId < 0) return null;
    const state = adviceTagState(chat[assistantId] && chat[assistantId].mes);
    return state.found ? { text: state.text, replacementText: LEGACY_ADVICE_CONTINUE_TEXT, assistantId, revision: 0 } : null;
  }

  function adviceRowIsReplacement(row, record) {
    return !!record && !!row && contextChatMessageRole(row) === 'user'
      && String(row.mes == null ? '' : row.mes) === record.replacementText;
  }

  function adviceDataForUser(userId) {
    return adviceRecordForUser(userId);
  }

  function replaceUserAdviceAfterEdit(assistantText, userText, oldUserText = '', hasKnownOld = false) {
    return advice_replaceUserAdviceAfterEdit(assistantText, userText, oldUserText, hasKnownOld, adviceConfig);
  }

  function adviceLastUserMessageMacro() {
    const substitute = hostFunction('substitudeMacros');
    if (!substitute) return '';
    try {
      const resolved = substitute('{{lastUserMessage}}');
      const value = String(resolved == null ? '' : resolved);
      if (!value || /\{\{\s*lastUserMessage\s*\}\}/i.test(value)) return '';
      return value;
    } catch (_) { return ''; }
  }

  function stageAdviceTransfer(sentMessageId, capturedUserText = '', { newlySent = false } = {}) {
    if (!adviceRuntimeEnabled()) return null;
    const suppliedText = String(capturedUserText == null ? '' : capturedUserText);
    if (suppliedText) adviceCapturedUserText = suppliedText;
    const chatKey = adviceChatKey();
    const pair = currentAdviceMessagePair(sentMessageId);
    const active = latestAdviceTransfer && latestAdviceTransfer.chatKey === chatKey
      ? latestAdviceTransfer
      : null;
    if (!pair) return active;
    const pairText = String(pair.user.message == null ? '' : pair.user.message);
    const captured = adviceCapturedUserText;
    const sameActiveMessage = active && active.userId === pair.user.message_id && active.assistantId === pair.assistant.message_id
      && (!active.userRow || active.userRow === pair.userRow);
    const record = adviceRecordForUser(pair.user.message_id, { includeActive: false, allowLegacy: !newlySent && !suppliedText && !sameActiveMessage });
    if (sameActiveMessage && (!record || (record.text === active.userText && record.replacementText === active.replacementText))) {
      const sameInput = text => text === active.userText || text === active.replacementText || text === active.user.message;
      if (sameInput(pairText) && (!captured || sameInput(captured))) {
        adviceCapturedUserText = '';
        return active;
      }
    }
    const isReplacement = record && pairText === record.replacementText;
    // 只排除有凭据的该楼占位句；无凭据的同句仍是新的真实输入。
    const userText = captured && (!record || captured !== record.replacementText)
      ? captured
      : isReplacement ? record.text : pairText;
    if (!userText && !isReplacement) return null;
    const replacementText = record ? record.replacementText : normalizeReplacementText(adviceConfig.replacementText);
    const rewriteConfig = {
      position: adviceConfig.position === 'head' ? 'head' : 'tail',
      stripModelAdvice: adviceConfig.position === 'head' || adviceConfig.stripModelAdvice !== false,
    };
    latestAdviceTransfer = {
      chatKey,
      assistant: pair.assistant,
      user: pair.user,
      userRow: pair.userRow,
      assistantId: pair.assistant.message_id,
      userId: pair.user.message_id,
      assistantText: assistantTextWithAdvice(pair.assistant.message, userText, rewriteConfig),
      userText,
      replacementText,
      rewriteConfig,
      originalAssistant: pair.assistant.message,
      committed: false,
      persisting: false,
      persistenceState: 'staged',
      persistenceAttempts: 0,
      persistenceError: '',
      worldInfoScanned: false,
      activatedWorldInfo: [],
    };
    adviceCapturedUserText = '';
    return latestAdviceTransfer;
  }

  function recordAdviceWorldInfoScan(eventData) {
    const transfer = latestAdviceTransfer;
    if (!transfer || transfer.chatKey !== adviceChatKey()) return null;
    transfer.worldInfoScanned = true;
    try {
      const entries = eventData && eventData.activated && eventData.activated.entries;
      transfer.activatedWorldInfo = entries && typeof entries.keys === 'function'
        ? Array.from(entries.keys())
        : [];
    } catch (_) {
      transfer.activatedWorldInfo = [];
    }
    return transfer;
  }

  function invalidateAdviceTransferForUser(userId) {
    if (latestAdviceTransfer && latestAdviceTransfer.chatKey === adviceChatKey() && latestAdviceTransfer.userId === userId) {
      latestAdviceTransfer = null;
    }
  }

  function assertCurrentAdviceTransfer(transfer) {
    if (adviceRuntimeEnabled() && transfer && transfer === latestAdviceTransfer && transfer.chatKey === adviceChatKey()) return;
    const stale = new Error('advice transfer is no longer current');
    stale.code = 'IZUMI_ADVICE_STALE';
    throw stale;
  }

  async function persistAdviceTransfer(transfer, userExtra) {
    assertCurrentAdviceTransfer(transfer);
    const setMessages = hostFunction('setChatMessages');
    const context = hostContext();
    const saveChat = context && typeof context.saveChat === 'function'
      ? context.saveChat.bind(context)
      : null;
    if (!setMessages && !saveChat) throw new Error('message persistence API missing');

    if (setMessages) {
      await setMessages([
        adviceMessageUpdatePayload(transfer.assistant, transfer.assistantText),
        adviceMessageUpdatePayload(transfer.user, transfer.replacementText, userExtra),
      ], { refresh: 'affected' });
      assertCurrentAdviceTransfer(transfer);
    }
    if (saveChat) {
      await saveChat();
      assertCurrentAdviceTransfer(transfer);
    }

    const refreshOne = hostFunction('refreshOneMessage');
    if (refreshOne) {
      try {
        await refreshOne(transfer.assistantId);
        await refreshOne(transfer.userId);
      } catch (_) {}
    }
    if (adviceConfig.displayAdviceForUser) updateSingleUserMessageDisplay(transfer.userId);
  }

  async function executeAdviceTransfer(sentMessageId) {
    if (!adviceRuntimeEnabled()) return null;
    const transfer = stageAdviceTransfer(sentMessageId);
    if (!transfer || transfer.chatKey !== adviceChatKey()) return null;

    if (!transfer.committed) {
      // 世界书扫描完成之后，才同步修改当前 chat；在此之前 user 始终保留原 role 和原文供绿灯审查。
      patchAdviceContextMessage(transfer.assistantId, transfer.assistantText);
      patchAdviceContextMessage(transfer.userId, transfer.replacementText);
      transfer.userExtra = setAdviceUserMeta(transfer.userId, transfer.userText, transfer.assistantId, transfer.replacementText);
      transfer.committed = true;
      transfer.persistenceState = 'committed';
    }
    // 内存提交必须同步完成，供同一事件中的最终请求改写使用；持久化则串行执行并允许整轮仅一次重试。
    if (['persisted', 'failed', 'cancelled'].includes(transfer.persistenceState) || transfer.persisting) return transfer;
    transfer.persisting = true;
    transfer.persistenceState = 'persisting';

    let lastError = null;
    while (transfer.persistenceAttempts < 2) {
      transfer.persistenceAttempts += 1;
      const attempt = transfer.persistenceAttempts;
      try {
        await persistAdviceTransfer(transfer, transfer.userExtra);
        transfer.persistenceState = 'persisted';
        transfer.persistenceError = '';
        lastError = null;
        break;
      } catch (error) {
        if (error && error.code === 'IZUMI_ADVICE_STALE') {
          transfer.persistenceState = 'cancelled';
          transfer.persistenceError = error.message;
          lastError = null;
          break;
        }
        lastError = error;
        transfer.persistenceError = error && error.message ? error.message : String(error || 'unknown error');
        console.warn(`[Izumi floating window] advice persistence attempt ${attempt} failed`, error);
        if (attempt < 2) await lifecycle.delay(120);
      }
    }
    transfer.persisting = false;
    if (lastError) {
      transfer.persistenceState = 'failed';
      toast('Advice 本轮请求已正确改写，但聊天记录保存失败；请先别刷新页面，并查看控制台错误～', 'error');
    }
    return transfer;
  }

  function rewriteAdviceSendingMessages(messages, transfer) {
    return advice_rewriteAdviceSendingMessages(messages, transfer, adviceConfig);
  }

  // BEGIN SANITIZER

  // EJS、酒馆宏和变量更新块必须保持逐字不变，否则变量名、JSON Patch 和 MVU 状态会被零宽字符破坏。

  function readSanitizerConfig() {
    const store = storage();
    try {
      const raw = store && store.getItem(SANITIZER_CONFIG_KEY);
      if (!raw) return Object.assign({}, DEFAULT_SANITIZER_CONFIG);
      const parsed = JSON.parse(raw);
      return normalizeSanitizerConfig(parsed);
    } catch (_) {
      return Object.assign({}, DEFAULT_SANITIZER_CONFIG);
    }
  }

  let sanitizerConfig = readSanitizerConfig();

  function saveSanitizerConfig(partial) {
    sanitizerConfig = Object.assign({}, sanitizerConfig, partial);
    if (sanitizerConfig.scopeMode === 'none') {
      sanitizerConfig.inputOnlyAfterX = true;
    }
    const saved = writeStorageKey(SANITIZER_CONFIG_KEY, JSON.stringify(sanitizerConfig));
    return saved;
  }

  function readSanitizerEnabled() {
    const store = storage();
    try {
      const saved = store && store.getItem(SANITIZER_ENABLED_KEY);
      return saved == null ? true : saved !== 'false';
    } catch (_) { return true; }
  }

  let sanitizerEnabled = readSanitizerEnabled();

  function sharedSanitizerEnabled() {
    const store = storage();
    try {
      const saved = store && store.getItem(SANITIZER_ENABLED_KEY);
      return saved == null ? sanitizerEnabled === true : saved !== 'false';
    } catch (_) { return sanitizerEnabled === true; }
  }

  function sanitizerRuntimeEnabled() {
    return isCurrentIzumiInstance() && sharedSanitizerEnabled() && advicePresetMatches();
  }

  function currentChatFloor() {
    const context = hostContext();
    if (context && Array.isArray(context.chat)) return context.chat.length;
    const getMessages = hostFunction('getChatMessages');
    if (getMessages) {
      try {
        const all = getMessages('0-999999', { hide_state: 'all', include_swipes: false });
        if (Array.isArray(all)) return all.length;
      } catch (_) {}
    }
    return 0;
  }

  function sanitizerStrategyForCurrentRequest(config = sanitizerConfig, currentFloor = currentChatFloor()) {
    return sanitizer_sanitizerStrategyForCurrentRequest(config, currentFloor);
  }

  function sanitizerControlMarkup(kind) {
    const quick = kind === 'quick';
    const action = quick ? 'data-quick-sanitizer' : 'data-action="sanitizer-toggle"';
    return `<button class="advice-toggle sanitizer-toggle${quick ? ' quick-advice-toggle' : ''}" ${action} data-sanitizer-control role="switch" aria-checked="${sanitizerEnabled}" aria-pressed="${sanitizerEnabled}" title="${sanitizerEnabled ? '关闭' : '开启'} 关键词替换">`
      + `<span>关键词替换</span><i aria-hidden="true"></i><small data-sanitizer-state>${sanitizerEnabled ? '开' : '关'}</small></button>`;
  }

  function sanitizerSettingsButtonMarkup(kind) {
    const quick = kind === 'quick';
    const action = quick ? 'data-quick-sanitizer-settings' : 'data-action="sanitizer-settings"';
    return `<button class="icon-btn small advice-settings-btn sanitizer-settings-btn" ${action} title="关键词替换设置" aria-label="关键词替换设置">⚙</button>`;
  }

  function updateSanitizerControls() {
    pdoc.querySelectorAll('[data-sanitizer-control]').forEach((control) => {
      control.setAttribute('aria-checked', String(sanitizerEnabled));
      control.setAttribute('aria-pressed', String(sanitizerEnabled));
