  }

  function setSanitizerEnabled(value, announce = true) {
    sanitizerEnabled = value === true;
    const saved = writeStorageKey(SANITIZER_ENABLED_KEY, String(sanitizerEnabled));
    updateSanitizerControls();
    if (announce) {
      if (saved) toast(`关键词替换已${sanitizerEnabled ? '开启' : '关闭'}～`, 'success');
      else toast(`关键词替换本次已${sanitizerEnabled ? '开启' : '关闭'}，但状态未能保存`, 'error');
    }
    return sanitizerEnabled;
