  function openSanitizerSettingsDialog(panel) {
    const overlay = pdoc.getElementById(`${ID}-sanitizer-dialog`);
    if (!overlay || !panel) return;
    const modeSelect = pdoc.getElementById(`${ID}-sanitizer-mode-select`);
    const thresholdInput = pdoc.getElementById(`${ID}-sanitizer-threshold-input`);
    const inputOnlyCheck = pdoc.getElementById(`${ID}-sanitizer-input-only-check`);
    const reverseCheck = pdoc.getElementById(`${ID}-sanitizer-reverse-check`);
    if (modeSelect) modeSelect.value = sanitizerConfig.scopeMode || 'first_x';
    if (thresholdInput) thresholdInput.value = String(sanitizerConfig.threshold || 10);
    if (inputOnlyCheck) {
