  function saveSanitizerSettingsDialog(panel) {
    const modeSelect = pdoc.getElementById(`${ID}-sanitizer-mode-select`);
    const thresholdInput = pdoc.getElementById(`${ID}-sanitizer-threshold-input`);
    const inputOnlyCheck = pdoc.getElementById(`${ID}-sanitizer-input-only-check`);
    const reverseCheck = pdoc.getElementById(`${ID}-sanitizer-reverse-check`);

    const nextMode = modeSelect && ['first_x', 'forever', 'none'].includes(modeSelect.value)
      ? modeSelect.value
      : 'first_x';
    const nextThreshold = Math.max(1, Math.min(9999, Number(thresholdInput && thresholdInput.value) || 10));
    const nextInputOnly = nextMode === 'none' ? true : (inputOnlyCheck ? inputOnlyCheck.checked : true);
    const nextReverse = reverseCheck ? reverseCheck.checked : true;

    const saved = saveSanitizerConfig({
      scopeMode: nextMode,
      threshold: nextThreshold,
      inputOnlyAfterX: nextInputOnly,
      reverseEnabled: nextReverse,
    });
    closeSanitizerSettingsDialog(panel);
    toast(saved ? '关键词替换设置已保存～' : '设置本次已生效，但未能保存到浏览器', saved ? 'success' : 'error');
  }

  function restoreIncomingSanitizedTextInChat(messageIndex) {
    if (!sanitizerRuntimeEnabled() || !sanitizerConfig.reverseEnabled) return false;
    try {
      const ctx = hostContext();
      if (!ctx || !Array.isArray(ctx.chat) || !ctx.chat.length) return false;
      const idx = Number.isInteger(Number(messageIndex)) ? Number(messageIndex) : ctx.chat.length - 1;
      const message = ctx.chat[idx];
      if (!message || message.is_user || !message.mes) return false;
      const orig = String(message.mes);
      const restored = reverseSanitizedText(orig);
      if (restored === orig) return false;

      // 同步修正当前 swipe；必须在 MESSAGE_RECEIVED 的 makeFirst 回调中同步完成，供 MVU/EJS 后续监听读取。
      message.mes = restored;
      const swipeId = Number(message.swipe_id);
      if (Array.isArray(message.swipes) && Number.isInteger(swipeId) && swipeId >= 0) {
        message.swipes[swipeId] = restored;
      }

      const refreshOne = hostFunction('refreshOneMessage');
      if (refreshOne) {
        try { Promise.resolve(refreshOne(idx)).catch(() => {}); } catch (_) {}
      }
      try {
        const saveChatDebounced = hostFunction('saveChatDebounced');
        if (saveChatDebounced) saveChatDebounced();
        else if (typeof ctx.saveChat === 'function') Promise.resolve(ctx.saveChat()).catch(() => {});
      } catch (_) {}
      return true;
    } catch (error) {
      console.warn('[Izumi floating window] sanitizer reverse restore failed', error);
      return false;
    }
  }
  // END SANITIZER


  function bindAdviceInterception() {
    const context = hostContext();
    const eventSource = context && context.eventSource;
    const eventTypes = context && context.eventTypes || {};
    const listeners = [];

    const removeRecord = (record) => {
      if (!record) return;
      if (record.subscription && typeof record.subscription.stop === 'function') {
        try { record.subscription.stop(); } catch (_) {}
      }
      if (eventSource && typeof eventSource.removeListener === 'function' && record.type && record.callback) {
        try { eventSource.removeListener(record.type, record.callback); } catch (_) {}
      }
    };

    const subscribe = (method, type, listener, options = {}) => {
      if (!eventSource || typeof eventSource[method] !== 'function') return null;
      const callback = (...args) => {
        const enabled = options.allowPresetMismatch
          ? isCurrentIzumiInstance()
          : options.sharedSanitizer
            ? adviceRuntimeEnabled() || sanitizerRuntimeEnabled()
            : adviceRuntimeEnabled();
        if (!enabled) return;
        listener(...args);
      };
      const subscription = eventSource[method](type, callback);
      const record = { type, callback, subscription };
      listeners.push(record);
      return record;
    };

    try {
      if (eventSource && typeof eventSource.on === 'function') {
        subscribe('on', eventTypes.GENERATION_STARTED || 'generation_started', (_type, _options, dryRun) => {
          if (!dryRun) regexLinkageGenerating = true;
        }, { allowPresetMismatch: true });
        for (const type of [eventTypes.GENERATION_ENDED || 'generation_ended', eventTypes.GENERATION_STOPPED || 'generation_stopped']) {
          subscribe('on', type, () => { regexLinkageGenerating = false; scheduleRegexLinkage(); }, { allowPresetMismatch: true });
        }
        subscribe('on', eventTypes.MESSAGE_SENT || 'message_sent', (messageId) => {
          // 必须在替换前立刻解析；之后 {{lastUserMessage}} 会变成固定占位句。
          adviceCapturedUserText = adviceLastUserMessageMacro();
          // 只缓存原 user；世界书扫描完成前绝不修改聊天内容。
          stageAdviceTransfer(messageId, adviceCapturedUserText, { newlySent: true });
        });

        subscribe('on', eventTypes.GENERATION_AFTER_COMMANDS || 'GENERATION_AFTER_COMMANDS', (_type, _option, dryRun) => {
          if (dryRun === true) return;
          stageAdviceTransfer(undefined);
        });

        subscribe('on', eventTypes.WORLDINFO_SCAN_DONE || 'worldinfo_scan_done', (eventData) => {
          recordAdviceWorldInfoScan(eventData);
        });

        subscribe(typeof eventSource.makeLast === 'function' ? 'makeLast' : 'on', eventTypes.WORLD_INFO_ACTIVATED || 'world_info_activated', (entries) => {
          const transfer = stageAdviceTransfer(undefined);
          if (!transfer) return;
          transfer.worldInfoScanned = true;
          try {
            transfer.activatedWorldInfo = Array.isArray(entries)
              ? entries.map((entry) => `${entry.world || ''}.${entry.uid == null ? '' : entry.uid}`)
              : transfer.activatedWorldInfo;
          } catch (_) {}
          executeAdviceTransfer(transfer.userId);
        });

        const rewritePayload = (messages, dryRun, finalStage) => {
          if (dryRun === true) return;
          const transfer = adviceRuntimeEnabled() ? stageAdviceTransfer(undefined) || latestAdviceTransfer : null;
          if (transfer) {
            // 只有确认世界书已扫描，或已进入保证晚于世界书的最终阶段，才提交搬运。
            if (!transfer.committed && (transfer.worldInfoScanned || finalStage)) {
              executeAdviceTransfer(transfer.userId);
            }
            if (transfer.committed) rewriteAdviceSendingMessages(messages, transfer);
          }
          if (sanitizerRuntimeEnabled()) {
            const strategy = sanitizerStrategyForCurrentRequest(sanitizerConfig, currentChatFloor());
            rewriteSanitizerSendingMessages(messages, strategy, transfer);
          }
        };

        subscribe(typeof eventSource.makeLast === 'function' ? 'makeLast' : 'on', eventTypes.GENERATE_AFTER_DATA || 'generate_after_data', (generateData, dryRun) => {
          rewritePayload(generateData && generateData.prompt, dryRun, true);
        }, { sharedSanitizer: true });
        subscribe(typeof eventSource.makeLast === 'function' ? 'makeLast' : 'on', eventTypes.CHAT_COMPLETION_SETTINGS_READY || 'chat_completion_settings_ready', (generateData) => {
          rewritePayload(generateData && generateData.messages, false, false);
        }, { sharedSanitizer: true });
        subscribe(typeof eventSource.makeLast === 'function' ? 'makeLast' : 'on', eventTypes.CHAT_COMPLETION_PROMPT_READY || 'chat_completion_prompt_ready', (eventData) => {
          rewritePayload(eventData && eventData.chat, eventData && eventData.dryRun, true);
        }, { sharedSanitizer: true });

        subscribe(typeof eventSource.makeFirst === 'function' ? 'makeFirst' : 'on', eventTypes.MESSAGE_RECEIVED || 'message_received', (messageId) => {
          restoreIncomingSanitizedTextInChat(messageId);
        }, { sharedSanitizer: true });
        subscribe(typeof eventSource.makeFirst === 'function' ? 'makeFirst' : 'on', eventTypes.MESSAGE_SWIPED || 'message_swiped', (messageId) => {
          restoreIncomingSanitizedTextInChat(messageId);
        }, { sharedSanitizer: true });
        subscribe(typeof eventSource.makeFirst === 'function' ? 'makeFirst' : 'on', eventTypes.GENERATION_ENDED || 'generation_ended', (messageId) => {
          restoreIncomingSanitizedTextInChat(messageId);
          latestAdviceTransfer = null;
          adviceCapturedUserText = '';
        }, { sharedSanitizer: true });
        subscribe('on', eventTypes.GENERATION_STOPPED || 'generation_stopped', () => {
          latestAdviceTransfer = null;
          adviceCapturedUserText = '';
        });
        subscribe(typeof eventSource.makeFirst === 'function' ? 'makeFirst' : 'on', eventTypes.MESSAGE_EDITED || 'message_edited', (messageId) => {
          // 最先执行；函数会在第一次 await 前同步修正内存 chat，兼容“保存并重新生成”。
          syncAdviceAfterMessageEdit(messageId);
        });
        subscribe('on', eventTypes.USER_MESSAGE_RENDERED || 'user_message_rendered', (messageId) => {
          if (adviceConfig.displayAdviceForUser && Number.isInteger(Number(messageId))) {
            updateSingleUserMessageDisplay(Number(messageId));
          }
        });
        subscribe('on', eventTypes.MORE_MESSAGES_LOADED || 'more_messages_loaded', () => {
          if (adviceConfig.displayAdviceForUser) updateAdviceDisplayInChat();
        });
        subscribe('on', eventTypes.CHAT_CHANGED || 'chat_id_changed', () => {
          latestAdviceTransfer = null;
          adviceCapturedUserText = '';
          adviceUserEditDrafts.clear();
          adviceEditSyncing = false;
          advicePendingEditedMessageId = null;
          if (adviceConfig.displayAdviceForUser) setTimeout(updateAdviceDisplayInChat, 200);
        });

        const stopOnPresetSwitch = () => {
          // Invalidate queued display work immediately, even for a rapid A → B → A transition.
          if (adviceDisplayCompat) adviceDisplayCompat.reset();
          // 部分预设事件会早于选择器/context 更新；下一任务再确认，避免保存同一预设时误清理。
          setTimeout(() => {
            if (!isCurrentIzumiInstance()) return;
            const current = normalizeName(presetName());
            if (!adviceOwnerPreset || !current || current !== adviceOwnerPreset) cleanup();
          }, 80);
        };
        subscribe('on', eventTypes.OAI_PRESET_CHANGED_AFTER || 'oai_preset_changed_after', stopOnPresetSwitch, { allowPresetMismatch: true });
        subscribe('on', eventTypes.PRESET_CHANGED || 'preset_changed', stopOnPresetSwitch, { allowPresetMismatch: true });
      } else {
        const fallback = hostFunction('eventOn');
        if (!fallback) throw new Error('event API missing');
        const sentCallback = (messageId) => {
          if (!adviceRuntimeEnabled()) return;
          adviceCapturedUserText = adviceLastUserMessageMacro();
          stageAdviceTransfer(messageId, adviceCapturedUserText, { newlySent: true });
          executeAdviceTransfer(messageId);
        };
        const editedCallback = (messageId) => {
          if (!adviceRuntimeEnabled()) return;
          syncAdviceAfterMessageEdit(messageId);
        };
        const sentSubscription = fallback('message_sent', sentCallback);
        const editedSubscription = fallback('message_edited', editedCallback);
        listeners.push({ type: 'message_sent', callback: sentCallback, subscription: sentSubscription });
        listeners.push({ type: 'message_edited', callback: editedCallback, subscription: editedSubscription });
      }
    } catch (error) {
      listeners.splice(0).forEach(removeRecord);
      adviceApiWarningShown = true;
      console.warn('[Izumi floating window] advice interception bind failed', error);
      return null;
    }

    return {
      stop() {
        listeners.splice(0).forEach(removeRecord);
      },
    };
  }

  function normalizeModels(value) {
    let parsed = value;
    if (typeof parsed === 'string') {
      try { parsed = JSON.parse(parsed); } catch (_) {
        parsed = parsed.split(/[\r\n,]+/);
      }
    }
    const list = Array.isArray(parsed)
      ? parsed
      : parsed && Array.isArray(parsed.data)
        ? parsed.data
        : parsed && Array.isArray(parsed.models)
          ? parsed.models
          : [];
    return Array.from(new Set(list.map((item) => {
      if (typeof item === 'string') return item.trim();
      if (!item || typeof item !== 'object') return '';
      return String(item.id || item.name || item.model || '').trim();
    }).filter(Boolean))).slice(0, 500);
  }

  async function fetchModelList(config) {
    const context = hostContext();
    if (!context || context.mainApi !== 'openai' || !context.chatCompletionSettings) {
      throw new Error('酒馆现在不是聊天补全模式，拉不了模型～');
    }
    if (typeof context.getRequestHeaders !== 'function') throw new Error('酒馆请求头接口不可用');
    const settings = context.chatCompletionSettings;
    const source = config.source || settings.chat_completion_source;
    if (source === 'custom' && !config.apiUrl && !settings.custom_url) throw new Error('请先在酒馆填写自定义端点');
    const body = {
      reverse_proxy: settings.reverse_proxy || '',
      proxy_password: settings.proxy_password || '',
      chat_completion_source: source,
    };
    if (source === 'custom') {
      body.custom_url = config.apiUrl || settings.custom_url;
      body.custom_include_headers = config.includeHeaders || settings.custom_include_headers || '';
    }
    if (source === 'azure_openai') {
      body.azure_base_url = settings.azure_base_url || '';
      body.azure_deployment_name = settings.azure_deployment_name || '';
      body.azure_api_version = settings.azure_api_version || '';
    }
    if (source === 'siliconflow') body.siliconflow_endpoint = settings.siliconflow_endpoint || '';
    if (source === 'minimax') body.minimax_endpoint = settings.minimax_endpoint || '';
    if (source === 'workers_ai') body.workers_ai_account_id = settings.workers_ai_account_id || '';
    const fetcher = pwin && typeof pwin.fetch === 'function'
      ? pwin.fetch.bind(pwin)
      : (typeof fetch === 'function' ? fetch.bind(globalThis) : null);
    if (!fetcher) throw new Error('这个环境拿不到酒馆的模型接口～');
    const controller = typeof AbortController === 'function' ? new AbortController() : null;
    const timer = controller ? setTimeout(() => controller.abort(), 15000) : null;
    try {
      const response = await fetcher('/api/backends/chat-completions/status', {
        method: 'POST',
        headers: context.getRequestHeaders(),
        body: JSON.stringify(body),
        cache: 'no-cache',
        signal: controller ? controller.signal : undefined,
      });
      if (!response.ok) throw new Error(`酒馆模型接口返回 ${response.status}`);
      const payload = await response.json();
      if (payload && payload.error) {
        const message = typeof payload.error === 'string' ? payload.error : payload.error.message;
        throw new Error(message || '酒馆连接校验失败');
      }
      return normalizeModels(payload);
    } catch (error) {
      if (error && error.name === 'AbortError') throw new Error('模型列表请求超时');
      throw error;
    } finally {
      if (timer) clearTimeout(timer);
    }
  }

  function configText(value, arrayStyle) {
    if (typeof value === 'string') return value;
    if (Array.isArray(value)) {
      return arrayStyle ? value.map((item) => `- ${String(item)}`).join('\n') : JSON.stringify(value, null, 2);
    }
    if (value && typeof value === 'object') return JSON.stringify(value, null, 2);
    return '';
  }

