      excludeBody: configText(value.excludeBody == null ? (value.custom_exclude_body == null ? value.exclude : value.custom_exclude_body) : value.excludeBody, true),
      includeHeaders: configText(value.includeHeaders == null ? (value.custom_include_headers == null ? value.headers : value.custom_include_headers) : value.includeHeaders, false),
