  function ownStorageKeys() {
    return new Set([SANITIZER_ENABLED_KEY, SANITIZER_CONFIG_KEY, WORDFLOW_KEY, STORAGE_KEY, LAYER_PLAN_KEY, LAYER_PLAN_GUIDE_KEY, SESSION_SNAPSHOT_KEY, QUICK_SLOTS_KEY, ADVICE_ENABLED_KEY, ADVICE_CONFIG_KEY,
