  // 生成一份纯文本占用报告，丢进导出弹窗里看。
  function storageReport() {
    const rows = storageBreakdown();
    const total = rows.reduce((sum, row) => sum + row.chars, 0);
    const mine = ownStorageKeys();
    const mineTotal = rows.filter((row) => mine.has(row.key)).reduce((sum, row) => sum + row.chars, 0);
    const pct = (value) => (total ? Math.round((value / total) * 100) : 0);
    const fmt = (chars) => `${(chars / 1048576).toFixed(2)} M 字符`;
    const lines = [
      '=== localStorage 占用报告 ===',
      `站点：${(pwin.location && pwin.location.host) || '未知'}`,
      `时间：${new Date().toLocaleString()}`,
      '',
      `总占用：${fmt(total)}　（多数浏览器上限约 5 M 字符）`,
      `本脚本占用：${fmt(mineTotal)}　占总量 ${pct(mineTotal)}%`,
      `其它程序占用：${fmt(total - mineTotal)}　占总量 ${pct(total - mineTotal)}%`,
      `键总数：${rows.length}`,
      '',
      '--- 按「键名族群」排（找元凶看这里）---',
    ];
    const groups = storageGroups(rows);
    groups.slice(0, 20).forEach((group, index) => {
      const own = mine.has(group.prefix);
      const flag = own ? '   ←本脚本' : (group.count >= 500 ? '   ←疑似垃圾堆积' : '');
      lines.push(`${String(index + 1).padStart(2)}. ${fmt(group.chars).padStart(14)}  ${String(pct(group.chars)).padStart(3)}%  ${String(group.count).padStart(7)} 个键  ${group.prefix}${group.count > 1 ? '*' : ''}${flag}`);
    });
    if (groups.length > 20) lines.push(`… 其余 ${groups.length - 20} 个族群`);
    lines.push('', '--- 单个最大的键 ---');
    rows.slice(0, 15).forEach((row, index) => {
      lines.push(`${String(index + 1).padStart(2)}. ${fmt(row.chars).padStart(14)}  ${row.key}${mine.has(row.key) ? '   ←本脚本' : ''}`);
    });
    lines.push('',
      '说明：键名本身也算进配额。几十万个小键即使值是空的，光键名就能占满 5 M。',
      '如果看到某个族群有成千上万个键，多半是某个扩展/前端卡在给每条消息写记录且从不清理。',
      '可以用方案区的「清理垃圾键」按前缀批量删除（本脚本自己的键不会被删）。');
    return lines.join('\n');
  }

  function storageFailureMessage(prefix) {
    if (!storage()) return `${prefix}：浏览器不允许本站使用 localStorage`;
    const rows = storageBreakdown();
    const total = rows.reduce((sum, row) => sum + row.chars, 0);
    const mine = ownStorageKeys();
    const mineTotal = rows.filter((row) => mine.has(row.key)).reduce((sum, row) => sum + row.chars, 0);
    if (isQuotaError(storageService.lastError)) {
      const share = total ? Math.round((mineTotal / total) * 100) : 0;
      return `${prefix}：存储已满（共 ${formatBytes(total)}，本脚本只占 ${share}%）。点方案区「存储详情」看是谁占的`;
    }
    const name = storageService.lastError && storageService.lastError.name ? storageService.lastError.name : '未知错误';
    return `${prefix}：写入被拒（${name}，共 ${formatBytes(total)}）`;
  }

