  const DEFAULT_ADVICE_CONFIG = {
    position: 'tail',
    stripModelAdvice: true,
    displayAdviceForUser: true,
    frontendCompatEnabled: true,
    replacementText: ADVICE_CONTINUE_TEXT,
  };

  function readAdviceConfig() {
    const store = storage();
    try {
      const raw = store && store.getItem(ADVICE_CONFIG_KEY);
      if (!raw) return Object.assign({}, DEFAULT_ADVICE_CONFIG);
      const parsed = JSON.parse(raw);
      const position = parsed && parsed.position === 'head' ? 'head' : 'tail';
      return {
        position,
        stripModelAdvice: position === 'head'
          ? true
          : (parsed && typeof parsed.stripModelAdvice === 'boolean' ? parsed.stripModelAdvice : true),
        displayAdviceForUser: parsed && typeof parsed.displayAdviceForUser === 'boolean' ? parsed.displayAdviceForUser : true,
        frontendCompatEnabled: parsed && typeof parsed.frontendCompatEnabled === 'boolean' ? parsed.frontendCompatEnabled : true,
        replacementText: normalizeReplacementText(parsed && parsed.replacementText),
      };
    } catch (_) {
      return Object.assign({}, DEFAULT_ADVICE_CONFIG);
    }
  }

  let adviceConfig = readAdviceConfig();

  function saveAdviceConfig(partial) {
    const previousDisplay = adviceConfig.displayAdviceForUser;
    const previousCompat = adviceConfig.frontendCompatEnabled;
    adviceConfig = Object.assign({}, adviceConfig, partial);
    if (adviceConfig.position === 'head') {
      adviceConfig.stripModelAdvice = true;
    }
    adviceConfig.replacementText = normalizeReplacementText(adviceConfig.replacementText);
    const saved = writeStorageKey(ADVICE_CONFIG_KEY, JSON.stringify(adviceConfig));
    // Only a changed display gate renews the compatibility epoch, not a new replacement sentence.
    if (previousDisplay !== adviceConfig.displayAdviceForUser || previousCompat !== adviceConfig.frontendCompatEnabled) {
      if (adviceDisplayCompat) adviceDisplayCompat.reset();
    }
    updateAdviceDisplayInChat();
    return saved;
  }

  function readAdviceEnabled() {
    const store = storage();
    try {
      const saved = store && store.getItem(ADVICE_ENABLED_KEY);
      return saved == null ? true : saved !== 'false';
    } catch (_) { return true; }
  }

