  // Runtime owns the Advice authorization; the service only requests bounded host display work.
  function adviceFrontendCompatScope() {
    try {
      const context = hostContext();
      if (!context || !Array.isArray(context.chat)) return null;
      const rawChatId = context.chatId
        || (typeof context.getCurrentChatId === 'function' ? context.getCurrentChatId() : '');
      if (typeof rawChatId !== 'string' && typeof rawChatId !== 'number') return null;
      const chatId = normalizeName(rawChatId);
      if (!chatId) return null;
      const characterId = normalizeName(context.groupId || context.characterId);
      return { chatKey: `${characterId}|${chatId}`, chat: context.chat, eventSource: context.eventSource };
    } catch (_) { return null; }
  }

  function adviceFrontendCompatEnabled() {
    if (!adviceRuntimeEnabled() || adviceConfig.displayAdviceForUser !== true || adviceConfig.frontendCompatEnabled !== true) return false;
    try {
      // This is Helper's HTML streaming setting, not the model's streaming-output option.
      const render = hostContext()?.extensionSettings?.tavern_helper?.render;
      return render?.enabled !== false && render?.allow_streaming !== true;
    } catch (_) { return false; }
  }

  function identifyAdviceFrontendDisplay(mesText) {
    try {
      const scope = adviceFrontendCompatScope();
      const root = pdoc.querySelector('#chat');
      const message = mesText?.closest('.mes');
      if (!scope || !root || root.isConnected === false || !message || message.parentElement !== root
        || !message.matches('.mes[mesid]') || !mesText.matches('.mes_text') || mesText.isConnected === false
        || message.querySelector('.mes_text') !== mesText
        || message.matches('.editing, .mes_editing')
        || message.matches('[contenteditable]:not([contenteditable="false"])')
        || message.querySelector('textarea, [contenteditable]:not([contenteditable="false"])')) return null;
      const rawId = message.getAttribute('mesid');
      if (typeof rawId !== 'string' || !/^\d+$/.test(rawId)) return null;
      const id = Number(rawId);
      if (!Number.isSafeInteger(id)) return null;
      const row = scope.chat[id];
      if (!row || row.is_user !== true || row.is_system || contextChatMessageRole(row) !== 'user') return null;
      const record = adviceRecordForUser(id);
      if (!adviceRowIsReplacement(row, record)) return null;
      return {
        id, row, message, mesText, source: record.text, revision: record.revision, replacement: record.replacementText,
        instanceToken: INSTANCE_TOKEN, ownerPreset: adviceOwnerPreset,
      };
    } catch (_) { return null; }
  }

  function isCurrentAdviceFrontendJob(job) {
    if (!job || !isCurrentIzumiInstance() || !adviceFrontendCompatEnabled()
      || job.instanceToken !== INSTANCE_TOKEN || job.ownerPreset !== adviceOwnerPreset) return false;
    const scope = adviceFrontendCompatScope();
    if (!scope || scope.chat !== job.chat || scope.chatKey !== job.chatKey) return false;
    const current = identifyAdviceFrontendDisplay(job.mesText);
    return !!current && current.id === job.id && current.row === job.row
      && current.message === job.message && current.mesText === job.mesText
      && current.source === job.source && current.revision === job.revision && current.replacement === job.replacement;
  }

  function startAdviceFrontendCompat() {
    if (adviceDisplayCompat) return;
    try {
      const context = hostContext();
      const source = context?.eventSource;
      const subscribe = typeof source?.makeLast === 'function' ? source.makeLast : source?.on;
      const Observer = pwin.MutationObserver;
      // Global Helper scripts can start on the welcome page. Keep the service dormant
      // without a scope so its non-gated CHAT_CHANGED listener can activate it later.
      if (!pdoc || typeof pdoc.querySelector !== 'function'
        || typeof Observer !== 'function' || typeof subscribe !== 'function'
        || typeof source?.emit !== 'function' || typeof source?.removeListener !== 'function') return;
      const types = context.eventTypes || {};
      const getScope = () => {
        const scope = adviceFrontendCompatScope();
        return scope?.eventSource === source ? scope : null;
      };
      const service = createAdviceDisplayCompat({
        doc: pdoc,
        getChatRoot: () => pdoc.querySelector('#chat'),
        getScope,
        isEnabled: () => !!getScope() && adviceFrontendCompatEnabled(),
        identify: identifyAdviceFrontendDisplay,
        isCurrentJob: job => !!getScope() && isCurrentAdviceFrontendJob(job),
        createMutationObserver: callback => new Observer(callback),
        setTimeout, clearTimeout,
        // Preserve host receivers and Promise returns; never use the Advice listener wrapper.
        subscribeLast: (type, callback) => {
          const subscription = subscribe.call(source, type, callback);
          return () => {
            try { if (subscription && typeof subscription.stop === 'function') subscription.stop(); } catch (_) {}
            try { source.removeListener(type, callback); } catch (_) {}
          };
        },
        emit: (type, ...args) => source.emit(type, ...args),
        eventTypes: {
          MESSAGE_UPDATED: types.MESSAGE_UPDATED || 'message_updated',
          USER_MESSAGE_RENDERED: types.USER_MESSAGE_RENDERED || 'user_message_rendered',
          CHAT_CHANGED: types.CHAT_CHANGED || 'chat_id_changed',
        },
        hasLegacyCompat: () => {
          const legacy = pwin.__izumiFrontendCompatV1;
          return legacy !== null && (typeof legacy === 'object' || typeof legacy === 'function');
        },
        warn: () => console.warn('[Izumi compatibility] Frontend display was not restored; automatic retries stopped.'),
      });
      adviceDisplayCompat = service;
      lifecycle.add(() => { service.stop(); if (adviceDisplayCompat === service) adviceDisplayCompat = null; });
      service.start();
    } catch (_) { /* Missing display capabilities must never affect Advice transfer or settings. */ }
  }

  function updateSingleUserMessageDisplay(messageId) {
    if (!adviceRuntimeEnabled() || !adviceConfig.displayAdviceForUser) return;
    const context = hostContext();
    const chat = context && Array.isArray(context.chat) ? context.chat : null;
    if (!chat || !chat.length) return;
    const userRow = chat[messageId];
    const adviceData = adviceRecordForUser(messageId);
    if (!adviceRowIsReplacement(userRow, adviceData)) return;
    const adviceContent = adviceData.text;

    let mesText = pdoc.querySelector(`#chat .mes[mesid="${messageId}"] .mes_text`);
    if (!mesText) {
      const retrieve = hostFunction('retrieveDisplayedMessage');
      try {
        const displayed = retrieve && retrieve(messageId);
        const candidate = displayed && (displayed[0] || (typeof displayed.get === 'function' && displayed.get(0)));
        mesText = candidate && (candidate.matches && candidate.matches('.mes_text')
          ? candidate
          : candidate.querySelector && candidate.querySelector('.mes_text')) || candidate || null;
      } catch (_) {}
    }
    if (!mesText) return;

    // 只改可见 DOM，不写回消息。优先使用酒馆自己的消息格式化器，得到正常的 Markdown、段落与换行。
    const formatter = hostFunction('formatAsDisplayedMessage');
    let formatted = '';
    try {
      formatted = formatter ? String(formatter(adviceContent, { message_id: messageId }) || '') : '';
    } catch (_) {}
    if (formatted) {
      mesText.innerHTML = formatted;
      if (mesText.style) {
        mesText.style.removeProperty('white-space');
        mesText.style.removeProperty('overflow-wrap');
      }
      if (mesText.dataset) mesText.dataset.izumiAdviceDisplay = 'formatted';
      // The service only schedules here; never emit recursively from the DOM write.
      if (adviceDisplayCompat) adviceDisplayCompat.notifyDisplayCompleted(messageId);
    } else {
      // 极旧环境回退为纯文本，同时保留换行和连续空格，不解释用户输入中的 HTML。
      mesText.textContent = adviceContent;
      if (mesText.style) {
        mesText.style.whiteSpace = 'pre-wrap';
        mesText.style.overflowWrap = 'anywhere';
      }
      if (mesText.dataset) mesText.dataset.izumiAdviceDisplay = 'plain';
    }
  }

