  function setAdviceNativeEditorValue(editor, text) {
    if (!editor) return false;
    const value = String(text == null ? '' : text);
    try {
      if ('value' in editor) editor.value = value;
      else if (editor.isContentEditable) editor.textContent = value;
      else return false;
      // 这里只是把冗余 Advice 预填进编辑器，不能伪造 input/change。
      // 部分 runOnEdit 正则会把程序化 input 当成真实编辑并提前处理消息，导致尚未保存就污染 assistant 正文。
      if (typeof editor.setSelectionRange === 'function') editor.setSelectionRange(value.length, value.length);
      return true;
    } catch (_) { return false; }
  }

  function handleAdviceEditorFocus(event) {
    if (!adviceRuntimeEnabled()) return;
    const editor = event && event.target;
    if (!editor || (panel && panel.contains(editor))) return;
    const isEditor = editor.matches && editor.matches('textarea, [contenteditable="true"]');
    if (!isEditor) return;
    const messageId = adviceMessageIdFromElement(editor);
