    const editorText = 'value' in editor ? String(editor.value || '') : String(editor.textContent || '');
    if (editorText && editorText !== data.replacementText && editorText !== data.text) return;
    adviceUserEditDrafts.clear();
    adviceUserEditDrafts.set(messageId, {
      assistantId: data.assistantId,
      text: data.text,
      replacementText: data.replacementText,
      chatKey: adviceChatKey(),
      editor,
      startedAt: Date.now(),
    });
    if (!editorText || editorText === data.replacementText) setAdviceNativeEditorValue(editor, data.text);
    // 部分酒馆版本会在 focusin 后才灌入原始正文；仅当它又变回空白/固定句时补填一次。
    setTimeout(() => {
