  async function syncAdviceFromUserEdit(messageId, row, draft) {
    const context = hostContext();
    const chat = context && Array.isArray(context.chat) ? context.chat : null;
    if (!chat || !row) return;
    const record = adviceRecordForUser(messageId);
    if (!record) return;
    const assistantId = record.assistantId;
    if (assistantId < 0 || !chat[assistantId]) return;
    let editedText = String(row.mes == null ? '' : row.mes);
    let hasEditorValue = false;
    if (editedText === record.replacementText && draft && draft.editor) {
      try {
        const editorText = 'value' in draft.editor
          ? String(draft.editor.value == null ? '' : draft.editor.value)
          : String(draft.editor.textContent == null ? '' : draft.editor.textContent);
        editedText = editorText;
        hasEditorValue = true;
      } catch (_) {}
    }
    if (editedText === record.replacementText && !hasEditorValue) {
      if (adviceConfig.displayAdviceForUser) updateSingleUserMessageDisplay(messageId);
      return;
    }
    const oldUserText = draft && typeof draft.text === 'string' ? draft.text : record.text;
    const nextAssistantText = replaceUserAdviceAfterEdit(chat[assistantId].mes, editedText, oldUserText, true);
    invalidateAdviceTransferForUser(messageId);
    patchAdviceContextMessage(assistantId, nextAssistantText);
    patchAdviceContextMessage(messageId, record.replacementText);
    const userExtra = setAdviceUserMeta(messageId, editedText, assistantId, record.replacementText);
    const setMessages = hostFunction('setChatMessages');
    if (setMessages) {
      await setMessages([
        adviceMessageUpdatePayload({ message_id: assistantId, role: 'assistant' }, nextAssistantText),
        adviceMessageUpdatePayload({ message_id: messageId, role: 'user' }, record.replacementText, userExtra),
      ], { refresh: 'affected' });
    }
    const refreshOne = hostFunction('refreshOneMessage');
    if (refreshOne) {
      try { await refreshOne(assistantId); await refreshOne(messageId); } catch (_) {}
    }
    if (adviceConfig.displayAdviceForUser) updateSingleUserMessageDisplay(messageId);
    if (context && typeof context.saveChat === 'function') await context.saveChat();
  }

  async function syncAdviceFromAssistantEdit(messageId, row) {
    const context = hostContext();
    const chat = context && Array.isArray(context.chat) ? context.chat : null;
    if (!chat || !row) return;
    const userId = pairedAdviceUserId(messageId);
    if (userId < 0 || !chat[userId]) return;
    const record = adviceRecordForUser(userId);
    if (!record) return;
    const state = adviceTagState(row.mes);
    // AI 编辑时完全删掉 Advice 视为暂不覆盖冗余副本；显式空标签则会同步为空。
    if (!state.found) return;
    invalidateAdviceTransferForUser(userId);
    patchAdviceContextMessage(userId, record.replacementText);
    const userExtra = setAdviceUserMeta(userId, state.text, messageId, record.replacementText);
    const setMessages = hostFunction('setChatMessages');
    if (setMessages) {
      await setMessages([
        adviceMessageUpdatePayload({ message_id: userId, role: 'user' }, record.replacementText, userExtra),
      ], { refresh: 'affected' });
    }
    const refreshOne = hostFunction('refreshOneMessage');
    if (refreshOne) {
