    if (adviceConfig.displayAdviceForUser) updateSingleUserMessageDisplay(userId);
    if (context && typeof context.saveChat === 'function') await context.saveChat();
  }

  async function syncAdviceAfterMessageEdit(messageId) {
    if (!adviceRuntimeEnabled()) return;
    const id = Number(messageId);
    if (adviceEditSyncing) {
      if (Number.isInteger(id)) advicePendingEditedMessageId = id;
      return;
    }
    if (!Number.isInteger(id)) return;
    const context = hostContext();
    const chat = context && Array.isArray(context.chat) ? context.chat : null;
    const row = chat && chat[id];
    if (!row) return;
    const role = contextChatMessageRole(row);
    const draft = adviceUserEditDrafts.get(id);
    if (role === 'user' && !adviceRecordForUser(id)) return;
    adviceEditSyncing = true;
    try {
      if (role === 'user') await syncAdviceFromUserEdit(id, row, draft);
      else if (role === 'assistant') await syncAdviceFromAssistantEdit(id, row);
    } catch (error) {
      console.warn('[Izumi floating window] advice edit sync failed', error);
      toast('Advice 双向同步失败了，原编辑内容没有主动删除～', 'error');
    } finally {
      adviceUserEditDrafts.delete(id);
      adviceEditSyncing = false;
      if (advicePendingEditedMessageId !== null) {
        const pendingId = advicePendingEditedMessageId;
        advicePendingEditedMessageId = null;
        Promise.resolve().then(() => syncAdviceAfterMessageEdit(pendingId));
      }
    }
  }

