  // BEGIN REGEX LINKAGE: only named preset regex toggles, never regex text or chat data.

  let regexLinkageTimer = null;
  let regexLinkageSignature = '';
  let regexLinkagePending = false;
  let regexLinkageGenerating = false;
  let regexLinkageWarning = '';
  let regexLinkageRevision = 0;

  function scheduleRegexLinkage() {
    if (stopped) return;
    regexLinkageRevision += 1;
    clearTimeout(regexLinkageTimer);
    regexLinkageTimer = setTimeout(() => {
      regexLinkageTimer = null;
      if (regexLinkageGenerating || regexLinkagePending || !isCurrentIzumiInstance()) return;
      regexLinkagePending = true;
      const revision = regexLinkageRevision;
      enqueueWrite(async () => {
        const owner = normalizeName(presetName());
        const valid = () => isCurrentIzumiInstance() && owner && owner === normalizeName(presetName())
          && (!adviceOwnerPreset || owner === adviceOwnerPreset) && !regexLinkageGenerating;
        if (!valid()) return;
        const preset = apiPreset();
        if (!preset) return;
        const state = regexLinkageState(preset.prompts, nightMode);
        const signature = JSON.stringify([owner, state]);
        if (signature === regexLinkageSignature) return;
        const get = hostFunction('getTavernRegexes');
        const replace = hostFunction('replaceTavernRegexes');
        if (!get || !replace) throw new Error('当前酒馆助手缺少预设正则 API，请升级酒馆助手');
        let changes = 0;
        const missing = new Set();
        // Persist named preset first; then update live regexes. Never touch global/character scopes.
        for (const name of [owner, 'in_use']) {
          if (!valid()) return;
          const rows = get({ type: 'preset', name });
          if (!Array.isArray(rows) || !rows.length) throw new Error('当前预设没有可管理的正则');
          const result = planRegexLinkage(rows, state);
          result.missing.forEach(n => missing.add(n));
          if (result.changed) {
            await replace(result.next, { type: 'preset', name });
            changes += result.changed;
          }
        }
        if (!valid()) return;
        regexLinkageSignature = signature;
        const warning = state.summary === 'conflict' ? '两个摘要条目同时开启，请只保留一种；摘要正则暂不自动切换'
          : missing.size ? `部分正则未切换：缺少对应美化版本（${Array.from(missing).join('、')}）` : '';
        if (warning && warning !== regexLinkageWarning) toast(warning, 'error');
        regexLinkageWarning = warning;
        if (changes) invalidatePromptDataCache();
      }).catch(error => {
        console.warn('[Izumi floating window] regex linkage failed', error);
        const message = `正则联动未完成：${error.message || error}`;
        if (message !== regexLinkageWarning) toast(message, 'error');
        regexLinkageWarning = message;
      }).finally(() => {
        regexLinkagePending = false;
        if (revision !== regexLinkageRevision && !stopped) scheduleRegexLinkage();
      });
    }, 180);
  }
  // END REGEX LINKAGE

