    const context = hostContext();
    if (context) {
      try {
        const manager = typeof context.getPresetManager === 'function'
          ? context.getPresetManager(context.mainApi === 'openai' ? 'openai' : '')
          : null;
        const value = normalizeName(manager && typeof manager.getSelectedPresetName === 'function'
          ? manager.getSelectedPresetName()
          : '');
        if (value && value !== 'in_use') return value;
      } catch (_) {}
      const settings = context.chatCompletionSettings;
      const value = normalizeName(settings && (settings.preset_settings_openai || settings.preset));
      if (value && value !== 'in_use') return value;
    }
    const selectors = ['#settings_preset_openai', '#settings_preset', '#completion_preset', '#preset', 'select[name="preset"]', 'select[id*="preset"]'];
    for (const selector of selectors) {
      try {
        const element = pdoc.querySelector(selector);
        if (!element) continue;
        const value = normalizeName(element.value || (element.selectedOptions && element.selectedOptions[0] && element.selectedOptions[0].textContent));
        if (value) return value;
      } catch (_) {}
