  function domPrompts() {
    const list = pdoc.querySelector('#completion_prompt_manager_list');
    if (!list) return [];
    let nodes = Array.from(list.querySelectorAll('li[data-pm-identifier]'));
    if (!nodes.length) nodes = Array.from(list.querySelectorAll('li'));
    const items = nodes.map((node, index) => {
      const nameNode = node.querySelector('[data-pm-name]');
      const name = normalizeName(nameNode ? nameNode.getAttribute('data-pm-name') : (node.getAttribute('data-pm-name') || node.textContent));
      const disabled = node.classList.contains('completion_prompt_manager_prompt_disabled') || node.classList.contains('prompt-disabled') || node.getAttribute('data-enabled') === 'false';
      const contentNode = node.querySelector('[data-pm-content], .prompt-manager-prompt-content, textarea, [contenteditable="true"]');
      const content = contentNode ? (contentNode.value || contentNode.textContent || contentNode.getAttribute('data-pm-content') || '') : '';
      return { index, id: String(node.getAttribute('data-pm-identifier') || ''), name: name || `条目 ${index + 1}`, content, enabled: !disabled, node };
    }).filter((item) => item.name || item.id);
    return classifyItems(items);
  }

  let promptDataCache = null;

  function rawPresetSignature(preset) {
    const prompts = Array.isArray(preset && preset.prompts) ? preset.prompts : [];
    return prompts.map((prompt, index) => `${promptIdentifier(prompt) || index}|${normalizeName(prompt && prompt.name)}|${prompt && prompt.enabled !== false ? 1 : 0}`).join('\n');
  }

  function invalidatePromptDataCache() {
    promptDataCache = null;
  }

  function promptData(options = {}) {
    const preset = apiPreset();
    if (preset) {
      const signature = rawPresetSignature(preset);
      if (!options.fresh && promptDataCache && promptDataCache.mode === 'api'
        && promptDataCache.signature === signature) {
        // getPreset 可能每次返回新对象；分类结果可以复用，但 preset 要换成最新对象。
        const data = { mode: 'api', preset, items: promptDataCache.data.items };
        promptDataCache = { mode: 'api', preset, signature, data };
        return data;
      }
      const data = { mode: 'api', preset, items: presetPromptItems(preset) };
      promptDataCache = { mode: 'api', preset, signature, data };
      return data;
    }
    const items = domPrompts();
    const signature = items.map((item) => `${item.id}|${item.name}|${item.enabled !== false ? 1 : 0}`).join('\n');
    if (!options.fresh && promptDataCache && promptDataCache.mode === 'dom' && promptDataCache.signature === signature) {
      return promptDataCache.data;
    }
    const data = { mode: items.length ? 'dom' : 'none', preset: null, items };
    promptDataCache = { mode: 'dom', preset: null, signature, data };
    return data;
  }

  // The prompt_order view can reorder prompts without changing the prompts array.
  // Resolve by the rendered row name as a fallback so actions never silently no-op.
  function resolvePromptItem(data, index, button, nameOverride = '') {
    if (!data || !Array.isArray(data.items)) return null;
    const numeric = Number(index);
    const row = button && button.closest && button.closest('.item-row[data-item-index]');
    const label = row && row.querySelector('.toggle-name');
    const rawName = nameOverride || (label ? label.textContent : button && button.getAttribute('aria-label')) || '';
    const name = normalizeName(rawName).replace(/^(?:启用|停用)\s+/, '');
    const item = data.items.find((candidate) => candidate.index === numeric);
    if (item && (!name || item.name === name)) return item;
    return name ? data.items.find((candidate) => candidate.name === name) || null : item || null;
  }

  // 开关监听只需要 id/name/enabled，绝不能为了它跑正文分类器。
  function promptToggleShape() {
    const preset = apiPreset();
    if (preset && Array.isArray(preset.prompts)) {
      return preset.prompts
        .filter((prompt) => prompt && typeof prompt === 'object')
        .map((prompt) => `${promptIdentifier(prompt)}|${normalizeName(prompt.name)}|${prompt.enabled !== false ? 1 : 0}`)
        .join('\n');
    }
    const list = pdoc.querySelector('#completion_prompt_manager_list');
    if (!list) return '';
    let nodes = Array.from(list.querySelectorAll('li[data-pm-identifier]'));
    if (!nodes.length) nodes = Array.from(list.querySelectorAll('li'));
    return nodes.map((node, index) => {
      const id = String(node.getAttribute('data-pm-identifier') || '');
      const nameNode = node.querySelector('[data-pm-name]');
      const name = normalizeName(nameNode ? nameNode.getAttribute('data-pm-name') : (node.getAttribute('data-pm-name') || node.textContent));
      const toggle = node.querySelector('.prompt-manager-toggle-action,[data-action*="toggle"],button');
      const pressed = toggle && toggle.getAttribute('aria-pressed');
      const enabled = pressed == null ? !node.classList.contains('disabled') : pressed === 'true';
      return `${id || index}|${name}|${enabled ? 1 : 0}`;
    }).join('\n');
  }

  function promptShape() {
    const preset = apiPreset();
    if (preset && Array.isArray(preset.prompts)) {
      return preset.prompts.map((prompt, index) => `${promptIdentifier(prompt)}|${normalizeName(prompt && prompt.name)}|${index}`).join('\n');
    }
    const list = pdoc.querySelector('#completion_prompt_manager_list');
    if (!list) return '';
    let nodes = Array.from(list.querySelectorAll('li[data-pm-identifier]'));
    if (!nodes.length) nodes = Array.from(list.querySelectorAll('li'));
    const rows = nodes.map((node, index) => {
      const nameNode = node.querySelector('[data-pm-name]');
      const name = normalizeName(nameNode ? nameNode.getAttribute('data-pm-name') : (node.getAttribute('data-pm-name') || node.textContent));
      return { id: String(node.getAttribute('data-pm-identifier') || ''), name, index };
    }).filter((row) => row.id || row.name);
    return rows.map((row) => `${row.id}|${row.name}|${row.index}`).join('\n');
  }

  function findDomPrompt(state) {
    const items = domPrompts();
    const id = normalizeName(state && state.id);
    const name = normalizeName(state && state.name);
    return (id ? items.find((item) => item.id === id) : null)
      || items.find((item) => item.name === name)
      || items[Number(state && state.index)]
      || null;
  }

  function clickDomPrompt(item, enabled) {
    if (!item || !item.node || item.enabled === enabled) return false;
    const button = item.node.querySelector('.prompt-manager-toggle-action') || item.node.querySelector('[data-action*="toggle"]') || item.node.querySelector('button');
    if (!button) return false;
    try { button.click(); return true; } catch (_) { return false; }
  }

  function normalizeSafePresetFields(value) {
    const fields = {};
    if (!value || typeof value !== 'object' || Array.isArray(value)) return fields;
    Object.entries(value).forEach(([key, raw]) => {
      if (key === 'settings') {
        if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return;
        fields.settings = Object.fromEntries(Object.entries(raw)
          .filter(([setting]) => SAFE_PRESET_SETTINGS.has(setting))
          .filter(([, settingValue]) => settingValue === null || ['string', 'number', 'boolean'].includes(typeof settingValue))
          .map(([setting, settingValue]) => [setting, clone(settingValue)]));
        return;
      }
      if (!SAFE_PRESET_FIELDS.has(key)) return;
      if (raw === null || ['string', 'number', 'boolean'].includes(typeof raw)) fields[key] = raw;
    });
    return fields;
  }

  function normalizePlan(plan) {
    if (!plan || typeof plan !== 'object') return null;
    const name = normalizeName(plan.name).slice(0, 80);
    if (!name) return null;
    const states = Array.isArray(plan.promptStates) ? plan.promptStates : [];
    return {
      name,
      savedAt: plan.savedAt || new Date().toISOString(),
      presetName: normalizeName(plan.presetName),
      promptStates: states.slice(0, 2000).map((state, index) => ({
        id: normalizeName(state && state.id),
        name: normalizeName(state && state.name),
        index: Number.isInteger(Number(state && state.index)) ? Number(state.index) : index,
        enabled: state && state.enabled !== false,
        layer: normalizeLayer(state && (state.layer || state.izumi_layer)),
      })).filter((state) => state.name || state.id),
      promptEdits: normalizePromptEdits(plan.promptEdits, states),
      promptOrder: Array.isArray(plan.promptOrder) ? clone(plan.promptOrder) : null,
      presetFields: normalizeSafePresetFields(plan.presetFields),
      layerPlans: Array.isArray(plan.layerPlans)
        ? plan.layerPlans.map(normalizeLayerPlan).filter(Boolean)
        : [],
      activeLayerPlans: plan.activeLayerPlans && typeof plan.activeLayerPlans === 'object' && !Array.isArray(plan.activeLayerPlans)
        ? Object.assign({}, plan.activeLayerPlans)
        : null,
      quickSlots: Array.isArray(plan.quickSlots) ? Array.from(new Set(plan.quickSlots.map(normalizeName).filter(Boolean))) : [],
      nativePreset: sanitizeNativePreset(plan.nativePreset),
      helperPreset: plan.helperPreset && typeof plan.helperPreset === 'object'
        ? sanitizePresetForWrite(plan.helperPreset)
        : null,
      apiConfig: plan.apiConfig && typeof plan.apiConfig === 'object'
        ? normalizeApiConfig(plan.apiConfig)
        : (plan.api && typeof plan.api === 'object' ? normalizeApiConfig(plan.api) : null),
    };
  }

  let planCache = null;

  function plans() {
    if (planCache) return planCache;
    const store = storage();
    if (!store) return [];
    try {
      const value = JSON.parse(store.getItem(STORAGE_KEY) || 'null');
      planCache = value && Array.isArray(value.plans) ? value.plans.map(normalizePlan).filter(Boolean) : [];
      return planCache;
    } catch (_) {
      planCache = [];
      return planCache;
    }
  }

  function savePlans(value) {
    const normalized = value.map(normalizePlan).filter(Boolean);
    const ok = writeStorageKey(STORAGE_KEY, JSON.stringify({
      schema: PLAN_SCHEMA,
      version: PLAN_VERSION,
      updatedAt: new Date().toISOString(),
      plans: normalized,
    }));
    if (ok) planCache = normalized;
    return ok;
  }

  // 大方案里 nativePreset 和 helperPreset 是同一份预设的两份拷贝。
  // 512KB 的预设 → 单个大方案能吃掉 1.5MB，两三个就把 5MB 的 localStorage 撑爆。
  // 精简时丢掉冗余的 nativePreset：载入优先走 helperPreset，丢了不影响恢复。
  function compactPlanStorage() {
    const list = plans();
    let touched = 0;
    let freed = 0;
    const compacted = list.map((plan) => {
      if (!plan.helperPreset || !plan.nativePreset) return plan;
      try { freed += JSON.stringify(plan.nativePreset).length; } catch (_) {}
      touched += 1;
      return Object.assign({}, plan, { nativePreset: null });
    });
    if (!touched) return { touched: 0, freed: 0, ok: true };
    const ok = savePlans(compacted);
    return { touched, freed, ok };
  }

  // ===========================================================================
  // 小方案（层方案）子系统
  // 大方案 = 整份预设快照；小方案 = 只记「某层/某子区里哪些条目开着」的按层微调。
  // 两套数据完全独立存储，互不污染；小方案可跨大方案自由拼装。
  // ===========================================================================
  const LAYER_PLAN_KEY = 'izumi_floating_window_layer_plans_v1';
  const LAYER_PLAN_SCHEMA = 'izumi-layer-plan-pack';
  const LAYER_PLAN_VERSION = 2;
  let layerPlanCache = null;

  function createLayerPlanId() {
    try {
      const cryptoRef = pwin.crypto || (typeof crypto !== 'undefined' ? crypto : null);
      if (cryptoRef && typeof cryptoRef.randomUUID === 'function') return cryptoRef.randomUUID();
    } catch (_) {}
    return `lp-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  }

  // 这里只列「不用解释也能确定互相矛盾」的条目。
  // 不做模糊关键词推断，避免脚本替用户决定复杂搭配。

  // 老的小方案里可能已经同时存了矛盾项。应用前整理一下：同组里后出现的那项胜出。


  // 同名条目的序号：让「——破甲加强区——」这种成对出现的名字也能被精确定位。

  function normalizeLayerPlan(plan) {
    if (!plan || typeof plan !== 'object') return null;
    const name = normalizeName(plan.name).slice(0, 60);
    const { layer, section } = normalizePlanScope(plan.layer, plan.section);
    if (!name || !layer) return null;
    const entries = (Array.isArray(plan.entries) ? plan.entries : [])
      .map(normalizeLayerPlanEntry).filter(Boolean).slice(0, 2000);
    if (!entries.length) return null;
    return {
      id: normalizeName(plan.id) || createLayerPlanId(),
      name,
      layer,
      section,
      strict: plan.strict !== false,
      savedAt: plan.savedAt || new Date().toISOString(),
      entries,
    };
  }

  function layerPlanStore() {
    if (layerPlanCache) return clone(layerPlanCache);
    const store = storage();
    let parsed = null;
    if (store) {
      try { parsed = JSON.parse(store.getItem(LAYER_PLAN_KEY) || 'null'); } catch (_) { parsed = null; }
    }
    const plans = parsed && Array.isArray(parsed.plans)
      ? parsed.plans.map(normalizeLayerPlan).filter(Boolean)
      : [];
    const active = {};
    LAYERS.forEach((layer) => {
      const value = parsed && parsed.active ? normalizeName(parsed.active[layer.id]) : '';
      active[layer.id] = plans.some((plan) => plan.id === value) ? value : '';
    });
    layerPlanCache = { plans, active };
    // Callers edit drafts. Never expose the committed cache to mutation before storage succeeds.
    return clone(layerPlanCache);
  }

  function layerPlans(layerId) {
    const list = layerPlanStore().plans;
    return layerId ? list.filter((plan) => plan.layer === layerId) : list;
  }

  function saveLayerPlanStore(next) {
    const plans = (next && Array.isArray(next.plans) ? next.plans : [])
      .map(normalizeLayerPlan).filter(Boolean);
    const active = {};
    LAYERS.forEach((layer) => {
      const value = next && next.active ? normalizeName(next.active[layer.id]) : '';
      active[layer.id] = plans.some((plan) => plan.id === value) ? value : '';
    });
    const saved = writeStorageKey(LAYER_PLAN_KEY, JSON.stringify({
      schema: LAYER_PLAN_SCHEMA,
      version: LAYER_PLAN_VERSION,
      updatedAt: new Date().toISOString(),
      plans,
      active,
    }));
    if (saved) layerPlanCache = clone({ plans, active });
    return saved;
  }

  // 小方案本身只有几 KB，写不进去基本都是被大方案挤的：先自动精简再重试一次。
  function saveLayerPlanStoreWithRetry(store) {
    if (saveLayerPlanStore(store)) return { ok: true, compacted: null };
    if (!isQuotaError(storageService.lastError)) return { ok: false, compacted: null };
    const result = compactPlanStorage();
    if (!result.touched) return { ok: false, compacted: null };
    if (!saveLayerPlanStore(store)) return { ok: false, compacted: result };
    return { ok: true, compacted: result };
  }

  // 重名小方案直接加（1）（2），不打扰用户。
  function uniqueLayerPlanName(name, layerId, excludeId, candidates = layerPlans(layerId)) {
    const base = normalizeName(name).replace(/（\d+）$/, '') || '未命名';
    const taken = new Set(candidates
      .filter((plan) => plan.layer === layerId && plan.id !== excludeId)
      .map((plan) => plan.name));
    if (!taken.has(base)) return base;
    for (let i = 1; i < 999; i += 1) {
      const candidate = `${base}（${i}）`;
      if (!taken.has(candidate)) return candidate;
    }
    return `${base}（${Date.now().toString(36)}）`;
  }

  // 小方案被改脏后另存：源名 + 递增序号，比光秃秃的 1234567 好认。
  function derivedLayerPlanName(baseName, layerId) {
    const base = normalizeName(baseName).replace(/\s+\d+$/, '').replace(/（\d+）$/, '') || '未命名';
    const taken = new Set(layerPlans(layerId).map((plan) => plan.name));
    if (!taken.has(base)) return base;
    for (let i = 2; i < 999; i += 1) {
      const candidate = `${base} ${i}`;
      if (!taken.has(candidate)) return candidate;
    }
    return uniqueLayerPlanName(base, layerId, '');
  }

  function captureLayerPlan(name, layerId, section, data) {
    const source = data || promptData();
    return normalizeLayerPlan({
      id: createLayerPlanId(),
      name,
      layer: layerId,
      section,
      strict: true,
      entries: layerPlanEntriesFrom(source.items, layerId, section),
    });
  }

  // 匹配链：id → 名称+同名序号 → 名称。刻意不做 index 兜底——跨预设复用时它会张冠李戴。

  // 载入大方案后自动反查：某层的开关状态正好等于某个小方案，就把它点亮。
  function detectActiveLayerPlans(data) {
    const source = data || promptData();
    const store = layerPlanStore();
    const signatureCache = new Map();
    let changed = false;
    LAYERS.forEach((layer) => {
      const currentId = store.active[layer.id];
      const currentPlan = store.plans.find((plan) => plan.id === currentId) || null;
      if (currentPlan && !isLayerPlanDirty(currentPlan, source, signatureCache)) return;
      const hit = store.plans.find((plan) => plan.layer === layer.id && !isLayerPlanDirty(plan, source, signatureCache));
      const next = hit ? hit.id : currentId;
      if (next !== currentId) {
        store.active[layer.id] = next;
        changed = true;
      }
    });
    if (changed) saveLayerPlanStore(store);
    return layerPlanStore().active;
  }

  function activeLayerPlan(layerId) {
    const store = layerPlanStore();
    return store.plans.find((plan) => plan.id === store.active[layerId]) || null;
  }

  // 应用小方案：所有条目在一次 updatePresetCompat 回调里改完，只写回一次。
  // 逐条走 togglePrompt 的话，一次切换会连写十几次预设，手机端必卡。
  async function applyLayerPlan(planId, options = {}) {
    const store = layerPlanStore();
    const value = store.plans.find((plan) => plan.id === planId) || null;
    if (!value) return toast('这个小方案找不到了，可能已经被删掉～', 'error');
    const data = promptData();
    if (data.mode !== 'api' || !(hostFunction('updatePresetWith') || hostFunction('replacePreset'))) {
      return toast('小方案切不了：读不到酒馆的预设接口，看看「酒馆助手」开着没～', 'error');
    }
    const resolvedPlan = resolveDirectConflictEntries(value.entries);

    // 吐槽区有「必须保留一项开启」的硬约束，严格模式可能把它清空，先拦下来。
    const tucaoScope = data.items.filter((item) => itemInScope(item, value.layer, value.section) && item.functionSection === 'tucao');
    if (tucaoScope.length) {
      const willEnable = value.entries.filter((entry) => entry.enabled)
        .some((entry) => tucaoScope.some((item) => normalizeName(item.id) === entry.id || normalizeName(item.name) === entry.name));
      if (!willEnable) return toast(`小方案「${value.name}」会清空吐槽区，已阻止`, 'error');
    }

    let missing = 0;
    let mutated = 0;
    let applied = false;
    let applyError = null;
    try {
      await enqueueWrite(() => updatePresetCompat((preset) => {
        const result = applyLayerPlanToPreset(preset, value, data.items);
        missing = result.missing;
        mutated = result.mutated;
        return preset;
      }, { render: 'immediate' }));
      applied = true;
    } catch (error) {
      applyError = error;
      console.warn('[Izumi floating window] layer plan apply failed', error);
    }
    if (!applied) return toast(applyError && applyError.partialCommit
      ? '当前开关可能已改变，但小方案未能完整保存；请刷新核对后重试'
      : '小方案没应用上，点↻刷新再试一次看看；还是不行的话按 F12 看看控制台报了什么', 'error');
    const nextStore = layerPlanStore();
    nextStore.active[value.layer] = value.id;
    const activeSaved = saveLayerPlanStore(nextStore);
    if (options.refresh !== false) refreshPanel();
    else {
      invalidatePromptDataCache();
      try { syncSessionSnapshot(promptData()); } catch (_) {}
    }
    const suffix = missing ? `，有 ${missing} 条没对上（可能不在当前预设里）` : '';
    const conflictSuffix = resolvedPlan.closed.length
      ? `；里面原本有直接矛盾的条目，已经帮你关掉了「${Array.from(new Set(resolvedPlan.closed)).join('、')}」`
      : '';
    if (!options.silentToast) {
      toast(`已应用小方案「${value.name}」：改动 ${mutated} 条${suffix}${conflictSuffix}${activeSaved ? '' : '；但当前小方案标记未保存'}`, missing || !activeSaved ? 'error' : 'success');
    }
    return { plan: value, mutated, missing, closed: resolvedPlan.closed };
  }

  function saveLayerPlanFromCurrent(layerId, section) {
    const data = promptData();
    const store = layerPlanStore();
    const activePlan = store.plans.find((plan) => plan.id === store.active[layerId]) || null;
    const dirty = activePlan ? isLayerPlanDirty(activePlan, data) : false;
    const fallback = section
      ? `${layerLabel(layerId)}·${sectionLabel(layerId, section)}`
      : layerLabel(layerId);
    const base = (activePlan && dirty && activePlan.section === section)
      ? activePlan.name
      : fallback;
    const plan = captureLayerPlan(derivedLayerPlanName(base, layerId), layerId, section, data);
    if (!plan) return toast('这一层现在是空的，没东西可以存～', 'error');
    plan.name = uniqueLayerPlanName(plan.name, layerId, plan.id);
    store.plans.unshift(plan);
    store.active[layerId] = plan.id;
    const saved = saveLayerPlanStoreWithRetry(store);
    if (!saved.ok) return toast(storageFailureMessage('小方案未保存'), 'error');
    renderItems(data);
    renderPlanList();
    if (saved.compacted && saved.compacted.touched) {
      return toast(`已保存小方案「${plan.name}」（存储将满，顺手精简了 ${saved.compacted.touched} 个大方案备份，省出约 ${formatBytes(saved.compacted.freed)}）`, 'success');
    }
    toast(`已保存小方案「${plan.name}」`, 'success');
  }

  function renameLayerPlan(planId) {
    const store = layerPlanStore();
    const plan = store.plans.find((candidate) => candidate.id === planId);
    if (!plan) return;
    const ask = pwin.prompt || (typeof prompt === 'function' ? prompt : null);
    if (!ask) return toast('这个浏览器不让弹输入框，改名用不了～', 'error');
    const next = normalizeName(ask.call(pwin, `小方案改名（${plan.name}）`, plan.name));
    if (!next || next === plan.name) return;
    plan.name = uniqueLayerPlanName(next, plan.layer, plan.id);
    if (!saveLayerPlanStoreWithRetry(store).ok) return toast(storageFailureMessage('改名未保存'), 'error');
    renderItems();
    toast(`已改名为「${plan.name}」`, 'success');
  }

  function deleteLayerPlan(planId) {
    const store = layerPlanStore();
    const index = store.plans.findIndex((plan) => plan.id === planId);
    if (index < 0) return;
    const plan = store.plans[index];
    const ask = pwin.confirm || (typeof confirm === 'function' ? confirm : null);
    if (ask && !ask.call(pwin, `删除小方案「${plan.name}」？`)) return;
    store.plans.splice(index, 1);
    LAYERS.forEach((layer) => { if (store.active[layer.id] === planId) store.active[layer.id] = ''; });
    if (!saveLayerPlanStoreWithRetry(store).ok) return toast(storageFailureMessage('小方案未删除'), 'error');
    const quickSaved = !quickSlots().includes(planId) || saveQuickSlots(quickSlots().filter((id) => id !== planId));
    renderItems();
    toast(quickSaved ? `已删除小方案「${plan.name}」` : `已删除小方案「${plan.name}」，但快捷入口未能保存`, quickSaved ? 'success' : 'error');
  }

  function toggleLayerPlanStrict(planId) {
    const store = layerPlanStore();
    const plan = store.plans.find((candidate) => candidate.id === planId);
    if (!plan) return;
    plan.strict = !plan.strict;
    if (!saveLayerPlanStoreWithRetry(store).ok) return toast(storageFailureMessage('模式未保存'), 'error');
    renderItems();
    toast(`「${plan.name}」已切换为${plan.strict ? '严格' : '宽松'}模式`, 'success');
  }

  // 大方案包里捎带的小方案：同 id 覆盖，同名不同 id 自动加（1）（2）。
  function mergeLayerPlans(incoming, active, incomingQuickSlots) {
    if (!Array.isArray(incoming) || !incoming.length) return 0;
    const store = layerPlanStore();
    let added = 0;
    incoming.map(normalizeLayerPlan).filter(Boolean).forEach((plan) => {
      const index = store.plans.findIndex((candidate) => candidate.id === plan.id);
      if (index >= 0) {
        store.plans[index] = plan;
        return;
      }
      plan.name = uniqueLayerPlanName(plan.name, plan.layer, plan.id, store.plans);
      store.plans.push(plan);
      added += 1;
    });
    if (active && typeof active === 'object') {
      LAYERS.forEach((layer) => {
        const id = normalizeName(active[layer.id]);
        if (id && store.plans.some((plan) => plan.id === id)) store.active[layer.id] = id;
      });
    }
    if (!saveLayerPlanStoreWithRetry(store).ok) throw new Error(storageFailureMessage('随包小方案未保存'));
    if (Array.isArray(incomingQuickSlots) && incomingQuickSlots.length
      && !saveQuickSlots(quickSlots().concat(incomingQuickSlots))) {
      throw new Error(storageFailureMessage('小方案已导入，但快捷入口未保存'));
    }
    return added;
  }

  // 独立导出全部小方案：不含任何预设正文，纯粹是各层的开关组合，体积很小、方便单独分享。
  function exportLayerPlans() {
    const store = layerPlanStore();
    if (!store.plans.length) return toast('还没有任何小方案可以导出', 'error');
    const payload = {
      schema: LAYER_PLAN_SCHEMA,
      version: LAYER_PLAN_VERSION,
      exportedAt: new Date().toISOString(),
      plans: store.plans.map((plan) => clone(plan)),
      active: Object.assign({}, store.active),
      quickSlots: quickSlots().slice(),
    };
    const byLayer = LAYERS.map((layer) => {
      const count = store.plans.filter((plan) => plan.layer === layer.id).length;
      return count ? `${layer.label} ${count}` : '';
    }).filter(Boolean).join('、');
    const stamp = new Date().toISOString().slice(0, 10);
    const done = download(payload, `泉此方小方案包 ${stamp}.json`);
    if (done) return toast(`已导出 ${store.plans.length} 个小方案（${byLayer}）`, 'success');
    // 手机端下载可能不可用，退回到可复制的文本弹窗。
    try {
      openTransferDialog('export', JSON.stringify(payload, null, 2), `泉此方小方案包 ${stamp}.json`);
      toast('这里下载不了文件，已经换成文本了，复制走就行～', 'success');
    } catch (_) {
      toast('导出没成功～', 'error');
    }
  }

  function exportQuickPlans() {
    const selected = quickSlotPlans();
    if (!selected.length) return toast('快捷方案还是空的，先从小方案的「⋯」里加几个吧～', 'error');
    const ids = selected.map((plan) => plan.id);
    const selectedSet = new Set(ids);
    const active = {};
    LAYERS.forEach((layer) => {
      const id = layerPlanStore().active[layer.id];
      active[layer.id] = selectedSet.has(id) ? id : '';
    });
    const payload = {
      schema: LAYER_PLAN_SCHEMA,
      version: LAYER_PLAN_VERSION,
      exportedAt: new Date().toISOString(),
      subset: 'quick-slots',
      plans: selected.map((plan) => clone(plan)),
      active,
      quickSlots: ids,
    };
    const stamp = new Date().toISOString().slice(0, 10);
    const filename = `泉此方快捷方案包 ${stamp}.json`;
    const done = download(payload, filename);
    if (done) return toast(`已导出 ${selected.length} 个快捷方案～`, 'success');
    try {
      openTransferDialog('export', JSON.stringify(payload, null, 2), filename);
      toast('这里下载不了文件，已经换成文本了，复制走就行～', 'success');
    } catch (_) { toast('导出没成功～', 'error'); }
  }

  // 使用教程正文。写得啰嗦一点，省得以后忘了某个按钮是干嘛的。
  function helpMarkup() {
    const build = getBuildInfo();
    return `
      <h4>版本与诊断</h4>
      <p class="help-note">运行版本 <span id="${ID}-build-version">${esc(build.version)}</span> · 短构建号 <code id="${ID}-build-id">${esc(build.buildId)}</code>（输入指纹，非产物哈希）。</p>
      <p class="help-note">点击后才生成脱敏诊断：仅含版本、接口能力布尔值与最近一次预设保存结果，不是完整操作日志，也不覆盖批量文件导入全链路。不读取预设正文、聊天或连接配置；不上传，不写入本地存储。</p>
      <button class="command" data-action="diagnostics">生成脱敏诊断</button>

      <p class="help-lead">这个悬浮窗做的事很简单：把酒馆预设里几百条提示词，按<b>层</b>和<b>子区</b>分好类，
      再让你用<b>方案</b>把「开哪些条目」的组合存下来、一键切换。</p>

      <h4>① 三个层是什么</h4>
      <ul>
        <li><b>结构层</b>　系统提示、角色定义、上下文骨架。下面分「常规结构」和「尾部」两个子区，
        尾部放的是思维链、总结、拷打、摘要、输出格式这类跑在正文后面的东西。</li>
        <li><b>功能层</b>　各种开关、模型适配、防护规则。下面分「常规功能 / 吐槽区 / 思维链 / 破甲区」四个子区。</li>
        <li><b>文风层</b>　文风、叙事、语言、描写规则。没有子区。</li>
      </ul>
      <p class="help-note">层和子区是<b>自动识别</b>的，靠条目名、正文特征和预设里的区间标记
      （<code>↓四选一开↓</code>、<code>思维链开始/结束</code>、<code>破甲加强区</code> 等）综合判断。
      识别错了不要紧：<b>点条目进编辑器，改「所属目录」和「目标子区」</b>，
      改完会写进预设，以后一直认这个，自动识别不会再覆盖它。</p>

      <h4>② 大方案 vs 小方案</h4>
      <ul>
        <li><b>大方案</b>＝整份预设的完整快照。条目开关、顺序、条目正文、连接参数全都存。
        对应面板下方的「保存方案缓存」和方案列表。</li>
        <li><b>小方案</b>＝只记「某一层里哪些条目开着」。不存顺序、不存正文，所以<b>可以跨大方案复用</b>。
        对应每个层导航下面那一排彩色小标签。</li>
      </ul>
      <p class="help-note">典型用法：结构层点一个「3.7适配」，功能层点一个「不抢话」，
      两个小方案叠加出你要的组合——不用再一个个抠开关。</p>

      <h4>③ 小方案怎么用</h4>
      <ol>
        <li>切到目标层（想只管某个子区，就再点一下那个子区）。</li>
        <li>把条目开关调成你要的样子。</li>
        <li>点小方案栏右边的「＋ 存小方案」。作用域会显示在栏子左边，存之前确认一眼。</li>
        <li>以后轻点那个小标签就能切回来。当前生效的标签会有<b>✓、粗边框和高亮</b>，不只靠颜色区分。</li>
        <li><b>长按小方案</b>可以先看预览：它会开启哪些、停用哪些，严格/宽松模式也会写清楚。</li>
        <li><b>「↶ 还原」</b>会回到这次打开酒馆时的条目开关状态，和有没有选小方案无关。</li>
        <li>点完还原后想反悔，旁边的<b>「↷ 回退」</b>会把刚才还原前的状态找回来。</li>
        <li>同一层有两个以上小方案时，可以点<b>「⇄ 对比」</b>，在两个下拉框里选好方案，看看它们开启的条目差在哪里。</li>
      </ol>
      <p class="help-note">第一次看到小方案栏时，会有一条「长按可预览」的小提示；点「知道啦」后就不再打扰。
      常用的小方案可以在右侧「⋯」里加入<b>快捷方案</b>；数量不设上限，加入顺序就是菜单顺序。之后长按悬浮的小此头像就能直接切换，不用打开大面板。快捷方案会随小方案包一起导入导出。
      脚本会在使用过程中持续记住当前开关，离开页面前也会再补记一次；下次打开酒馆时，
      这份记录就会成为「还原」的基准。快照只保存条目身份和开关，不存正文、密钥或连接参数。
      标签上的数字＝这个小方案会开启几条。点标签右边的「⋯」可以
      <b>改名 / 切换严格模式 / 删除</b>。</p>

      <h4>④ 严格模式（重要）</h4>
      <ul>
        <li><b>严格</b>（默认）：这一层<b>完全听小方案的</b>，小方案里没说要开的条目，一律关掉。
        想在「抢话」和「不抢话」之间干净地切换，就得用严格。</li>
        <li><b>宽松</b>：只改小方案记录过的条目，其余的保持原样。</li>
      </ul>
      <p class="help-warn">严格模式的副作用：小方案存好之后你<b>新加</b>的条目，
      下次应用会被一起关掉。介意的话就把那个小方案切成宽松。</p>
      <p class="help-note">脚本只会自动处理<b>明确的直接矛盾</b>：抢话 / 防抢话、转述 / 防转述。
      开一边时另一边会自然关掉；复杂搭配不会替你做决定。</p>

      <h4>⑤ 那个 * 号是什么意思</h4>
      <p>应用了小方案之后，你又手动动了这层的开关 → 标签后面会出现 <b>*</b>，表示「已经不是原装的了」。
      这时候再点「＋ 存小方案」，<b>不会覆盖原方案</b>，而是另存成「原名 2」「原名 3」，
      老的那个还在。想改名就用「⋯」或者点顶部横幅。</p>

      <h4>⑥ 顶部那条横幅</h4>
      <p>显示<b>大方案名</b>和<b>三个层各自在用哪个小方案</b>，一眼看清当前这套配置是什么。
      点大方案那格可以改大方案的名字；点层那格可以改那个小方案的名字；
      没选小方案的层显示「—」，点一下会跳到那层去。变黄＝内容被改脏了。</p>
      <ul>
        <li><b>生效总览</b>　看看当前开启了多少条、提示词大约多少字符，以及系统/用户/助手、相对位置/聊天内的分布。字符数只是近似统计，不等于 token。</li>
        <li><b>复制配置</b>　生成一份 Discord 友好的 Markdown 清单，包含大方案、小方案和每层开启项的<b>名称</b>；不会复制提示词正文、密钥或连接参数。</li>
      </ul>

      <h4>⑦ 导入导出</h4>
      <ul>
        <li><b>导出全部小方案</b>　导出整个小方案库，同时带上快捷方案的选择和顺序。</li>
        <li><b>导出快捷方案</b>　只导快捷菜单里那部分小方案和排列顺序，适合分享自己的常用组合。</li>
        <li><b>导出当前酒馆预设 / 导出全部酒馆预设</b>　导的是完整预设。</li>
        <li><b>保存方案缓存</b>　存大方案时会<b>自动把整个小方案库一起打包进去</b>，
        所以给别人一个大方案包，对方拿到的是「完整配置＋全套小方案」。</li>
        <li><b>批量导入</b>　上面三种包都能认，直接丢进来就行。小方案按 id 合并：
        同 id 覆盖更新，同名不同 id 自动加（1）（2），不会互相顶掉。</li>
      </ul>
      <p class="help-note">手机上如果下载不了文件，会自动改成文本弹窗，复制粘贴一样能用。</p>

      <h4>⑧ 重名怎么处理</h4>
      <ul>
        <li><b>大方案</b>重名 → 弹窗要你改名，输入框里已经填好了一个不重名的建议；
        想覆盖原方案就直接确定。</li>
        <li><b>小方案</b>重名 → 自动加（1）（2），不打扰你。</li>
      </ul>

      <h4>⑨ 其它按钮</h4>
      <ul>
        <li>标题左边的<b>「ⓘ 使用教程」</b>就是这里；标题栏右边 <b>☾</b> 是夜间模式，<b>⏻</b> 是彻底关闭（重新运行脚本就回来）。</li>
        <li><b>↻</b> 刷新：在酒馆那边改了预设、这边没跟上时点它。</li>
        <li>搜索框默认只搜条目名；勾上<b>「搜正文」</b>后，也能用正文里的句子、变量名或标签来找条目。</li>
        <li>条目行左边可以<b>拖拽排序</b>，只能在同一个子区内部拖。</li>
        <li>面板右下角可以<b>拖拽缩放</b>，标题栏可以拖动整个面板。</li>
        <li>教程、预览、对比和编辑窗口打开时，面板会自动把窗口完整带到屏幕里；关闭后会回到刚才浏览的位置。</li>
      </ul>

      <h4>⑩ 几个要留意的地方</h4>
      <ul>
        <li>吐槽区<b>必须保留一项开启</b>。会导致清空的操作会被直接拦下来。</li>
        <li>思维链、吐槽区这类子区是<b>只开一个</b>的，开新的会自动关掉旧的。</li>
        <li>小方案靠「条目 id ＋ 名字」认人。跨预设复用时，如果对方预设里没有对应条目，
        会提示「有 N 条没对上」——不是坏了，是那几条确实不存在。</li>
        <li>搜正文会读取当前层的提示词正文，条目很多时比只搜名称稍慢一点；默认关闭就是为了让平时搜索更轻。</li>
        <li>所有改动都会自动写回<b>当前命名的酒馆预设</b>。如果顶部显示「未命名 / in_use」，
        请先在酒馆里把预设另存为一个有名字的预设，否则改动无处可存。</li>
      </ul>

      <h4>⑪ 存储不够 / 存不进去时</h4>
      <p>浏览器给每个站点的 localStorage 通常只有 <b>5 M 字符</b>。要命的是——<b>键名本身也算进配额</b>。
      有些扩展会给每条消息写一个键，攒到十几万个之后，哪怕每个值都是空的，光键名就能把 5 M 占满。</p>
      <p class="help-note">方案列表上方那行会显示当前占用和百分比，超 60% 变黄、超 85% 变红。</p>
      <b>四个按钮怎么用：</b>
      <ul>
        <li><b>存储详情</b>　弹出完整报告。<b>先看「按键名族群排」那一段</b>——
        如果某一族有成千上万个键，它就是元凶。单键排序看不出问题，因为病根是数量不是体积。</li>
        <li><b>清理垃圾键</b>　自动找出 50 个以上的键族群（<b>本脚本自己的键永远不参与</b>），
        列成菜单让你输序号选择，二次确认会告诉你删多少个、释放多少。<b>这是空间不足时的首选。</b></li>
        <li><b>精简</b>　只处理本脚本的大方案备份，丢掉里面冗余的预设副本，不影响载入。</li>
        <li><b>清空备份</b>　删掉本脚本<b>全部</b>本地大方案备份。酒馆里的预设和小方案都不受影响，
        但建议先「导出」存成文件。</li>
      </ul>
      <p class="help-warn">被清理的垃圾键属于酒馆或其它扩展，删掉后它们的历史缓存会丢失（通常会自动重建）。
      如果不确定，先用「存储详情」看清楚是什么再动手。</p>
      <p class="help-note">垃圾键清完还会慢慢再攒。要根治得找到那个乱写 localStorage 的扩展，
      在它的设置里关掉相关功能，或者干脆停用。</p>
      <p>存小方案时如果空间不够，脚本会<b>自动精简一次再重试</b>，多数时候你不会察觉。
      真存不进去时，提示会直接告诉你<b>本脚本占了百分之几</b>——占比很低就说明该清的是别人的键。</p>

      <h4>⑫ Advice 破甲开关与设置</h4>
      <p>发送新的 user 消息时，脚本只处理两条消息：刚发出的最新 user，以及它之前最新的一条可见 AI 输出。
      酒馆会先保留真实 user 的原文和身份完成世界书扫描；绿灯结果确定后，user 正文才会移到 AI 的
      <code>&lt;advice&gt;…&lt;/advice&gt;</code> 中，原 user 楼改成可配置的替换句。默认是 <code>${esc(ADVICE_CONTINUE_TEXT)}</code></p>
      <p>主面板和长按头像菜单里都有<b>「Advice破甲开关」</b>，旁边齿轮可以设置：</p>
      <ul>
        <li><b>插入位置</b>　尾部＝放在最新 AI 末尾；头部＝有 <code>&lt;/konatan_planning…&gt;</code> 时放在它后面，否则放在 AI 最前。头部模式会强制删除模型自己生成的 Advice。</li>
        <li><b>删除模型生成的 Advice</b>　开启时先删掉最新 AI 中已有的 Advice，再按所选位置插入用户输入；关闭时保留模型 Advice，并在尾部另加用户 Advice。</li>
        <li><b>user 楼显示原 Advice 内容</b>　只把页面上的替换句显示成你原本写的 Advice，真实保存内容和发给模型的内容仍是该条记录的替换句。</li>
        <li><b>user 输入替换句</b>　可输入多行文字，留空时使用默认句。「恢复默认」只改设置表单，保存才生效，取消不保存。更改只影响后续新转移，不改正在进行的一轮或历史记录。</li>
      </ul>
      <p>Advice 转接后会把原输入和本次替换句冗余保存在 user 楼的扩展数据里。点 user 楼的原生编辑按钮时，编辑框会显示原输入；点保存后才同步更新前一条 AI 的用户 Advice，并把 user 真实正文恢复成该条记录的替换句。直接编辑 AI 楼中的用户 Advice 并保存，也会反向同步 user 冗余和可见内容。旧记录无需批量修改；关键词替换开启时，发给模型的替换句仍会经过现有净化规则。</p>
      <p class="help-note">取消编辑不会保存；输入过程中不会逐字改写 AI，也没有轮询。AI 编辑时完全删掉 Advice 标签会保留 user 冗余防误删，显式留下空的 <code>&lt;advice&gt;&lt;/advice&gt;</code> 才会把冗余同步为空。只审 user 输入的世界书仍按真实输入触发。</p>
      <p class="help-warn">从旧版 Advice 脚本升级到本版后，请完整刷新一次 SillyTavern 页面，清掉旧版可能遗留的父页面监听。刷新后，关闭开关会立即停止转接；切换到其它预设也不会继续运行。</p>

      <h4>⑬ 关于安全</h4>
      <p>这个悬浮窗<b>不会自己联网</b>。唯一一次网络请求是「拉取模型」，打到的是酒馆自己的后端
      （<code>/api/backends/…</code> 这种同源地址），拿完模型列表就结束，不会把东西发去别的地方。</p>
      <ul>
        <li><b>密钥</b>　只有你勾选了才会以明文存在这个浏览器本地。它不进日志、不进提示，
        <b>脚本的所有导出都不会带上它</b>。共用电脑的话就别勾～</li>
        <li><b>小方案包</b>　里面只有「哪些条目开着」的清单，没有正文、没有密钥，可以放心分享。</li>
        <li><b>导入别人的预设包要留个心眼</b>　酒馆预设本身允许夹带酒馆助手脚本，导入后是会运行的。
        碰到这种包脚本会先弹窗问你一句，来路不明的话就别导～</li>
        <li><b>外部网站读不到你这边的数据</b>　浏览器的同源策略挡着，别的网页碰不到酒馆页面的本地存储。</li>
      </ul>
    `;
  }

  // ===========================================================================
  // 会话快照：给「还原 / 回退」用
  // baseline = 本次打开酒馆时的状态；current = 随修改更新；undo = 还原前的现场。
  // 页面级 SESSION_MARKER 用来区分「重新运行脚本」和「真正重新打开酒馆」。
  // ===========================================================================
  const sessionSnapshotService = createSessionSnapshotService({
    key: SESSION_SNAPSHOT_KEY,
    getStorage: () => storage(),
    write: (...args) => writeStorageKey(...args),
    getMarker: () => pageSessionMarker(),
    nowIso: () => new Date().toISOString(),
    setTimeout,
    clearTimeout,
  });
  const fallbackSessionMarker = { initialized: new Set() };

  function snapshotPresetKey() {
    return normalizeName(presetName()) || 'in_use';
  }

  function captureToggleSnapshot(data) {
    return session_snapshot_captureToggleSnapshot((data || promptData()).items, () => new Date().toISOString());
  }

  function normalizeToggleSnapshot(snapshot) {
    return session_snapshot_normalizeToggleSnapshot(snapshot, () => new Date().toISOString());
  }

  function compactToggleSnapshot(snapshot) {
    return session_snapshot_compactToggleSnapshot(snapshot, () => new Date().toISOString());
  }

  function toggleSnapshotSignature(snapshot) {
    return session_snapshot_toggleSnapshotSignature(snapshot);
  }

  function sessionSnapshotStore() {
    return sessionSnapshotService.store();
  }

  function sessionSnapshotPayload(store) {
    return session_snapshot_sessionSnapshotPayload(store, () => new Date().toISOString());
  }

  function flushSessionSnapshotStore() {
    return sessionSnapshotService.flush();
  }

  function saveSessionSnapshotStore(store, options = {}) {
    return sessionSnapshotService.save(store, options);
  }

  function pageSessionMarker() {
    try {
      if (!pwin[SESSION_MARKER_KEY] || typeof pwin[SESSION_MARKER_KEY] !== 'object') {
        pwin[SESSION_MARKER_KEY] = { initialized: new Set() };
      }
      const marker = pwin[SESSION_MARKER_KEY];
      // Parent-page Sets belong to another realm. Keep their original receiver.
      if (!marker.initialized || typeof marker.initialized.has !== 'function' || typeof marker.initialized.add !== 'function') {
        marker.initialized = new Set();
      }
      return marker;
    } catch (_) {
      return fallbackSessionMarker;
    }
  }

  // 首次遇到某个预设：上次 current 晋升成这次 baseline，再用酒馆当前状态开一个新的 current。
  // 同一页面里之后每次刷新，只更新 current，不碰 baseline。
  function syncSessionSnapshot(data, options = {}) {
    return sessionSnapshotService.sync(snapshotPresetKey(), (data || promptData()).items, options);
  }

  function currentSessionSnapshots(data) {
    return sessionSnapshotService.current(snapshotPresetKey(), (data || promptData()).items);
  }

  async function applyToggleSnapshot(snapshot, options = {}) {
    const value = normalizeToggleSnapshot(snapshot);
    if (!value) return toast('这份还原记录已经找不到啦～', 'error');
    const data = promptData();
    if (data.mode !== 'api' || !(hostFunction('updatePresetWith') || hostFunction('replacePreset'))) {
      return toast('还原不了：读不到酒馆的预设接口，看看「酒馆助手」开着没～', 'error');
    }
    let applied = false;
    let applyError = null;
    let missing = 0;
    let changed = 0;
    try {
      await enqueueWrite(() => updatePresetCompat((preset) => {
        const prompts = Array.isArray(preset.prompts) ? preset.prompts : [];
        const lookup = buildPromptLookup(prompts);
        value.entries.forEach((entry) => {
          const target = lookupPromptForEntry(lookup, entry);
          if (!target) { missing += 1; return; }
          if ((target.enabled !== false) !== entry.enabled) changed += 1;
          setPromptEnabled(preset, target, entry.enabled);
        });
        return preset;
      }, { render: 'immediate' }));
      applied = true;
    } catch (error) {
      applyError = error;
      console.warn('[Izumi floating window] session snapshot apply failed', error);
    }
    if (!applied) return toast(applyError && applyError.partialCommit
      ? '当前开关可能已改变，但还原未能完整保存；请刷新核对后重试'
      : '没还原上，点↻刷新再试一次看看～', 'error');
    refreshPanel({ skipSnapshotSync: true });
    if (!options.silentToast) {
      const suffix = missing ? `，有 ${missing} 条已经不在这个预设里` : '';
      toast(`${options.label || '已恢复'}：改动 ${changed} 条${suffix}`, missing ? 'error' : 'success');
    }
    return { changed, missing };
  }

  function assertSnapshotOwner(key, owner) {
    assertWriteOwner(owner);
    if (snapshotPresetKey() !== key) throw new Error('预设已切换，已取消旧记录更新；请刷新后重试');
  }

  let sessionRestoreBusy = false;

  async function withSessionRestoreLock(operation) {
    if (sessionRestoreBusy) return;
    sessionRestoreBusy = true;
    try { return await operation(); }
    finally { sessionRestoreBusy = false; }
  }

  async function restoreSessionBaseline() {
    return withSessionRestoreLock(restoreSessionBaselineNow);
  }

  async function undoSessionRestore() {
    return withSessionRestoreLock(undoSessionRestoreNow);
  }

  async function restoreSessionBaselineNow() {
    const key = snapshotPresetKey();
    const owner = captureWriteOwner();
    const data = promptData();
    const snapshots = currentSessionSnapshots(data);
    if (!snapshots || !snapshots.baseline) return toast('这次打开酒馆时的记录还没准备好～', 'error');
    const store = sessionSnapshotStore();
    snapshots.undo = captureToggleSnapshot(data);
    snapshots.updatedAt = new Date().toISOString();
    if (!saveSessionSnapshotStore(store, { immediate: true })) {
      return toast(storageFailureMessage('还原前的记录未保存，未修改当前开关'), 'error');
    }
    const result = await applyToggleSnapshot(snapshots.baseline, { silentToast: true });
    if (!result) return;
    try { assertSnapshotOwner(key, owner); }
    catch (error) { return toast(error.message, 'error'); }
    snapshots.current = captureToggleSnapshot(promptData());
    snapshots.updatedAt = new Date().toISOString();
    const saved = saveSessionSnapshotStore(store, { immediate: true });
    refreshPanel({ skipSnapshotSync: true });
    if (!saved) return toast(storageFailureMessage('当前开关已改变，但还原记录未保存'), 'error');
    toast(`已经回到这次打开酒馆时的状态啦～${result.missing ? `（有 ${result.missing} 条没对上）` : ''}`, result.missing ? 'error' : 'success');
  }

  async function undoSessionRestoreNow() {
    const key = snapshotPresetKey();
    const owner = captureWriteOwner();
    const data = promptData();
    const snapshots = currentSessionSnapshots(data);
    if (!snapshots || !snapshots.undo) return toast('现在还没有可以回退的记录～', 'error');
    const store = sessionSnapshotStore();
    // Persist any pending safety record; a clean record does not need another write.
    if (!flushSessionSnapshotStore()) {
      return toast(storageFailureMessage('回退记录未保存，未修改当前开关'), 'error');
    }
    const target = snapshots.undo;
    const result = await applyToggleSnapshot(target, { silentToast: true });
    if (!result) return;
    try { assertSnapshotOwner(key, owner); }
    catch (error) { return toast(error.message, 'error'); }
    snapshots.current = captureToggleSnapshot(promptData());
    snapshots.undo = null;
    snapshots.updatedAt = new Date().toISOString();
    const saved = saveSessionSnapshotStore(store, { immediate: true });
    refreshPanel({ skipSnapshotSync: true });
    if (!saved) return toast(storageFailureMessage('当前开关已改变，但回退记录未保存'), 'error');
    toast(`已经回到还原前的状态啦～${result.missing ? `（有 ${result.missing} 条没对上）` : ''}`, result.missing ? 'error' : 'success');
  }

  let quickSlotCache = null;

  function quickSlots() {
    if (quickSlotCache) return quickSlotCache.slice();
    const local = storage();
    try {
      const parsed = local ? JSON.parse(local.getItem(QUICK_SLOTS_KEY) || '[]') : [];
      quickSlotCache = Array.from(new Set((Array.isArray(parsed) ? parsed : []).map(normalizeName).filter(Boolean)));
    } catch (_) { quickSlotCache = []; }
    return quickSlotCache.slice();
  }

  function saveQuickSlots(ids) {
    const existing = new Set(layerPlans().map((plan) => plan.id));
    const next = Array.from(new Set((Array.isArray(ids) ? ids : []).map(normalizeName).filter((id) => id && existing.has(id))));
    const saved = writeStorageKey(QUICK_SLOTS_KEY, JSON.stringify(next));
    if (saved) quickSlotCache = next;
    return saved;
  }

  function toggleQuickSlot(planId) {
    const ids = quickSlots().slice();
    const index = ids.indexOf(planId);
    if (index >= 0) {
      ids.splice(index, 1);
      return { ok: saveQuickSlots(ids), added: false };
    }
    ids.push(planId);
    return { ok: saveQuickSlots(ids), added: true };
  }

  function quickSlotPlans() {
    const map = new Map(layerPlans().map((plan) => [plan.id, plan]));
    const values = quickSlots().map((id) => map.get(id)).filter(Boolean);
    if (values.length !== quickSlots().length) saveQuickSlots(values.map((plan) => plan.id));
    return values;
  }

  function sanitizeNativePreset(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
    const snapshot = clone(value);
    if (!snapshot || typeof snapshot !== 'object' || Array.isArray(snapshot)) return null;
    NATIVE_PRESET_CONNECTION_FIELDS.forEach((key) => { delete snapshot[key]; });
    ['apiKey', 'api_key', 'secret_key', 'secretKey', 'proxy_password'].forEach((key) => { delete snapshot[key]; });
    delete snapshot.name;
    try {
      if (JSON.stringify(snapshot).length > MAX_TRANSFER_BYTES) return null;
    } catch (_) {
      return null;
    }
    return snapshot;
  }

  // Tavern Helper is the supported persistence boundary. Native SillyTavern
  // preset files are converted at the transfer edge so imported data can be
  // written with createOrReplacePreset without touching private host storage.
  function helperPresetFromTransfer(value, fallbackName) {
    const wrapper = value && value.preset && typeof value.preset === 'object' ? value : null;
    const raw = wrapper ? value.preset : value;
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
    const isHelper = raw.settings && typeof raw.settings === 'object' && Array.isArray(raw.prompts);
    const native = isHelper ? null : sanitizeNativePreset(raw);
    if (!isHelper && (!native || !Array.isArray(native.prompts))) return null;
    const source = isHelper ? clone(raw) : native;
    const settings = isHelper ? clone(source.settings || {}) : {};
    if (!isHelper) {
      Object.entries(NATIVE_SETTING_MAP).forEach(([helperKey, nativeKey]) => {
        if (Object.prototype.hasOwnProperty.call(source, nativeKey)) settings[helperKey] = clone(source[nativeKey]);
      });
    }
    const prompts = (Array.isArray(source.prompts) ? source.prompts : [])
      .map(normalizePresetPromptForWrite).filter(Boolean);
    const unused = (Array.isArray(source.prompts_unused) ? source.prompts_unused : [])
      .map(normalizePresetPromptForWrite).filter(Boolean);
    if (!prompts.length && !unused.length) return null;
    return {
      name: normalizeName((wrapper && wrapper.name) || source.name || fallbackName).slice(0, 80),
      preset: sanitizePresetForWrite({
        settings,
        prompts,
        prompts_unused: unused,
        // Native SillyTavern files carry Tavern Helper scripts under
        // extensions.tavern_helper; keep every extension field intact.
        extensions: source.extensions && typeof source.extensions === 'object' ? clone(source.extensions) : {},
      }),
    };
  }

  function collectImportedPresets(value, output, fallbackName) {
    if (Array.isArray(value)) {
      value.forEach((entry, index) => collectImportedPresets(entry, output, `${fallbackName || '导入预设'} ${index + 1}`));
      return;
    }
    if (!value || typeof value !== 'object') return;
    if (Array.isArray(value.presets)) {
      value.presets.forEach((entry, index) => collectImportedPresets(entry, output, `${fallbackName || '导入预设'} ${index + 1}`));
      return;
    }
    if (Array.isArray(value.plans)) {
      value.plans.forEach((entry, index) => {
        const plan = entry && entry.helperPreset
          ? { name: entry.name, preset: entry.helperPreset }
          : (entry && entry.nativePreset ? { name: entry.name, preset: entry.nativePreset } : entry);
        const converted = helperPresetFromTransfer(plan, `${fallbackName || '导入预设'} ${index + 1}`);
        if (converted) output.push(converted);
      });
      return;
    }
    const converted = helperPresetFromTransfer(value, fallbackName);
    if (converted) {
      if (!converted.name) converted.name = `泉此方导入 ${output.length + 1}`;
      output.push(converted);
    }
  }

  function tavernPresetFunctions() {
    return {
      names: hostFunction('getPresetNames'),
      get: hostFunction('getPreset'),
      write: hostFunction('createOrReplacePreset'),
      load: hostFunction('loadPreset'),
    };
  }

  function assertImportInstance() {
    // Import/load intentionally changes presets; only instance lifetime cancels it.
    if (!isCurrentIzumiInstance()) throw new Error('脚本实例已失效，已取消后续预设导入或加载');
  }

  async function importTavernPresets(value, options = {}) {
    assertImportInstance();
    const api = tavernPresetFunctions();
    if (!api.write) throw new Error('当前酒馆助手版本没有 createOrReplacePreset 接口');
    const entries = [];
    collectImportedPresets(value, entries, options.fallbackName || '导入预设');
    const unique = new Map();
    entries.forEach((entry) => {
      const name = normalizeName(entry && entry.name).slice(0, 80);
      if (name && name !== 'in_use' && entry.preset) unique.set(name, { name, preset: entry.preset });
    });
    if (!unique.size) throw new Error('没有识别到兼容的酒馆预设');
    // 预设文件可以在 extensions.tavern_helper 里夹带酒馆助手脚本，导入后是会被执行的。
    // 这是酒馆预设分享机制本身的特性，不是这个悬浮窗引入的，但一键导入太顺手了，
    // 所以碰到夹带脚本的包，先停下来问一句。
    const withScripts = Array.from(unique.values()).filter((entry) => {
      const ext = entry.preset && entry.preset.extensions;
      const helper = ext && typeof ext === 'object' ? ext.tavern_helper : null;
      if (!helper || typeof helper !== 'object') return false;
      const scripts = helper.scripts || helper.script_data || helper;
      return Array.isArray(scripts) ? scripts.length > 0 : Object.keys(scripts || {}).length > 0;
    });
    if (withScripts.length && !options.silent) {
      const ask = pwin.confirm || (typeof confirm === 'function' ? confirm : null);
      const names = withScripts.slice(0, 3).map((entry) => entry.name).join('、');
      const more = withScripts.length > 3 ? ` 等 ${withScripts.length} 个` : '';
      const warn = `这 ${withScripts.length} 个预设里夹带了酒馆助手脚本：${names}${more}\n\n`
        + '预设是可以带脚本的，导入之后它们会在酒馆里运行。\n'
        + '如果这个文件不是你自己做的、或者不是从信得过的地方拿的，建议先别导入～\n\n还要继续吗？';
      if (ask && !ask.call(pwin, warn)) throw new Error('那就先不导入啦～');
    }
    const imported = [];
    for (const entry of unique.values()) {
      assertImportInstance();
      await api.write(entry.name, entry.preset, { render: 'none' });
      assertImportInstance();
      imported.push(entry);
    }
    if (options.loadFirst && imported[0] && api.load) {
      assertImportInstance();
      const loaded = api.load(imported[0].name);
      if (loaded === false) throw new Error(`酒馆未能载入预设“${imported[0].name}”`);
    }
    return imported;
  }

  async function readCurrentApiConfig() {
    const context = hostContext();
    if (!context || !context.chatCompletionSettings) throw new Error('无法读取 SillyTavern 当前连接');
    const settings = context.chatCompletionSettings;
    const source = normalizeName(settings.chat_completion_source);
    let model = '';
    try {
      if (typeof context.getChatCompletionModel === 'function') model = context.getChatCompletionModel(settings) || '';
    } catch (_) {}
    if (!model && MODEL_SETTING_KEYS[source]) model = settings[MODEL_SETTING_KEYS[source]] || '';
    return normalizeApiConfig({
      mainApi: context.mainApi,
      source,
      apiUrl: settings.custom_url,
      model,
      apiKey: currentApiConfig.apiKey,
      saveKey: currentApiConfig.saveKey,
      postProcessing: settings.custom_prompt_post_processing,
      maxTokens: settings.openai_max_tokens,
      temperature: settings.temp_openai,
      topP: settings.top_p_openai,
      stream: settings.stream_openai,
      includeBody: settings.custom_include_body,
      excludeBody: settings.custom_exclude_body,
      includeHeaders: settings.custom_include_headers,
    });
  }

  function apiElement(name) {
    return pdoc.getElementById(`${ID}-api-${name}`);
  }

  function renderModelOptions(models, selected) {
    const list = normalizeModels(models);
    const datalist = apiElement('models');
    if (datalist) datalist.innerHTML = list.map((model) => `<option value="${esc(model)}"></option>`).join('');
    const select = apiElement('model-list');
    if (!select) return;
    const options = [];
    if (selected && !list.includes(selected)) options.push(`<option value="${esc(selected)}">当前模型：${esc(selected)}</option>`);
    list.forEach((model) => options.push(`<option value="${esc(model)}">${esc(model)}</option>`));
    select.innerHTML = options.length ? options.join('') : '<option value="">点击“拉取模型”加载列表</option>';
    if (selected) select.value = selected;
  }

  function readApiForm() {
    const root = apiElement('form');
    if (!root) return normalizeApiConfig(currentApiConfig);
    const value = {
      mainApi: currentApiConfig.mainApi,
      source: currentApiConfig.source,
      apiUrl: apiElement('url') && apiElement('url').value,
      model: apiElement('model') && apiElement('model').value,
      apiKey: apiElement('key') && apiElement('key').value,
      saveKey: !!(apiElement('save-key') && apiElement('save-key').checked),
      postProcessing: apiElement('post-processing') && apiElement('post-processing').value,
      maxTokens: apiElement('max-tokens') && apiElement('max-tokens').value,
      temperature: apiElement('temperature') && apiElement('temperature').value,
      topP: apiElement('top-p') && apiElement('top-p').value,
      stream: !!(apiElement('stream') && apiElement('stream').checked),
      includeBody: apiElement('include-body') && apiElement('include-body').value,
      excludeBody: apiElement('exclude-body') && apiElement('exclude-body').value,
      includeHeaders: apiElement('include-headers') && apiElement('include-headers').value,
    };
    return normalizeApiConfig(value);
  }

  function renderApiConfig(config) {
    currentApiConfig = normalizeApiConfig(config);
    const value = currentApiConfig;
    let keyHash = 0;
    for (let i = 0; i < value.apiKey.length; i += 1) keyHash = ((keyHash << 5) - keyHash + value.apiKey.charCodeAt(i)) | 0;
    const signature = JSON.stringify({
      value: Object.assign({}, value, { apiKey: value.apiKey ? `${value.apiKey.length}:${keyHash}` : '' }),
      models: availableModels,
    });
    if (signature === lastApiRenderSignature) return;
    lastApiRenderSignature = signature;
    const fields = {
      'main-api': value.mainApi === 'openai' ? '聊天补全' : (value.mainApi || '未连接'),
      source: SOURCE_LABELS[value.source] || value.source || '未选择',
      url: value.apiUrl,
      model: value.model,
      'post-processing': value.postProcessing,
      'max-tokens': value.maxTokens,
      temperature: value.temperature,
      'top-p': value.topP,
      'include-body': value.includeBody,
      'exclude-body': value.excludeBody,
      'include-headers': value.includeHeaders,
    };
    Object.keys(fields).forEach((name) => {
      const element = apiElement(name);
      if (element) element.value = fields[name] == null ? '' : fields[name];
    });
    const key = apiElement('key');
    if (key && Object.prototype.hasOwnProperty.call(config || {}, 'apiKey')) key.value = value.apiKey;
    const saveKey = apiElement('save-key');
    if (saveKey) saveKey.checked = value.saveKey;
    const stream = apiElement('stream');
    if (stream) stream.checked = value.stream;
    const customOnly = ['url', 'include-body', 'exclude-body', 'include-headers'];
    customOnly.forEach((name) => {
      const element = apiElement(name);
      if (element) element.disabled = value.source !== 'custom';
    });
    renderModelOptions(availableModels, value.model);
    const status = apiElement('status');
    if (status) {
      const connected = value.mainApi === 'openai' && !!value.source;
      status.textContent = connected ? '已读取酒馆连接' : '当前不是聊天补全';
      status.classList.toggle('kagami', !connected);
    }
  }

  function hasApiConfig(config) {
    const value = normalizeApiConfig(config);
    return value.mainApi === 'openai' && !!value.source;
  }

  async function applyApiConfig(input) {
    const value = normalizeApiConfig(input);
    const context = hostContext();
    const errors = [];
    if (!context || context.mainApi !== 'openai' || !context.chatCompletionSettings) {
      return { ok: false, skipped: false, errors: ['酒馆现在不是聊天补全模式，拉不了模型～'] };
    }
    const settings = context.chatCompletionSettings;
    const source = normalizeName(settings.chat_completion_source);
    if (value.source && value.source !== source) errors.push('聊天补全来源已变化，请先重新读取');
    const numericSettings = {};
    const parseNumber = (key, raw, label, integer) => {
      if (raw === '') return;
      const number = Number(raw);
      if (!Number.isFinite(number) || (integer && (!Number.isInteger(number) || number <= 0))) {
        errors.push(`${label}不是有效数字`);
        return;
      }
      numericSettings[key] = number;
    };
    parseNumber('openai_max_tokens', value.maxTokens, '回复长度', true);
    parseNumber('temp_openai', value.temperature, '随机程度', false);
    parseNumber('top_p_openai', value.topP, '多样性', false);
    if (!errors.length) {
      const modelKey = MODEL_SETTING_KEYS[source];
      if (modelKey && value.model) settings[modelKey] = value.model;
      settings.custom_prompt_post_processing = value.postProcessing;
      if (source === 'custom') {
        settings.custom_url = value.apiUrl;
        settings.custom_include_body = value.includeBody;
        settings.custom_exclude_body = value.excludeBody;
        settings.custom_include_headers = value.includeHeaders;
      }
      Object.assign(settings, numericSettings);
      settings.stream_openai = value.stream;
      if (typeof context.saveSettingsDebounced === 'function') context.saveSettingsDebounced();
    }
    if (!errors.length) {
      const nativeFields = {
        '#custom_api_url_text': settings.custom_url,
        '#custom_model_id': source === 'custom' ? settings.custom_model : '',
        '#custom_prompt_post_processing': settings.custom_prompt_post_processing,
        '#openai_max_tokens': settings.openai_max_tokens,
        '#temp_openai': settings.temp_openai,
        '#top_p_openai': settings.top_p_openai,
        '#custom_include_body': settings.custom_include_body,
        '#custom_exclude_body': settings.custom_exclude_body,
        '#custom_include_headers': settings.custom_include_headers,
      };
      Object.entries(nativeFields).forEach(([selector, fieldValue]) => {
        const element = pdoc.querySelector(selector);
        if (!element || fieldValue == null) return;
        element.value = fieldValue;
        try {
          const EventCtor = pwin.Event || Event;
          element.dispatchEvent(new EventCtor(element.tagName === 'SELECT' ? 'change' : 'input', { bubbles: true }));
        } catch (_) {}
      });
      const nativeStream = pdoc.querySelector('#stream_toggle');
      if (nativeStream) {
        nativeStream.checked = !!settings.stream_openai;
        try {
          const EventCtor = pwin.Event || Event;
          nativeStream.dispatchEvent(new EventCtor('change', { bubbles: true }));
        } catch (_) {}
      }
    }
    if (errors.length) {
      currentApiConfig = value;
    } else {
      const refreshed = await readCurrentApiConfig();
      refreshed.apiKey = value.apiKey;
      refreshed.saveKey = value.saveKey;
      currentApiConfig = refreshed;
    }
    renderApiConfig(currentApiConfig);
    return { ok: errors.length === 0, skipped: false, errors };
  }

  function capturePlan(name, data = promptData()) {
    const fields = {};
    if (data.preset) {
      Object.keys(data.preset).forEach((key) => {
        if (key === 'prompts' || key === 'extensions' || key === 'prompt_order' || key === 'settings') return;
        const value = data.preset[key];
        if (!SAFE_PRESET_FIELDS.has(key)) return;
        if (value === null || ['string', 'number', 'boolean'].includes(typeof value)) fields[key] = value;
      });
      if (data.preset.settings && typeof data.preset.settings === 'object') {
        fields.settings = Object.fromEntries(Object.entries(data.preset.settings)
          .filter(([key]) => SAFE_PRESET_SETTINGS.has(key))
          .map(([key, value]) => [key, clone(value)]));
      }
    }
    const api = readApiForm();
    return {
      name,
      savedAt: new Date().toISOString(),
      presetName: presetName(),
      promptStates: data.items.map((item) => ({ id: item.id, name: item.name, index: item.index, enabled: item.enabled, layer: item.pinnedLayer || '' })),
      promptEdits: normalizePromptEdits(data.items.map((item) => ({
        id: item.id,
        name: item.name,
        index: item.index,
        content: item.content,
        contentKey: item.contentKey,
        role: item.role,
        triggers: item.triggers,
        injectionPosition: item.injectionPosition,
        injectionDepth: item.injectionDepth,
        injectionOrder: item.injectionOrder,
        marker: item.marker,
        layer: item.pinnedLayer || '',
      }))),
      promptOrder: data.preset && Array.isArray(data.preset.prompt_order) ? clone(data.preset.prompt_order) : null,
      presetFields: normalizeSafePresetFields(fields),
      // 大方案保存 = 大方案配置 + 整个小方案库，导出/导入永远成套走。
      layerPlans: layerPlanStore().plans.map((plan) => clone(plan)),
      activeLayerPlans: Object.assign({}, layerPlanStore().active),
      quickSlots: quickSlots().slice(),
      // nativePreset 与 helperPreset 是同一份预设的两份完整拷贝，白白吃掉一倍空间。
      // 载入时优先走 helperPreset，所以只有在环境用不上它的时候才留 nativePreset。
      nativePreset: (hostFunction('createOrReplacePreset') && data.preset && Array.isArray(data.preset.prompts))
        ? null
        : sanitizeNativePreset(data.preset),
      helperPreset: data.preset && Array.isArray(data.preset.prompts)
        ? sanitizePresetForWrite(data.preset)
        : null,
      apiConfig: Object.assign({}, api, { apiKey: api.saveKey ? api.apiKey : '' }),
    };
  }

  function nativePresetManager() {
    const context = hostContext();
    if (!context || context.mainApi !== 'openai' || typeof context.getPresetManager !== 'function') return null;
    try {
      const manager = context.getPresetManager('openai');
      return manager && typeof manager.savePreset === 'function' ? manager : null;
    } catch (_) {
      return null;
    }
  }

  function nativePresetNames() {
    const manager = nativePresetManager();
    if (!manager || typeof manager.getAllPresets !== 'function') return [];
    try {
      const names = manager.getAllPresets();
      return Array.isArray(names) ? names.map(normalizeName).filter(Boolean) : [];
    } catch (_) {
      return [];
    }
  }

  function nativePromptSnapshot(prompt) {
    const value = clone(prompt && typeof prompt === 'object' ? prompt : {});
    if (value.id && !value.identifier) value.identifier = String(value.id);
    delete value.id;
    if (value.position && typeof value.position === 'object' && !Array.isArray(value.position)) {
      value.injection_position = promptInjectionPosition(value);
      value.injection_depth = promptInjectionDepth(value);
      value.injection_order = promptInjectionOrder(value);
      delete value.position;
    }
    if (Array.isArray(value.triggers) && !Array.isArray(value.injection_trigger)) {
      value.injection_trigger = clone(value.triggers);
    }
    delete value.triggers;
    delete value.injectionPosition;
    delete value.injectionDepth;
    delete value.injectionOrder;
    return value;
  }

  function syncNativePrompt(target, source) {
    if (!target || !source) return;
    ['name', 'enabled', 'role', 'system_prompt', 'marker', 'forbid_overrides'].forEach((key) => {
      if (Object.prototype.hasOwnProperty.call(source, key)) target[key] = clone(source[key]);
    });
    if (promptLayerHint(source)) setPromptLayerHint(target, promptLayerHint(source));
    const sourceContentKey = typeof source.content === 'string'
      ? 'content'
      : (typeof source.text === 'string'
        ? 'text'
        : (typeof source.system_prompt === 'string' ? 'system_prompt' : ''));
    if (sourceContentKey) {
      const targetContentKey = typeof target[sourceContentKey] === 'string'
        ? sourceContentKey
        : (typeof target.content === 'string' ? 'content' : sourceContentKey);
      target[targetContentKey] = source[sourceContentKey];
    }
    const triggers = promptTriggers(source);
    if (Array.isArray(target.injection_trigger)) target.injection_trigger = clone(triggers);
    else if (target.extra && Array.isArray(target.extra.injection_trigger)) target.extra.injection_trigger = clone(triggers);
    else target.injection_trigger = clone(triggers);
    if (Object.prototype.hasOwnProperty.call(target, 'injection_position') || !(target.position && typeof target.position === 'object')) {
      target.injection_position = promptInjectionPosition(source);
      target.injection_depth = promptInjectionDepth(source);
      target.injection_order = promptInjectionOrder(source);
    } else {
      target.position = Object.assign({}, target.position, {
        type: promptInjectionPosition(source) === 1 ? 'in_chat' : 'relative',
        depth: promptInjectionDepth(source),
        order: promptInjectionOrder(source),
      });
    }
  }

  function nativePromptOrder(value) {
    if (!Array.isArray(value)) return value;
    return value.map((entry) => {
      const row = clone(entry);
      if (!row || !Array.isArray(row.order)) return row;
      row.order = row.order.map((item) => {
        const orderItem = clone(item);
        if (orderItem && orderItem.id && !orderItem.identifier) orderItem.identifier = String(orderItem.id);
        if (orderItem) delete orderItem.id;
        return orderItem;
      });
      return row;
    });
  }

  const NATIVE_SETTING_MAP = {
    max_context: 'openai_max_context', max_completion_tokens: 'openai_max_tokens', reply_count: 'n',
    should_stream: 'stream_openai', stream: 'stream_openai', temperature: 'temperature',
    frequency_penalty: 'frequency_penalty', presence_penalty: 'presence_penalty',
    repetition_penalty: 'repetition_penalty', top_p: 'top_p', min_p: 'min_p', top_k: 'top_k',
    top_a: 'top_a', seed: 'seed', squash_system_messages: 'squash_system_messages',
    reasoning_effort: 'reasoning_effort', request_thoughts: 'show_thoughts',
    request_images: 'request_images', enable_function_calling: 'function_calling',
    enable_web_search: 'enable_web_search',
  };

  function writeNativePresetFields(snapshot, fields) {
    if (!fields || typeof fields !== 'object') return;
    Object.entries(fields).forEach(([key, value]) => {
      if (key === 'settings' && value && typeof value === 'object') {
        Object.entries(value).forEach(([setting, settingValue]) => {
          const targetKey = NATIVE_SETTING_MAP[setting] || setting;
          snapshot[targetKey] = clone(settingValue);
        });
        return;
      }
      if (key === 'name') return;
      const targetKey = NATIVE_SETTING_MAP[key] || key;
      snapshot[targetKey] = clone(value);
    });
    delete snapshot.settings;
  }

  function newNativePrompt(edit, state, prompts) {
    // Raw SillyTavern snapshots use identifier + injection_* + prompt_order.
    const id = normalizeName(edit && edit.id || state && state.id) || createPromptIdentifier(prompts);
    const inChat = Object.prototype.hasOwnProperty.call(edit || {}, 'position')
      ? Number(edit.position) === 1
      : Number(edit && edit.injectionPosition) === 1;
    const value = {
      identifier: id,
      system_prompt: false,
      enabled: state ? state.enabled !== false : true,
      marker: edit && edit.marker === true,
      name: normalizeName(edit && edit.name || state && state.name),
      role: normalizeName(edit && edit.role) || 'system',
      content: edit && typeof edit.content === 'string' && !edit.marker ? edit.content : '',
      injection_position: inChat ? 1 : 0,
      injection_depth: Number(edit && edit.injectionDepth) || 4,
      injection_order: Number(edit && edit.injectionOrder) || 100,
      injection_trigger: edit && Array.isArray(edit.triggers) ? clone(edit.triggers) : [],
    };
    if (edit && edit.layer) setPromptLayerHint(value, edit.layer);
    if (edit && edit.functionSection) setPromptFunctionSectionHint(value, edit.functionSection);
    return value;
  }

  function newPresetPrompt(edit, state, prompts) {
    // This is the exact TavernHelper PresetPrompt shape accepted by replacePreset.
    const id = normalizeName(edit && edit.id || state && state.id) || createPromptIdentifier(prompts);
    const inChat = Object.prototype.hasOwnProperty.call(edit || {}, 'position')
      ? Number(edit.position) === 1
      : Number(edit && edit.injectionPosition) === 1;
    const extra = {};
    if (edit && Array.isArray(edit.triggers)) extra.injection_trigger = clone(edit.triggers);
    const value = {
      id,
      name: normalizeName(edit && edit.name || state && state.name),
      enabled: state ? state.enabled !== false : true,
      position: inChat
        ? { type: 'in_chat', depth: Number(edit && edit.injectionDepth) || 4, order: Number(edit && edit.injectionOrder) || 100 }
        : { type: 'relative' },
      role: normalizeName(edit && edit.role) || 'system',
      content: edit && typeof edit.content === 'string' && !edit.marker ? edit.content : '',
      extra,
    };
    if (edit && edit.layer) setPromptLayerHint(value, edit.layer);
    if (edit && edit.functionSection) setPromptFunctionSectionHint(value, edit.functionSection);
    return value;
  }

  function applyPlanToNativeSnapshot(snapshot, plan) {
    const safeFields = normalizeSafePresetFields(plan && plan.presetFields);
    writeNativePresetFields(snapshot, safeFields);
    const states = Array.isArray(plan && plan.promptStates) ? plan.promptStates : [];
    const edits = Array.isArray(plan && plan.promptEdits) ? plan.promptEdits : [];
    const existing = Array.isArray(snapshot.prompts) ? snapshot.prompts.map((prompt) => clone(prompt)) : [];
    edits.forEach((edit, index) => {
      const state = matchPrompt(states, edit, true) || states[index] || null;
      let target = matchPrompt(existing, edit, true);
      if (!target) {
        target = newNativePrompt(edit, state);
        existing.push(target);
      }
      applyNativePromptEdit(target, edit);
      if (state && state.layer && !edit.layer) setPromptLayerHint(target, state.layer);
    });
    snapshot.prompts = existing;
    if (Array.isArray(plan && plan.promptOrder)) snapshot.prompt_order = nativePromptOrder(plan.promptOrder);
    states.forEach((state) => {
      const target = matchPrompt(snapshot.prompts, state, true);
      if (!target) return;
      setPromptEnabled(snapshot, target, state.enabled !== false);
      if (state.layer) setPromptLayerHint(target, state.layer);
    });
    snapshot.prompts.forEach((prompt) => appendPromptOrderReference(snapshot, promptIdentifier(prompt)));
  }

  function stripNativeConnectionFields(snapshot) {
    NATIVE_PRESET_CONNECTION_FIELDS.forEach((key) => { delete snapshot[key]; });
    ['apiKey', 'api_key', 'secret_key', 'secretKey'].forEach((key) => { delete snapshot[key]; });
  }

  function nativePresetSnapshot(plan, options = {}) {
    const manager = nativePresetManager();
    const data = options.promptData || promptData();
    const fromPlan = options.fromPlan === true;
    const planPreset = fromPlan ? sanitizeNativePreset(plan && plan.nativePreset) : null;
    if (!manager || (!data.preset && !planPreset)) throw new Error('读不到酒馆的对话补全预设～');
    let selectedName = '';
    let rawPreset = planPreset;
    try {
      selectedName = typeof manager.getSelectedPresetName === 'function' ? normalizeName(manager.getSelectedPresetName()) : presetName();
      if (!rawPreset && typeof manager.getCompletionPresetByName === 'function') {
        const targetName = fromPlan ? normalizeName(plan && plan.name) : selectedName;
        rawPreset = targetName ? manager.getCompletionPresetByName(targetName) : null;
        if (!rawPreset && selectedName && targetName !== selectedName) rawPreset = manager.getCompletionPresetByName(selectedName);
      }
    } catch (_) {}
    const normalized = data.preset || planPreset;
    const snapshot = clone(rawPreset && typeof rawPreset === 'object' ? rawPreset : normalized);
    const removedIds = new Set((Array.isArray(options.removedPromptIds) ? options.removedPromptIds : [])
      .map(normalizeName)
      .filter(Boolean));
    if (removedIds.size) {
      snapshot.prompts = (Array.isArray(snapshot.prompts) ? snapshot.prompts : [])
        .filter((prompt) => !removedIds.has(promptIdentifier(prompt)));
      promptOrderLists(snapshot).forEach((order) => {
        for (let index = order.length - 1; index >= 0; index -= 1) {
          if (removedIds.has(String(order[index] && (order[index].identifier || order[index].id) || ''))) order.splice(index, 1);
        }
      });
    }
    if (fromPlan) {
      applyPlanToNativeSnapshot(snapshot, plan);
    } else {
      const normalizedFields = {};
      Object.keys(normalized).forEach((key) => {
        if (!SAFE_PRESET_FIELDS.has(key)) return;
        const value = normalized[key];
        if (value === null || ['string', 'number', 'boolean'].includes(typeof value)) normalizedFields[key] = value;
      });
      if (normalized.settings && typeof normalized.settings === 'object') normalizedFields.settings = normalized.settings;
      writeNativePresetFields(snapshot, normalizedFields);
      if (Array.isArray(normalized.prompts)) {
        const existing = Array.isArray(snapshot.prompts) ? snapshot.prompts : [];
        normalized.prompts.forEach((prompt) => {
          const id = promptIdentifier(prompt);
          const target = (id ? existing.find((candidate) => promptIdentifier(candidate) === id) : null)
            || existing.find((candidate) => normalizeName(candidate && candidate.name) === normalizeName(prompt && prompt.name));
          if (target) syncNativePrompt(target, prompt);
          else existing.push(nativePromptSnapshot(prompt));
        });
        snapshot.prompts = existing;
        data.items.forEach((item) => {
          const target = matchPrompt(snapshot.prompts, item, true);
          if (target) setPromptEnabled(snapshot, target, item.enabled);
        });
      }
      syncNativePromptOrderFromPreset(snapshot, normalized.prompts);
      snapshot.prompts.forEach((prompt) => appendPromptOrderReference(snapshot, promptIdentifier(prompt)));
    }
    const api = normalizeApiConfig(fromPlan
      ? (plan && plan.apiConfig ? plan.apiConfig : {})
      : (plan && plan.apiConfig ? plan.apiConfig : readApiForm()));
    if (!fromPlan || hasApiConfig(api)) {
      if (api.maxTokens !== '' && Number.isFinite(Number(api.maxTokens))) snapshot.openai_max_tokens = Number(api.maxTokens);
      if (api.temperature !== '' && Number.isFinite(Number(api.temperature))) snapshot.temperature = Number(api.temperature);
      if (api.topP !== '' && Number.isFinite(Number(api.topP))) snapshot.top_p = Number(api.topP);
      snapshot.stream_openai = api.stream;
    }
    stripNativeConnectionFields(snapshot);
    delete snapshot.name;
    return snapshot;
  }

  async function saveNativePreset(name, plan, options = {}) {
    const manager = nativePresetManager();
    if (!manager) throw new Error('SillyTavern 对话补全预设管理器不可用');
    const snapshot = nativePresetSnapshot(plan, options);
    nativePresetTransition = name;
    try {
      await manager.savePreset(name, snapshot);
      let selected = typeof manager.getSelectedPresetName === 'function' ? normalizeName(manager.getSelectedPresetName()) : '';
      if (selected !== name && typeof manager.findPreset === 'function' && typeof manager.selectPreset === 'function') {
        const value = manager.findPreset(name);
        if (value !== undefined && value !== null) manager.selectPreset(value);
        selected = typeof manager.getSelectedPresetName === 'function' ? normalizeName(manager.getSelectedPresetName()) : name;
      }
      if (selected && selected !== name) throw new Error(`酒馆仍停留在预设“${selected}”`);
      knownPreset = name;
      const data = options.promptData || null;
      knownPromptShape = data && Array.isArray(data.items)
        ? data.items.map((item) => `${item.id}|${item.name}|${item.index}`).join('\n')
        : promptShape();
      nativePresetTransition = '';
      scheduleRefresh(240, { renderApi: false });
      return { name, snapshot };
    } catch (error) {
      nativePresetTransition = '';
      throw error;
    }
  }

  function selectedNativePresetName() {
    const getLoadedName = hostFunction('getLoadedPresetName');
    try {
      const name = normalizeName(getLoadedName && getLoadedName());
      if (name && name !== 'in_use') return name;
    } catch (_) {}
    return normalizeName(presetName()) || '';
  }

  function presetDataForNativeSave(preset) {
    return {
      mode: 'api',
      preset,
      items: presetPromptItems(preset),
    };
  }

  async function persistCurrentPresetToNative(data = promptData(), owner = captureWriteOwner()) {
    return getPresetPersistenceService().persistNamed(data, owner);
  }

  function afterNamedPresetPersist(name, data) {
    regexLinkageSignature = '';
    scheduleRegexLinkage();
    knownPreset = name;
    knownPromptShape = data.items.map((item) => `${item.id}|${item.name}|${item.index}`).join('\n');
    scheduleRefresh(240, { renderApi: false });
  }

  async function saveCurrentNativePreset() {
    if (savingPlan) return;
    const button = pdoc.querySelector(`#${PANEL_ID} [data-action="save-current"]`);
    const data = promptData();
    if (data.mode !== 'api') return toast('写不进酒馆的对话补全预设，可能是「酒馆助手」没开～', 'error');
    savingPlan = true;
    if (button) {
      button.disabled = true;
      button.textContent = '保存中…';
    }
    try {
      const name = await enqueueWrite(() => persistCurrentPresetToNative(data));
      refreshPanel();
      toast(`已保存到酒馆预设“${name}”`, 'success');
    } catch (error) {
      toast(error && error.message ? error.message : '酒馆预设保存失败', 'error');
    } finally {
      savingPlan = false;
      if (button) {
        button.disabled = false;
        button.textContent = '保存当前酒馆预设';
      }
    }
  }

  let presetPersistenceService = null;
  let runtimeDiagnostics = null;
  let currentApiConfig = emptyApiConfig();
  let availableModels = [];
  let lastApiRenderSignature = '';
  let editingPrompt = null;
  let editorOpener = null;
  let savingPlan = false;

  function getRuntimeDiagnostics() {
    if (!runtimeDiagnostics) {
      runtimeDiagnostics = createDiagnostics({
        capabilityCollector: () => ({
          getPreset: typeof hostFunction('getPreset') === 'function',
          replacePreset: typeof hostFunction('replacePreset') === 'function',
          updatePresetWith: typeof hostFunction('updatePresetWith') === 'function',
          createOrReplacePreset: typeof hostFunction('createOrReplacePreset') === 'function',
          loadPreset: typeof hostFunction('loadPreset') === 'function',
        }),
      });
    }
    return runtimeDiagnostics;
  }

  function recordPresetSaveResult(result) {
    return getRuntimeDiagnostics().recordResult(result);
  }

  function getPresetPersistenceService() {
    if (!presetPersistenceService) {
      // Factories and callbacks are lazy: early startup must not touch owner/UI state.
      presetPersistenceService = createPresetPersistenceService({
        capabilities: (name) => hostFunction(name),
        getOwner: () => ({ token: INSTANCE_TOKEN, preset: normalizeName(selectedNativePresetName()) }),
        isCurrentInstance: () => isCurrentIzumiInstance(),
        ensureInstance: () => assertImportInstance(),
        normalizePreset: (value) => sanitizePresetForWrite(value),
        toNativeData: (value) => presetDataForNativeSave(value),
        invalidate: () => invalidatePromptDataCache(),
        afterNamedPersist: (name, data) => afterNamedPresetPersist(name, data),
        persistNamed: (...args) => persistCurrentPresetToNative(...args),
        onResult: (result) => recordPresetSaveResult(result),
      });
    }
    return presetPersistenceService;
  }

  function captureWriteOwner() {
    return getPresetPersistenceService().captureOwner();
  }

  function assertWriteOwner(owner) {
    return getPresetPersistenceService().assertOwner(owner);
  }

  function enqueueWrite(task) {
    return getPresetPersistenceService().enqueue(task);
  }

  // Normalize only the TavernHelper API representation. Native raw preset conversion
  // remains in nativePresetSnapshot/newNativePrompt for file import and export.
  function normalizePresetPromptForWrite(prompt) {
    if (!prompt || typeof prompt !== 'object' || Array.isArray(prompt)) return null;
    const id = normalizeName(prompt.id || prompt.identifier);
    if (!id) return null;
    const extra = prompt.extra && typeof prompt.extra === 'object' && !Array.isArray(prompt.extra)
      ? clone(prompt.extra)
      : {};
    if (Array.isArray(prompt.injection_trigger)) extra.injection_trigger = clone(prompt.injection_trigger);
    if (prompt.izumi_layer) extra.izumi_layer = prompt.izumi_layer;
    if (prompt.izumi_function_section) extra.izumi_function_section = prompt.izumi_function_section;
    const role = normalizeName(prompt.role).toLowerCase();
    const inChat = promptInjectionPosition(prompt) === 1;
    const value = {
      id,
      name: normalizeName(prompt.name) || id,
      enabled: prompt.enabled !== false,
      position: inChat
        ? { type: 'in_chat', depth: promptInjectionDepth(prompt), order: promptInjectionOrder(prompt) }
        : { type: 'relative' },
      role: ['system', 'user', 'assistant'].includes(role) ? role : 'system',
    };
    if (typeof prompt.content === 'string') value.content = prompt.content;
    if (Object.keys(extra).length) value.extra = extra;
    return value;
  }

  function sanitizePresetForWrite(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
    const next = clone(value);
    ['prompts', 'prompts_unused'].forEach((key) => {
      if (Array.isArray(next[key])) next[key] = next[key].map(normalizePresetPromptForWrite).filter(Boolean);
    });
    // prompt_order is a raw SillyTavern storage detail, not a Preset API field.
    delete next.prompt_order;
    return next;
  }

  async function updatePresetCompat(updater, options = {}) {
    return getPresetPersistenceService().update(updater, options);
  }

  async function saveHelperPreset(name, preset, options = {}) {
    return getPresetPersistenceService().saveImported(name, preset, options);
  }

  async function applyPlan(plan) {
    const value = normalizePlan(plan);
    if (!value) return toast('这个方案数据读不出来，可能文件不完整或者不是方案包～', 'error');
    try {
      if (value.helperPreset && hostFunction('createOrReplacePreset')) {
        await saveHelperPreset(value.name, value.helperPreset, { render: 'none', load: true });
      } else {
        await saveNativePreset(value.name, value, { fromPlan: true });
      }
    } catch (error) {
      const message = error && error.message ? error.message : '酒馆预设保存失败';
      return toast(`方案未载入：${message}`, 'error');
    }
    if (value.apiConfig && hasApiConfig(value.apiConfig)) {
      const apiResult = await applyApiConfig(value.apiConfig);
      if (!apiResult.ok) {
        refreshPanel();
        return toast(`已切换到“${value.name}”，但连接参数未应用：${apiResult.errors.join('、')}`, 'error');
      }
    }
    refreshPanel();
    let merged = 0;
    try { merged = mergeLayerPlans(value.layerPlans, value.activeLayerPlans, value.quickSlots); }
    catch (error) {
      return toast(`预设已载入，但附带小方案未能完整保存：${error.message}`, 'error');
    }
    detectActiveLayerPlans();
    renderItems();
    const extra = merged ? `，并带入 ${merged} 个小方案` : '';
    toast(`已载入方案“${value.name}”（含条目开关与酒馆助手脚本）${extra}`, 'success');
  }

  function uniqueBigPlanName(name) {
    const base = normalizeName(name).replace(/\s+\d+$/, '') || '泉此方方案';
    const taken = new Set(plans().map((plan) => plan.name).concat(nativePresetNames()));
    if (!taken.has(base)) return base;
    for (let i = 2; i < 999; i += 1) {
      const candidate = `${base} ${i}`;
      if (!taken.has(candidate)) return candidate;
    }
    return `${base} ${Date.now().toString(36)}`;
  }

  // 大方案改名：本地备份直接改，同时把名字填进方案名输入框，
  // 点「保存方案缓存」就会以新名字写回酒馆（酒馆本身没有暴露安全的预设重命名接口）。
  async function renameBigPlan() {
    const ask = pwin.prompt || (typeof prompt === 'function' ? prompt : null);
    if (!ask) return toast('这个浏览器不让弹输入框，改名用不了～', 'error');
    const current = normalizeName(presetName());
    const next = normalizeName(ask.call(pwin, '大方案改名', current)).slice(0, 80);
    if (!next || next === current) return;
    const list = plans();
    if (list.some((plan) => plan.name === next)) {
      return toast(`已存在同名大方案「${next}」，请换一个名字`, 'error');
    }
    const index = list.findIndex((plan) => plan.name === current);
    if (index >= 0) {
      list[index].name = next;
      if (!savePlans(list)) return toast(storageFailureMessage('改名未保存'), 'error');
      renderPlanList(list);
    }
    const nameInput = pdoc.getElementById(`${ID}-plan-name`);
    if (nameInput) nameInput.value = next;
    renderItems();
    toast(`已改名为「${next}」，点「保存方案缓存」即可写回酒馆`, 'success');
  }

  async function saveCurrentPlan() {
    if (savingPlan) return;
    const nameInput = pdoc.getElementById(`${ID}-plan-name`);
    const saveButton = pdoc.querySelector(`#${PANEL_ID} [data-action="save"]`);
    const name0 = normalizeName(nameInput && nameInput.value).slice(0, 80);
    let name = name0;
    if (!name) {
      if (nameInput) nameInput.focus();
      return toast('请先填写方案名称', 'error');
    }
    if (nameInput) nameInput.value = name;
    const list = plans();
    let index = list.findIndex((plan) => plan.name === name);
    let nativeExists = nativePresetNames().includes(name);
    // 重名大方案不再默默覆盖：弹窗让用户改名，改到不重名或明确选择覆盖为止。
    if (index >= 0 || nativeExists) {
      const askName = pwin.prompt || (typeof prompt === 'function' ? prompt : null);
      if (askName) {
        const suggestion = uniqueBigPlanName(name);
        const next = normalizeName(askName.call(pwin,
          `大方案「${name}」已存在。改个名字继续，或直接确定以覆盖原方案。`, suggestion)).slice(0, 80);
        if (!next) return toast('那就先不保存啦～', 'error');
        if (next !== name) {
          name = next;
          if (nameInput) nameInput.value = name;
          index = list.findIndex((plan) => plan.name === name);
          nativeExists = nativePresetNames().includes(name);
        }
      }
      if (index >= 0) list.splice(index, 1);
    }
    savingPlan = true;
    if (nameInput) nameInput.disabled = true;
    if (saveButton) {
      saveButton.disabled = true;
      saveButton.setAttribute('aria-busy', 'true');
      saveButton.textContent = '保存中…';
    }
    try {
      await lifecycle.delay(0);
      if (!isCurrentIzumiInstance()) return;
      const data = promptData();
      const plan = capturePlan(name, data);
      let nativeError = '';
      try {
        if (plan.helperPreset && hostFunction('createOrReplacePreset')) {
          await saveHelperPreset(name, plan.helperPreset, { render: 'none', load: true });
        } else {
          await saveNativePreset(name, plan, { promptData: data });
        }
      } catch (error) {
        nativeError = error && error.message ? error.message : '酒馆预设保存失败';
      }
      list.unshift(plan);
      if (!savePlans(list)) {
        // 大方案本身就是撑爆存储的元凶，满了先自动精简再重试一次。
        const compacted = isQuotaError(storageService.lastError) ? compactPlanStorage() : null;
        if (!compacted || !compacted.touched || !savePlans(list)) {
          return toast(storageFailureMessage('方案未保存'), 'error');
        }
      }
      renderPlanList(list);
      renderItems(data);
      if (nativeError) return toast(`本地备份已保存，但酒馆预设未保存：${nativeError}`, 'error');
      toast(`已保存并切换到酒馆预设“${name}”`, 'success');
    } catch (error) {
      toast(error && error.message ? error.message : '方案保存失败', 'error');
    } finally {
      savingPlan = false;
      if (nameInput) nameInput.disabled = false;
      if (saveButton) {
        saveButton.disabled = false;
        saveButton.removeAttribute('aria-busy');
        saveButton.textContent = '保存方案缓存';
      }
    }
  }

  function deletePlan(index) {
    const list = plans();
    const plan = list[index];
    if (!plan) return;
    const ask = pwin.confirm || (typeof confirm === 'function' ? confirm : null);
    if (ask && !ask.call(pwin, `删除方案“${plan.name}”？`)) return;
    list.splice(index, 1);
    savePlans(list);
    renderPlanList();
  }

  function downloadText(text, filename) {
    try {
      const BlobCtor = pwin.Blob || Blob;
      const URLCtor = pwin.URL || URL;
      const blob = new BlobCtor([text], { type: 'application/json;charset=utf-8' });
      const url = URLCtor.createObjectURL(blob);
      const link = pdoc.createElement('a');
      link.href = url;
      link.download = filename;
      link.style.display = 'none';
      (pdoc.body || pdoc.documentElement).appendChild(link);
      link.click();
      setTimeout(() => { link.remove(); URLCtor.revokeObjectURL(url); }, 500);
      return true;
    } catch (_) {
      return false;
    }
  }

  function download(value, filename) {
    try { return downloadText(JSON.stringify(value, null, 2), filename); } catch (_) { return false; }
  }

  function transferPayloadText(value) {
    const text = JSON.stringify(value, null, 2);
    if (text.length > MAX_TRANSFER_BYTES) throw new Error('导入导出内容超过 8 MB，请拆分后重试');
    return text;
  }

  const PANEL_OVERLAY_IDS = ['editor', 'layer-preview', 'help', 'transfer', 'advice-dialog', 'sanitizer-dialog'];
  let transferDialogRevision = 0;
  let transferCopyRevision = 0;

  function panelOverlayElement(name) {
    return pdoc.getElementById(`${ID}-${name}`);
  }

  function anyPanelOverlayOpen() {
    return PANEL_OVERLAY_IDS.some((name) => {
      const overlay = panelOverlayElement(name);
      return overlay && !overlay.hidden;
    });
  }

  // 弹窗是 absolute 定位在面板内容顶部，而面板本身可滚动。
  // 打开前记住当前位置并滚到顶部，关闭最后一个弹窗后再把用户送回原处。
  function openPanelOverlay(overlay, panel) {
    if (!overlay || !panel) return false;
    if (!panel.hasAttribute('data-overlay-scroll')) {
      panel.setAttribute('data-overlay-scroll', String(panel.scrollTop || 0));
    }
    panel.scrollTop = 0;
    overlay.hidden = false;
    panel.classList.add('editing');
    const requestFrame = pwin.requestAnimationFrame || ((callback) => setTimeout(callback, 0));
    requestFrame(() => { if (!overlay.hidden) panel.scrollTop = 0; });
    return true;
  }

  function closePanelOverlay(overlay, panel, options = {}) {
    if (overlay) overlay.hidden = true;
    if (!panel || anyPanelOverlayOpen()) return;
    panel.classList.remove('editing');
    const saved = Number(panel.getAttribute('data-overlay-scroll'));
    panel.removeAttribute('data-overlay-scroll');
    if (options.restoreScroll === false || !Number.isFinite(saved)) return;
    const requestFrame = pwin.requestAnimationFrame || ((callback) => setTimeout(callback, 0));
    requestFrame(() => { panel.scrollTop = saved; });
  }

  function visiblePanelOverlay() {
    for (const name of PANEL_OVERLAY_IDS) {
      const overlay = panelOverlayElement(name);
      if (overlay && !overlay.hidden) return { name, overlay };
    }
    return null;
  }

  function closeVisiblePanelOverlay(panel, options = {}) {
    const current = visiblePanelOverlay();
    if (!current) return false;
    if (current.name === 'editor') closePromptEditor(options.restoreFocus !== false, options);
    else if (current.name === 'transfer') closeTransferDialog(options);
    else if (current.name === 'layer-preview') closeLayerPlanPreview(panel, options);
    else if (current.name === 'advice-dialog') closeAdviceSettingsDialog(panel);
    else if (current.name === 'sanitizer-dialog') closeSanitizerSettingsDialog(panel);
    else closePanelOverlay(current.overlay, panel, options);
    return true;
  }

  function closeAllPanelOverlays(panel, options = {}) {
    transferDialogRevision++;
    PANEL_OVERLAY_IDS.forEach((name) => {
      const overlay = panelOverlayElement(name);
      if (overlay) overlay.hidden = true;
    });
    editingPrompt = null;
    editorOpener = null;
    closePanelOverlay(null, panel, options);
  }

  function openDiagnosticsDialog(panel) {
    const text = getRuntimeDiagnostics().serialize();
    const help = pdoc.getElementById(`${ID}-help`);
    // Handoff keeps the existing overlay scroll/focus behavior, without two modals.
    if (help) help.hidden = true;
    const opened = openTransferDialog('export', text, 'Izumi诊断.json', { diagnostic: true });
    if (!opened) closePanelOverlay(help, panel);
    return opened;
  }

  function openTransferDialog(mode, text, filename, options = {}) {
    const overlay = pdoc.getElementById(`${ID}-transfer`);
    const textarea = pdoc.getElementById(`${ID}-transfer-text`);
    const title = pdoc.getElementById(`${ID}-transfer-title`);
    const kicker = pdoc.getElementById(`${ID}-transfer-kicker`);
    const description = pdoc.getElementById(`${ID}-transfer-description`);
    if (!overlay || !textarea) return false;
    transferDialogRevision++;
    const diagnostic = options.diagnostic === true;
    const exportMode = diagnostic || mode === 'export';
    overlay.dataset.mode = exportMode ? 'export' : 'import';
    overlay.dataset.displayMode = diagnostic ? 'diagnostic' : 'transfer';
    overlay.dataset.filename = diagnostic ? 'Izumi诊断.json' : filename || '泉此方方案.json';
    textarea.value = text || '';
    textarea.readOnly = exportMode;
    textarea.placeholder = diagnostic ? '' : '粘贴方案包、原生酒馆预设，或它们组成的 JSON 数组';
    if (title) title.textContent = diagnostic ? '版本与诊断 · 脱敏诊断' : exportMode ? '移动端导出' : '批量导入';
    if (kicker) kicker.textContent = diagnostic ? 'IZUMI / DIAGNOSTICS' : 'MOBILE / BATCH TRANSFER';
    if (description) description.textContent = diagnostic
      ? '仅含版本、接口能力布尔值与最近一次预设保存结果，不是完整操作日志，不覆盖批量文件导入全链路。能力 false 表示未确认或不可用；partial 为 false 不保证宿主没有发生修改。不含预设名、正文、聊天、URL、密钥或原始错误；不上传、不写入本地存储。可复制给维护者排查，不能作为预设导入。'
      : exportMode ? '当前文本用于导出，可复制文本或下载文件；预设包可在酒馆导入。'
        : '支持 Tavern Helper 预设包、SillyTavern 原生预设、旧泉此方方案包、多个文件和 JSON 数组；导入会直接创建或覆盖酒馆命名预设。';
    overlay.querySelectorAll('[data-transfer-show]').forEach((button) => {
      button.hidden = diagnostic ? button.dataset.action !== 'transfer-copy' : button.dataset.transferShow !== overlay.dataset.mode;
      if (button.dataset.action === 'transfer-copy') button.textContent = diagnostic ? '复制脱敏诊断' : '复制文本';
    });
    const panel = pdoc.getElementById(PANEL_ID);
    if (panel) openPanelOverlay(overlay, panel);
    setTimeout(() => {
      try {
        textarea.focus({ preventScroll: true });
        if (exportMode) textarea.select();
      } catch (_) {
        try { textarea.focus(); if (exportMode) textarea.select(); } catch (_) {}
      }
    }, 0);
    return true;
  }

  function closeTransferDialog(options = {}) {
    transferDialogRevision++;
    const overlay = pdoc.getElementById(`${ID}-transfer`);
    const panel = pdoc.getElementById(PANEL_ID);
    closePanelOverlay(overlay, panel, options);
  }

  async function copyTransferText() {
    const textarea = pdoc.getElementById(`${ID}-transfer-text`);
    if (!textarea || !textarea.value) return toast('这里还没有内容可以复制～', 'error');
    const overlay = pdoc.getElementById(`${ID}-transfer`);
    const text = textarea.value;
    const mode = overlay && overlay.dataset.mode;
    const displayMode = overlay && overlay.dataset.displayMode;
    const hidden = overlay && overlay.hidden;
    const dialogRevision = transferDialogRevision;
    const copyRevision = ++transferCopyRevision;
    const ownsCopyDialog = () => isCurrentIzumiInstance()
      && dialogRevision === transferDialogRevision && copyRevision === transferCopyRevision
      && pdoc.getElementById(`${ID}-transfer-text`) === textarea
      && pdoc.getElementById(`${ID}-transfer`) === overlay
      && (!overlay || (overlay.hidden === hidden && overlay.dataset.mode === mode && overlay.dataset.displayMode === displayMode));
    const isCurrentCopy = () => ownsCopyDialog() && textarea.value === text;
    if (!isCurrentCopy()) return;
    let copied = false;
    try {
      const clipboard = pwin.navigator && pwin.navigator.clipboard;
      if (clipboard && typeof clipboard.writeText === 'function') {
        await clipboard.writeText(text);
        copied = true;
      }
    } catch (_) {}
    // Clipboard permission may settle after another dialog replaces this textarea.
    // Never fall back to selecting its new contents, nor label an old copy as new.
    if (!isCurrentCopy()) return;
    if (!copied) {
      const readOnly = textarea.readOnly;
      try {
        textarea.readOnly = false;
        textarea.focus();
        if (!isCurrentCopy()) return;
        textarea.select();
        if (!isCurrentCopy()) return;
        copied = !!(pdoc.execCommand && pdoc.execCommand('copy'));
      } catch (_) {
      } finally {
        if (ownsCopyDialog()) textarea.readOnly = readOnly;
      }
    }
    if (!isCurrentCopy()) return;
    const successMessage = displayMode === 'diagnostic' ? '脱敏诊断已复制，可发送给维护者排查（不是预设文件）' : 'JSON 已复制，可在手机端酒馆粘贴导入';
    toast(copied ? successMessage : '自动复制失败，请长按文本手动复制', copied ? 'success' : 'error');
  }

  async function pasteTransferText() {
    const textarea = pdoc.getElementById(`${ID}-transfer-text`);
    const overlay = pdoc.getElementById(`${ID}-transfer`);
    if (!textarea || !overlay || overlay.hidden || textarea.readOnly
      || overlay.dataset.mode !== 'import' || overlay.dataset.displayMode !== 'transfer') return;
    const originalText = textarea.value;
    const dialogRevision = transferDialogRevision;
    const isCurrentPaste = (text = originalText) => isCurrentIzumiInstance()
      && dialogRevision === transferDialogRevision
      && pdoc.getElementById(`${ID}-transfer-text`) === textarea && textarea.value === text && !textarea.readOnly
      && pdoc.getElementById(`${ID}-transfer`) === overlay && !overlay.hidden
      && overlay.dataset.mode === 'import' && overlay.dataset.displayMode === 'transfer';
    if (!isCurrentPaste()) return;
    try {
      const clipboard = pwin.navigator && pwin.navigator.clipboard;
      if (!clipboard || typeof clipboard.readText !== 'function') throw new Error('clipboard unavailable');
      const text = await clipboard.readText();
      if (!isCurrentPaste()) return;
      textarea.value = text;
      textarea.focus();
      if (isCurrentPaste(text)) toast('已从剪贴板读取 JSON', 'success');
    } catch (_) {
      if (!isCurrentPaste()) return;
      textarea.focus();
      if (isCurrentPaste()) toast('读不到剪贴板，长按上面的输入框手动粘贴就行～', 'error');
    }
  }

  function planFromNativePreset(value, fallbackName) {
    const wrapper = value && value.preset && typeof value.preset === 'object' ? value : null;
    const raw = wrapper ? wrapper.preset : value;
    const nativePreset = sanitizeNativePreset(raw);
    if (!nativePreset || !Array.isArray(nativePreset.prompts)) return null;
    const name = normalizeName((wrapper && wrapper.name) || (raw && raw.name) || fallbackName).slice(0, 80)
      || `泉此方导入 ${new Date().toISOString().slice(0, 10)}`;
    const helper = helperPresetFromTransfer(value, name);
    const items = presetPromptItems(nativePreset);
    return normalizePlan({
      name,
      savedAt: new Date().toISOString(),
      presetName: name,
      promptStates: items.map((item) => ({ id: item.id, name: item.name, index: item.index, enabled: item.enabled, layer: item.pinnedLayer || '' })),
      promptEdits: items.map((item) => ({
        id: item.id,
        name: item.name,
        index: item.index,
        content: item.content,
        contentKey: item.contentKey,
        role: item.role,
        triggers: item.triggers,
        injectionPosition: item.injectionPosition,
        injectionDepth: item.injectionDepth,
        injectionOrder: item.injectionOrder,
        marker: item.marker,
        layer: item.pinnedLayer || '',
      })),
      promptOrder: Array.isArray(nativePreset.prompt_order) ? clone(nativePreset.prompt_order) : null,
      presetFields: normalizeSafePresetFields(nativePreset),
      nativePreset,
      helperPreset: helper && helper.preset ? helper.preset : null,
      apiConfig: null,
    });
  }

  function collectImportedPlans(value, output, fallbackName) {
    if (Array.isArray(value)) {
      value.forEach((entry, index) => collectImportedPlans(entry, output, `${fallbackName || '批量导入'} ${index + 1}`));
      return;
    }
    if (!value || typeof value !== 'object') return;
    if (Array.isArray(value.plans)) {
      value.plans.forEach((entry) => {
        const plan = normalizePlan(entry);
        if (plan) output.push(plan);
      });
      return;
    }
    if (Array.isArray(value.presets)) {
      value.presets.forEach((entry, index) => {
        const plan = planFromNativePreset(entry, `${fallbackName || '预设'} ${index + 1}`);
        if (plan) output.push(plan);
      });
      return;
    }
    if (value.data && typeof value.data === 'object' && Array.isArray(value.data.prompts)) {
      const plan = planFromNativePreset({
        name: value.name || fallbackName,
        preset: {
          prompts: value.data.prompts,
          prompt_order: Array.isArray(value.data.prompt_order) ? value.data.prompt_order : [],
        },
      }, fallbackName);
      if (plan) output.push(plan);
      return;
    }
    if (value.preset && typeof value.preset === 'object') {
      const plan = planFromNativePreset(value, fallbackName);
      if (plan) output.push(plan);
      return;
    }
    if (Array.isArray(value.prompts)) {
      const plan = planFromNativePreset(value, fallbackName);
      if (plan) output.push(plan);
      return;
    }
    const plan = normalizePlan(value);
    if (plan) output.push(plan);
  }

  function parseTransferText(text) {
    let source = String(text == null ? '' : text).replace(/^\uFEFF/, '').trim();
    if (!source) throw new Error('导入内容为空');
    if (source.length > MAX_TRANSFER_BYTES) throw new Error('导入内容超过 8 MB，请拆分后重试');
    const fenced = source.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
    if (fenced) source = fenced[1].trim();
    try { return JSON.parse(source); } catch (firstError) {
      const documents = source.split(/^\s*---+\s*$/m).map((part) => part.trim()).filter(Boolean);
      if (documents.length > 1) {
        try { return documents.map((document) => JSON.parse(document)); } catch (_) {}
      }
      throw new Error('不是有效 JSON；可粘贴方案包、原生预设或它们组成的数组');
    }
  }

  function mergeImportedPlans(incoming) {
    const unique = new Map();
    incoming.map(normalizePlan).filter(Boolean).forEach((plan) => unique.set(plan.name, plan));
    const normalized = Array.from(unique.values());
    if (!normalized.length) throw new Error('没有识别到兼容的方案或酒馆预设');
    const list = plans();
    normalized.forEach((plan) => {
      const index = list.findIndex((existing) => existing.name === plan.name);
      if (index >= 0) list[index] = plan;
      else list.push(plan);
    });
    if (!savePlans(list)) throw new Error(storageFailureMessage('导入未保存'));
    renderPlanList(list);
    return normalized;
  }

  async function importPlans(text, options = {}) {
    try {
      const parsed = parseTransferText(text);
      // 小方案包最先识别：它没有 prompts，容易被后面的预设分支误判成空包。
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)
        && parsed.schema === LAYER_PLAN_SCHEMA && Array.isArray(parsed.plans)) {
        const quickBefore = quickSlots().length;
        const added = mergeLayerPlans(parsed.plans, parsed.active, parsed.quickSlots);
        const quickAdded = Math.max(0, quickSlots().length - quickBefore);
        refreshPanel();
        if (!options.silent) {
          const quickText = quickAdded ? `，并加入 ${quickAdded} 个快捷方案` : '';
          toast(added
            ? `已导入 ${added} 个小方案${quickText}（同名自动加序号，同 id 覆盖）`
            : `小方案已全部存在，已按 id 覆盖更新${quickText}`, 'success');
        }
        return [];
      }
      const probe = [];
      collectImportedPresets(parsed, probe, options.fallbackName || '导入预设');
      if (probe.length) {
        const imported = await importTavernPresets(parsed, options);
        if (!options.silent) toast(`已批量写入酒馆 ${imported.length} 个预设${options.loadFirst ? '，并载入第一个' : ''}`, 'success');
        refreshPanel();
        return imported;
      }
      const legacy = [];
      collectImportedPlans(parsed, legacy, options.fallbackName || '导入预设');
      const backups = mergeImportedPlans(legacy);
      if (options.loadFirst && backups[0]) await applyPlan(backups[0]);
      if (!options.silent) toast(`已恢复 ${backups.length} 个旧版本地备份`, 'success');
      return backups;
    } catch (error) {
      if (!options.silent) toast(error && error.message ? error.message : '导入失败', 'error');
      throw error;
    }
  }

  function readFileText(file) {
    if (file && typeof file.text === 'function') return file.text();
    return new Promise((resolve, reject) => {
      const Reader = pwin.FileReader || (typeof FileReader === 'function' ? FileReader : null);
      if (!Reader) return reject(new Error('当前手机浏览器不支持读取文件'));
      const reader = new Reader();
      reader.onload = () => resolve(String(reader.result || ''));
      reader.onerror = () => reject(reader.error || new Error('文件读取失败'));
      reader.readAsText(file, 'utf-8');
    });
  }

  async function importPlanFiles(fileList, options = {}) {
    const files = Array.from(fileList || []);
    if (!files.length) return [];
    const incoming = [];
    const legacy = [];
    const failures = [];
    let layerPlanFiles = 0;
    let layerPlanPackages = 0;
    let quickPlanFiles = 0;
    for (const file of files) {
      try {
        if (file.size > MAX_TRANSFER_BYTES) throw new Error('超过 8 MB');
        const parsed = parseTransferText(await readFileText(file));
        const fallbackName = normalizeName(file.name).replace(/\.json$/i, '');
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)
          && parsed.schema === LAYER_PLAN_SCHEMA && Array.isArray(parsed.plans)) {
          const quickBefore = quickSlots().length;
          layerPlanFiles += mergeLayerPlans(parsed.plans, parsed.active, parsed.quickSlots);
          layerPlanPackages += 1;
          quickPlanFiles += Math.max(0, quickSlots().length - quickBefore);
          continue;
        }
        const probe = [];
        collectImportedPresets(parsed, probe, fallbackName);
        if (probe.length) incoming.push(...probe);
        else collectImportedPlans(parsed, legacy, fallbackName);
      } catch (error) {
        failures.push(`${file.name || '未命名文件'}：${error && error.message ? error.message : '读取失败'}`);
      }
    }
    if (!incoming.length && !legacy.length) {
      if (layerPlanPackages) {
        refreshPanel();
        const planText = layerPlanFiles ? `新增 ${layerPlanFiles} 个小方案` : '小方案已按 id 更新';
        toast(`已处理 ${layerPlanPackages} 个小方案包：${planText}${quickPlanFiles ? `，并加入 ${quickPlanFiles} 个快捷方案` : ''}${failures.length ? `；${failures.length} 个文件失败：${failures[0]}` : ''}`, failures.length ? 'error' : 'success');
        return [];
      }
      const message = failures[0] || '没有识别到兼容的导入文件';
      toast(message, 'error');
      return [];
    }
    try {
      if (incoming.length) {
        const imported = await importTavernPresets(incoming, options);
        refreshPanel();
        toast(`已从 ${files.length} 个文件写入酒馆 ${imported.length} 个预设${failures.length ? `，${failures.length} 个文件失败` : ''}`, failures.length ? 'error' : 'success');
        return imported;
      }
      const backups = mergeImportedPlans(legacy);
      if (options.loadFirst && backups[0]) await applyPlan(backups[0]);
      toast(`已恢复 ${backups.length} 个旧版本地备份${failures.length ? `，${failures.length} 个文件失败` : ''}`, failures.length ? 'error' : 'success');
      return backups;
    } catch (error) {
      toast(error && error.message ? error.message : '批量导入失败', 'error');
      return [];
    }
  }

  function exportPlans() {
    const api = tavernPresetFunctions();
    if (!api.names || !api.get) return toast('读不到酒馆的预设列表，可能是「酒馆助手」没开～', 'error');
    const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const filename = `酒馆预设批量-${stamp}.json`;
    try {
      const names = Array.from(new Set((api.names() || []).map(normalizeName).filter((name) => name && name !== 'in_use')));
      const presets = names.map((name) => ({ name, preset: sanitizePresetForWrite(api.get(name)) })).filter((entry) => entry.preset);
      if (!presets.length) return toast('酒馆中没有可导出的命名预设', 'error');
      const payload = { schema: NATIVE_TRANSFER_SCHEMA, version: 1, exportedAt: new Date().toISOString(), source: 'SillyTavern TavernHelper', presets };
      const text = transferPayloadText(payload);
      openTransferDialog('export', text, filename);
      const downloaded = downloadText(text, filename);
      toast(downloaded ? `已导出 ${presets.length} 个酒馆预设` : '文件下载不可用，请复制文本导出', downloaded ? 'success' : 'error');
    } catch (error) {
      toast(error && error.message ? error.message : '导出没成功～', 'error');
    }
  }

  function exportCurrentPreset() {
    const api = tavernPresetFunctions();
    const name = selectedNativePresetName();
    if (!api.get || !name || name === 'in_use') return toast('现在这个预设还没名字，先在酒馆里另存一下就能导出啦～', 'error');
    const snapshot = sanitizePresetForWrite(api.get(name));
    if (!snapshot || !Array.isArray(snapshot.prompts)) return toast('导不出来，读不到酒馆的预设接口～', 'error');
    const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const filename = `${name.replace(/[\\/:*?"<>|]/g, '_')}-${stamp}.json`;
    try {
      // Export the native preset shape so SillyTavern's own mobile preset
      // picker can import it directly; the importer also accepts our older
      // wrapped transfer shape for backwards compatibility.
      const payload = { schema: NATIVE_TRANSFER_SCHEMA, version: 1, exportedAt: new Date().toISOString(), source: 'SillyTavern TavernHelper', presets: [{ name, preset: snapshot }] };
      const text = transferPayloadText(payload);
      openTransferDialog('export', text, filename);
      const downloaded = downloadText(text, filename);
      toast(downloaded ? '已导出当前酒馆预设；手机端也可直接复制文本' : '文件下载不可用，请复制文本导出', downloaded ? 'success' : 'error');
    } catch (error) {
      toast(error && error.message ? error.message : '当前预设导出失败', 'error');
    }
  }

