  function toast(message, type) {
    const element = pdoc.getElementById(TOAST_ID);
    if (!element) return;
    element.textContent = message;
    element.className = type || 'info';
    element.dataset.mood = type === 'error' ? 'kagami' : 'izumi';
    element.style.display = 'block';
    clearTimeout(element._timer);
    element._timer = setTimeout(() => { element.style.display = 'none'; }, 2600);
