  function panelMarkup() {
    return `
      <header class="panel-header" data-drag-handle>
        <div class="header-top">
          <div class="header-title"><span class="kicker">IZUMI / FLOATING WINDOW</span><h2>泉此方设置</h2></div>
          <div class="header-actions"><button class="icon-btn" data-action="night" title="夜间模式" aria-label="夜间模式" aria-pressed="false">☾</button><button class="icon-btn danger" data-action="shutdown" title="彻底关闭本次悬浮窗" aria-label="彻底关闭本次悬浮窗">⏻</button><button class="icon-btn" data-action="close" title="收起" aria-label="收起">×</button></div>
        </div>
        <div class="header-bottom">
          <button class="help-btn" data-action="help" title="打开使用教程" aria-label="打开使用教程"><b aria-hidden="true">i</b><span>使用教程</span></button>
          <div class="header-status-tools"><div class="sanitizer-control-group">${sanitizerControlMarkup('panel')}${sanitizerSettingsButtonMarkup('panel')}</div><div class="advice-control-group">${adviceControlMarkup('panel')}${adviceSettingsButtonMarkup('panel')}</div><div class="header-preset"><span id="${ID}-preset">当前预设：读取中</span><button class="icon-btn small" data-action="refresh" title="刷新" aria-label="刷新">↻</button></div></div>
        </div>
      </header>
      <details class="api-box" id="${ID}-api-form">
        <summary class="api-summary"><span>附加参数</span><small id="${ID}-api-status">读取中</small></summary>
        <div class="api-content">
        <div class="api-head">
          <div><strong>★ 泉此方方案配置</strong><small class="api-subtitle">当前聊天补全连接</small></div>
        </div>
        <div class="api-grid api-main-grid">
          <div class="api-field">
            <label for="${ID}-api-main-api">API</label>
            <input id="${ID}-api-main-api" readonly aria-readonly="true">
          </div>
          <div class="api-field">
            <label for="${ID}-api-source">聊天补全来源</label>
            <input id="${ID}-api-source" readonly aria-readonly="true">
          </div>
          <div class="api-field wide">
            <label for="${ID}-api-url">自定义端点（基础 URL）</label>
            <input id="${ID}-api-url" autocomplete="url" placeholder="https://api.example.com/v1">
          </div>
          <div class="api-field wide">
            <label for="${ID}-api-model">输入模型名</label>
            <div class="model-picker">
              <input id="${ID}-api-model" list="${ID}-api-models" autocomplete="off" placeholder="模型 ID">
              <select id="${ID}-api-model-list" aria-label="可用模型"><option value="">尚未拉取模型</option></select>
            </div>
            <datalist id="${ID}-api-models"></datalist>
          </div>
          <div class="api-field wide">
            <label for="${ID}-api-key">API 密钥 <small>仅在本机方案中保存</small></label>
            <input id="${ID}-api-key" type="password" autocomplete="new-password" placeholder="留空就用酒馆当前的密钥">
            <span class="field-help">实际请求走的还是酒馆自己的密钥配置。这里填的不会显示在方案列表或状态提示里。</span>
          </div>
          <div class="api-field wide">
            <label for="${ID}-api-post-processing">提示词后处理</label>
            <select id="${ID}-api-post-processing">
              <option value="">未选择</option>
              <optgroup label="使用工具">
                <option value="merge_tools">合并连续角色（使用工具）</option>
                <option value="semi_tools">半严格交替（使用工具）</option>
                <option value="strict_tools">严格交替（使用工具）</option>
              </optgroup>
              <optgroup label="不使用工具">
                <option value="merge">合并连续角色</option>
                <option value="semi">半严格交替</option>
                <option value="strict">严格交替</option>
                <option value="single">单条用户消息</option>
              </optgroup>
            </select>
          </div>
        </div>
        <div class="api-section-title">生成偏好 <small>写回当前酒馆设置</small></div>
        <div class="api-grid api-generation-grid">
          <div class="api-field"><label for="${ID}-api-max-tokens">回复长度</label><input id="${ID}-api-max-tokens" inputmode="numeric" placeholder="4096"></div>
          <div class="api-field"><label for="${ID}-api-temperature">随机程度</label><input id="${ID}-api-temperature" inputmode="decimal" placeholder="0.7"></div>
          <div class="api-field"><label for="${ID}-api-top-p">多样性</label><input id="${ID}-api-top-p" inputmode="decimal" placeholder="0.9"></div>
          <label class="api-check"><input id="${ID}-api-stream" type="checkbox"> 流式输出</label>
        </div>
        <details class="advanced">
          <summary>附加参数</summary>
          <div class="advanced-content">
            <div class="api-grid">
              <div class="api-field wide">
                <label for="${ID}-api-include-body">包含主体参数 <small>YAML 对象</small></label>
                <textarea id="${ID}-api-include-body" spellcheck="false" placeholder="top_k: 20&#10;repetition_penalty: 1.1"></textarea>
              </div>
              <div class="api-field wide">
                <label for="${ID}-api-exclude-body">排除主体参数 <small>YAML 数组</small></label>
                <textarea id="${ID}-api-exclude-body" spellcheck="false" placeholder="- frequency_penalty&#10;- presence_penalty"></textarea>
              </div>
              <div class="api-field wide">
                <label for="${ID}-api-include-headers">包含请求标头 <small>YAML 对象</small></label>
                <textarea id="${ID}-api-include-headers" spellcheck="false" placeholder="CustomHeader: 自定义值&#10;AnotherHeader: 自定义值"></textarea>
              </div>
            </div>
          </div>
        </details>
        <div class="api-actions">
          <button class="command primary" data-action="api-apply">★ 应用当前设置</button>
          <button class="command" data-action="api-read">↻ 读取当前</button>
          <button class="command" data-action="api-models">⌕ 拉取模型</button>
        </div>
        <div class="api-key-options">
          <label class="api-check"><input id="${ID}-api-save-key" type="checkbox"> 把密钥一起存在本机（只存在这个浏览器里，导出文件不会包含）</label>
        </div>
        <small class="api-warning">勾选后，密钥会以明文存在这个浏览器的本地存储里，只有本机能读到；不写进酒馆的密钥库，也不出现在提示和日志里。脚本的所有导出（酒馆预设、小方案包、存储报告）都不会带上它。如果这台电脑不是你一个人用，就别勾～</small>
        </div>
      </details>
      <section class="overview-card"><div class="plan-banner" id="${ID}-plan-banner"></div></section>
      <section class="workspace-card">
      <nav class="tabs">${LAYERS.map((layer) => `<button class="tab" data-action="tab" data-layer="${layer.id}" aria-selected="false"><span>${layer.label}</span><b data-count="${layer.id}">0</b></button>`).join("")}</nav>
      <nav class="function-tabs" id="${ID}-function-tabs" aria-label="层内子区" hidden></nav>
      <div class="layer-plans" id="${ID}-layer-plans" hidden></div>
