  function createPanel() {
    const panel = pdoc.createElement('section');
    panel.id = PANEL_ID;
    panel.innerHTML = panelMarkup();
    panel.classList.toggle('night', nightMode);
    (pdoc.body || pdoc.documentElement).appendChild(panel);
    return panel;
  }

  let lastPlanListRenderSignature = '';

  function renderPlanList(list = plans(), options = {}) {
    const container = pdoc.getElementById(`${ID}-plans`);
    if (!container) return;
    // 存储全量统计可能要扫十几万个键，普通刷新绝不能做。
    // 未测量时只给入口；点「存储详情」或发生配额错误后才会拿到准确数字。
    const used = storageService.measuredChars;
    const ratio = used == null ? null : Math.min(999, Math.round((used / (5 * 1048576)) * 100));
    const level = ratio == null ? '' : (ratio >= 85 ? ' danger' : (ratio >= 60 ? ' warn' : ''));
    const usageText = used == null
      ? '本地存储尚未测量 · 点「存储详情」查看'
      : `本地存储 ${formatBytes(used)} · 约占上限 ${ratio}%`;
    const currentPreset = normalizeName(presetName());
    const renderSignature = JSON.stringify({
      used,
      currentPreset,
      plans: list.map((plan) => [plan.name, plan.savedAt, plan.promptStates.length,
        plan.promptStates.filter((state) => state.enabled).length, !!(plan.apiConfig && plan.apiConfig.apiKey)]),
    });
    if (!options.force && renderSignature === lastPlanListRenderSignature) return;
    lastPlanListRenderSignature = renderSignature;
    const usage = `<div class="plan-usage${level}">`
      + `<span>${usageText}</span>`
      + `<span class="plan-usage-acts">`
      + `<button class="mini" data-action="storage-report" title="看清每个键族占了多少">存储详情</button>`
      + `<button class="mini" data-action="clean-junk" title="按前缀批量删除堆积的垃圾键">清理垃圾键</button>`
      + `<button class="mini" data-action="compact-storage" title="丢掉大方案里冗余的预设副本，不影响载入">精简</button>`
      + `<button class="mini" data-action="purge-backups" title="删除本脚本的全部本地大方案备份（酒馆里的预设不受影响）">清空备份</button>`
      + `</span></div>`;
    if (!list.length) {
      container.innerHTML = `${usage}<div class="empty">暂无自定义方案</div>`;
      return;
    }
    container.innerHTML = usage + list.map((plan, index) => {
      const on = plan.promptStates.filter((state) => state.enabled).length;
      const keyLabel = plan.apiConfig && plan.apiConfig.apiKey ? ' · 含本地密钥' : '';
      const active = currentPreset === plan.name;
      const stateLabel = active ? '酒馆当前' : '本地备份';
      return `<div class="plan-row"><div class="plan-copy"><strong>${esc(plan.name)}</strong><small>${stateLabel} · ${on}/${plan.promptStates.length} 开启${keyLabel}</small></div><div class="plan-actions"><button class="mini" data-action="load" data-index="${index}">${active ? '重新载入' : '载入并切换'}</button><button class="icon-btn small danger" data-action="delete" data-index="${index}" title="仅删除本地备份" aria-label="仅删除本地备份">×</button></div></div>`;
    }).join('');
  }

  function renderFunctionHub(container, items, layerId) {
    const targetLayer = layerId || activeLayer;
    const sections = layerSections(targetLayer);
    container.innerHTML = `<div class="function-hub">${sections.map((sectionId) => {
      const count = items.filter((item) => itemInScope(item, targetLayer, sectionId)).length;
      return `<button class="function-jump" data-action="function-section" data-section="${sectionId}"><span>${esc(sectionLabel(targetLayer, sectionId))}</span><b>${count}</b></button>`;
    }).join('')}</div>`;
  }

  // 条目编辑器的「目标子区」下拉：按所属层动态填充，层没有子区就整个隐藏。
  function fillEditorSectionOptions(layerId, selected) {
    const field = pdoc.getElementById(`${ID}-editor-section-field`);
    const select = pdoc.getElementById(`${ID}-editor-section`);
    if (!field || !select) return;
    const sections = layerSections(layerId).filter((section) => section !== 'plain');
    field.hidden = !sections.length;
    select.innerHTML = [`<option value="">${esc(layerLabel(layerId))}末尾</option>`]
      .concat(sections.map((section) => `<option value="${section}">${esc(sectionLabel(layerId, section))}</option>`))
      .join('');
    select.value = sections.includes(selected) ? selected : '';
  }

  // 层内子区导航：按当前层动态生成，不再写死功能层那四个。
  function renderSectionTabs(panel, layerId) {
    const nav = panel.querySelector(`#${ID}-function-tabs`);
    if (!nav) return;
    const sections = layerSections(layerId);
    if (!sections.length) {
      nav.hidden = true;
      nav.innerHTML = '';
      return;
    }
    nav.hidden = false;
    const buttons = [`<button class="function-tab" data-action="function-section" data-section="overview" aria-selected="${activeFunctionSection === 'overview' ? 'true' : 'false'}">子区</button>`]
      .concat(sections.map((sectionId) => `<button class="function-tab" data-action="function-section" data-section="${sectionId}" aria-selected="${activeFunctionSection === sectionId ? 'true' : 'false'}">${esc(sectionLabel(layerId, sectionId))}</button>`));
    nav.innerHTML = buttons.join('');
  }

  // 小方案栏：当前层的所有小方案，点一下即应用；改脏的会带 * 标记。
  function renderLayerPlanBar(panel, data, layerId, signatureCache) {
    const bar = panel.querySelector(`#${ID}-layer-plans`);
    if (!bar) return;
    const list = layerPlans(layerId);
    const store = layerPlanStore();
    const activeId = store.active[layerId];
    const scopeSection = normalizeSectionForLayer(layerId, activeFunctionSection);
    const scopeText = scopeSection ? `${layerLabel(layerId)}·${sectionLabel(layerId, scopeSection)}` : layerLabel(layerId);
    const scopeSignatures = signatureCache || new Map();
    const chips = list.map((plan) => {
      const on = plan.entries.filter((entry) => entry.enabled).length;
      const isActive = plan.id === activeId;
      const dirty = isActive && isLayerPlanDirty(plan, data, scopeSignatures);
      const inQuick = quickSlots().includes(plan.id);
      const scope = plan.section ? sectionLabel(plan.layer, plan.section) : '整层';
      const title = `${plan.name}｜作用域：${scope}｜${on}/${plan.entries.length} 开启｜${plan.strict ? '严格' : '宽松'}`;
      // 生效状态除了配色，还用「✓」符号标出来，色弱用户也能分辨。
      return `<span class="layer-chip${isActive ? ' on' : ''}${dirty ? ' dirty' : ''}">`
        + `<button class="layer-chip-main" data-action="layer-plan-apply" data-plan="${esc(plan.id)}" aria-pressed="${isActive ? 'true' : 'false'}" title="${esc(title)}">`
        + `<i class="chip-mark" aria-hidden="true">${isActive ? '✓' : '○'}</i>`
        + `<span class="chip-name">${inQuick ? '★ ' : ''}${esc(plan.name)}${dirty ? ' *' : ''}</span>`
        + `<b>${on}</b></button>`
        + `<button class="layer-chip-more" data-action="layer-plan-menu" data-plan="${esc(plan.id)}" title="改名 / 严格模式 / 快捷方案 / 删除" aria-label="更多">⋯</button>`
        + `</span>`;
    }).join('');
    bar.hidden = false;
    // 标签和保存按钮单独一行，小方案自己一行并自动换行——
    // 原来三者挤在一行靠横向滚动，超过三个就看不见也点不到。
    const snapshots = currentSessionSnapshots(data);
    const canRestore = !!(snapshots && snapshots.baseline);
    const canUndo = !!(snapshots && snapshots.undo);
    const canCompare = list.length >= 2;
    const guideSeen = (() => {
      const local = storage();
      try { return !!local && local.getItem(LAYER_PLAN_GUIDE_KEY) === 'seen'; } catch (_) { return false; }
    })();
    const guide = list.length && !guideSeen
      ? '<div class="layer-plan-guide"><span>小提示：长按小方案，可以先看看它会开哪些条目～</span><button data-action="layer-plan-guide-close" aria-label="知道了">知道啦</button></div>'
      : '';
    bar.innerHTML = `<div class="layer-plan-head">`
      + `<span class="layer-plan-label" title="保存/应用只影响这个作用域">作用域：${esc(scopeText)}</span>`
      + `<span class="layer-plan-head-actions">`
      + `<button class="mini" data-action="session-restore" ${canRestore ? '' : 'disabled'} title="回到这次打开酒馆时的条目开关状态">↶ 还原</button>`
      + `<button class="mini" data-action="session-undo" ${canUndo ? '' : 'disabled'} title="回到刚才点击还原之前的状态">↷ 回退</button>`
      + `<button class="mini" data-action="layer-plan-compare" ${canCompare ? '' : 'disabled'} title="对比同一层的两个小方案">⇄ 对比</button>`
      + `<button class="mini" data-action="layer-plan-save" title="把当前作用域的开关状态存成小方案">＋ 存小方案</button>`
      + `</span></div>`
      + guide
      + `<div class="layer-chips">${chips || '<span class="layer-chip-empty">这一层还没有小方案</span>'}</div>`;
  }

  function closeLayerPlanPreview(panel, options = {}) {
    const overlay = pdoc.getElementById(`${ID}-layer-preview`);
    closePanelOverlay(overlay, panel, options);
  }

  function openLayerPlanPreview(planId, panel) {
    const plan = layerPlans().find((candidate) => candidate.id === planId);
    const overlay = pdoc.getElementById(`${ID}-layer-preview`);
    const title = pdoc.getElementById(`${ID}-layer-preview-title`);
    const body = pdoc.getElementById(`${ID}-layer-preview-body`);
    if (!plan || !overlay || !body) return toast('这个小方案找不到了，可能已经被删掉～', 'error');
    const enabled = plan.entries.filter((entry) => entry.enabled).map((entry) => entry.name || entry.id);
    const disabled = plan.entries.filter((entry) => !entry.enabled).map((entry) => entry.name || entry.id);
    const scope = plan.section ? `${layerLabel(plan.layer)} · ${sectionLabel(plan.layer, plan.section)}` : `${layerLabel(plan.layer)} · 整层`;
    const listMarkup = (items, emptyText) => items.length
      ? `<ul>${items.map((name) => `<li>${esc(name)}</li>`).join('')}</ul>`
      : `<p class="layer-preview-empty">${esc(emptyText)}</p>`;
    if (title) title.textContent = plan.name;
    body.innerHTML = `<div class="layer-preview-meta"><span>${esc(scope)}</span><b>${plan.strict ? '严格模式' : '宽松模式'}</b></div>`
      + `<section><h4><span class="preview-on">✓</span> 会开启 <b>${enabled.length}</b> 条</h4>${listMarkup(enabled, '没有要开启的条目')}</section>`
      + `<section><h4><span class="preview-off">—</span> 会停用 <b>${disabled.length}</b> 条</h4>${listMarkup(disabled, '没有明确记录为停用的条目')}</section>`
      + (plan.strict ? '<p class="help-warn">严格模式下，这个作用域里没有记录到的新条目也会被停用。</p>' : '<p class="help-note">宽松模式只改上面列出的条目，其余保持原样。</p>');
    if (panel) openPanelOverlay(overlay, panel);
    try {
      const local = storage();
      if (local) local.setItem(LAYER_PLAN_GUIDE_KEY, 'seen');
    } catch (_) {}
  }

  function layerPlanEntryKey(entry) {
    // 对比面向人看，优先按名称认同一条；跨预设时 id 可能不同，但名字仍然相同。
    return `${normalizeName(entry && (entry.name || entry.id))}#${Number(entry && entry.sameNameIndex) || 0}`;
  }

  function openLayerPlanComparison(layerId, panel) {
    const list = layerPlans(layerId);
    if (list.length < 2) return toast('同一层至少要有两个小方案才能对比～', 'error');
    const overlay = pdoc.getElementById(`${ID}-layer-preview`);
    const title = pdoc.getElementById(`${ID}-layer-preview-title`);
    const body = pdoc.getElementById(`${ID}-layer-preview-body`);
    if (!overlay || !body) return;
    const option = (plan, index) => {
      const scope = plan.section ? sectionLabel(plan.layer, plan.section) : '整层';
      return `<option value="${esc(plan.id)}">${esc(plan.name)} · ${esc(scope)} · ${plan.strict ? '严格' : '宽松'}</option>`;
    };
    if (title) title.textContent = `${layerLabel(layerId)}小方案对比`;
    body.innerHTML = `<div class="compare-picker">`
      + `<label><b>A 方案</b><select id="${ID}-compare-a">${list.map(option).join('')}</select></label>`
      + `<span aria-hidden="true">⇄</span>`
      + `<label><b>B 方案</b><select id="${ID}-compare-b">${list.map(option).join('')}</select></label>`
      + `</div>`
      + `<p class="help-note">选两个同层小方案，看看它们分别开启了什么。作用域不同也可以比，结果会如实算进去。</p>`
      + `<div class="compare-picker-action"><button class="command primary" data-action="layer-compare-run" data-layer="${esc(layerId)}">开始对比</button></div>`;
    const selectB = pdoc.getElementById(`${ID}-compare-b`);
    if (selectB && list[1]) selectB.value = list[1].id;
    if (panel) openPanelOverlay(overlay, panel);
  }

  function runLayerPlanComparison(layerId) {
    const list = layerPlans(layerId);
    const selectA = pdoc.getElementById(`${ID}-compare-a`);
    const selectB = pdoc.getElementById(`${ID}-compare-b`);
    const a = list.find((plan) => plan.id === (selectA && selectA.value));
    const b = list.find((plan) => plan.id === (selectB && selectB.value));
    if (!a || !b || a.id === b.id) return toast('选两个不同的小方案就能对比啦～', 'error');
    const enabledA = new Map(a.entries.filter((entry) => entry.enabled).map((entry) => [layerPlanEntryKey(entry), entry.name || entry.id]));
    const enabledB = new Map(b.entries.filter((entry) => entry.enabled).map((entry) => [layerPlanEntryKey(entry), entry.name || entry.id]));
    const onlyA = Array.from(enabledA.entries()).filter(([key]) => !enabledB.has(key)).map(([, name]) => name);
    const onlyB = Array.from(enabledB.entries()).filter(([key]) => !enabledA.has(key)).map(([, name]) => name);
    const common = Array.from(enabledA.entries()).filter(([key]) => enabledB.has(key)).map(([, name]) => name);
    const title = pdoc.getElementById(`${ID}-layer-preview-title`);
    const body = pdoc.getElementById(`${ID}-layer-preview-body`);
    if (!body) return;
    const scopeOf = (plan) => plan.section ? `${layerLabel(plan.layer)} · ${sectionLabel(plan.layer, plan.section)}` : `${layerLabel(plan.layer)} · 整层`;
    const names = (items, empty) => items.length
      ? `<ul>${items.map((name) => `<li>${esc(name)}</li>`).join('')}</ul>`
      : `<p class="layer-preview-empty">${esc(empty)}</p>`;
    if (title) title.textContent = `${a.name} ⇄ ${b.name}`;
    body.innerHTML = `<div class="compare-heads">`
      + `<div><b>A</b><strong>${esc(a.name)}</strong><small>${esc(scopeOf(a))} · ${a.strict ? '严格' : '宽松'}</small></div>`
      + `<div><b>B</b><strong>${esc(b.name)}</strong><small>${esc(scopeOf(b))} · ${b.strict ? '严格' : '宽松'}</small></div>`
      + `</div>`
      + `<section><h4><span class="compare-a">A</span> 只在 A 开启 <b>${onlyA.length}</b></h4>${names(onlyA, '没有')}</section>`
      + `<section><h4><span class="compare-b">B</span> 只在 B 开启 <b>${onlyB.length}</b></h4>${names(onlyB, '没有')}</section>`
      + `<section><h4><span class="preview-on">✓</span> 两边都开启 <b>${common.length}</b></h4>${names(common, '没有共同开启的条目')}</section>`
      + `<p class="help-note">这里只比较「开启了什么」。如果两个方案作用域不同，结果也会把这个差异算进去。</p>`;
  }

  function activePromptStats(data) {
    // 总览统计实际开启的全部条目，包括面板隐藏的区间标记，字符估算才不会偏低。
    const enabled = data.items.filter((item) => item.enabled);
    const roles = { system: 0, user: 0, assistant: 0 };
    const positions = { relative: 0, chat: 0 };
    const layers = { structure: [], function: [], style: [] };
    let chars = 0;
    enabled.forEach((item) => {
      roles[item.role] = (roles[item.role] || 0) + 1;
      positions[item.injectionPosition === 1 ? 'chat' : 'relative'] += 1;
      chars += String(item.content || '').length;
      if (!item.hiddenFromPanel && layers[item.layer]) layers[item.layer].push(item.name);
    });
    return { enabled, roles, positions, layers, chars };
  }

  const markdownEsc = (value) => String(value == null ? '' : value).replace(/([\\`*_{}\[\]()#+.!|>~-])/g, '\\$1');

  function configMarkdown(data) {
    const stats = activePromptStats(data);
    const bigName = normalizeName(presetName()) || '未命名预设';
    const layerPlanText = LAYERS.map((layer) => {
      const plan = activeLayerPlan(layer.id);
      return `${layer.label}：${plan ? plan.name : '未选小方案'}`;
    }).join('｜');
    const lines = [
      '## Izumi 当前配置',
      `- 大方案：${markdownEsc(bigName)}`,
      `- 小方案：${markdownEsc(layerPlanText)}`,
      `- 总计：${stats.enabled.length} 条开启，约 ${stats.chars.toLocaleString()} 字符`,
      `- 角色：system ${stats.roles.system || 0}｜user ${stats.roles.user || 0}｜assistant ${stats.roles.assistant || 0}`,
      `- 位置：相对位置 ${stats.positions.relative}｜聊天内 ${stats.positions.chat}`,
      '',
    ];
    LAYERS.forEach((layer) => {
      const names = stats.layers[layer.id];
      lines.push(`### ${layer.label}（${names.length}）`);
      lines.push(names.length ? names.map((name) => `- ${markdownEsc(name)}`).join('\n') : '- 无');
      lines.push('');
    });
    return lines.join('\n').trim();
  }

  async function copyCurrentConfig(data) {
    const source = data || promptData();
    const stats = activePromptStats(source);
    const text = configMarkdown(source);
    let copied = false;
    try {
      const clipboard = pwin.navigator && pwin.navigator.clipboard;
      if (clipboard && typeof clipboard.writeText === 'function') {
        await clipboard.writeText(text);
        copied = true;
      }
    } catch (_) {}
    if (!copied) {
      openTransferDialog('export', text, `Izumi当前配置 ${new Date().toISOString().slice(0, 10)}.md`);
      return toast('自动复制没成功，已经把清单放进文本框啦～', 'error');
    }
    toast(`已复制当前配置：${stats.enabled.length} 条开启～`, 'success');
  }

  // 显眼的方案名部件：一眼看清「现在这套配置到底是啥」，点哪段改哪段。
  function renderPlanBanner(panel, data, signatureCache) {
    const banner = panel.querySelector(`#${ID}-plan-banner`);
    if (!banner) return;
    const bigName = normalizeName(presetName()) || '未命名预设';
    const segments = LAYERS.map((layer) => {
      const plan = activeLayerPlan(layer.id);
      if (!plan) {
        return `<button class="banner-seg empty" data-action="layer-plan-focus" data-layer="${layer.id}" title="${esc(layer.label)}：未选用小方案">${esc(layer.label)}<i>—</i></button>`;
      }
      const dirty = isLayerPlanDirty(plan, data, signatureCache);
      return `<button class="banner-seg${dirty ? ' dirty' : ''}" data-action="layer-plan-rename" data-layer="${layer.id}" data-plan="${esc(plan.id)}" title="点击给「${esc(plan.name)}」改名">${esc(layer.label)}<i>${esc(plan.name)}${dirty ? ' *' : ''}</i></button>`;
    }).join('');
    const stats = summaryOpen ? activePromptStats(data) : null;
    const summary = stats
      ? `<div class="active-summary">`
        + `<div><b>${stats.enabled.length}</b><span>开启条目</span></div>`
        + `<div><b>${stats.chars.toLocaleString()}</b><span>提示词字符</span></div>`
        + `<div><b>${stats.roles.system || 0}/${stats.roles.user || 0}/${stats.roles.assistant || 0}</b><span>系统/用户/助手</span></div>`
        + `<div><b>${stats.positions.relative}/${stats.positions.chat}</b><span>相对/聊天内</span></div>`
        + `<small>字符数是提示词正文的近似统计，不等于模型 token。</small>`
        + `</div>`
      : '';
    banner.innerHTML = `<div class="banner-main">`
      + `<div class="banner-big-row">`
      + `<button class="banner-big" data-action="plan-rename-big" title="点击重命名当前酒馆预设/大方案"><span class="banner-kicker">大方案</span><strong>${esc(bigName)}</strong></button>`
      + `<span class="banner-tools"><button data-action="toggle-summary" aria-expanded="${summaryOpen}">⌁ 生效总览</button><button data-action="copy-config">📋 复制配置</button></span>`
      + `</div>`
      + `<div class="banner-segs">${segments}</div>`
      + summary
      + `</div>`;
  }

  function renderItems(data = promptData()) {
    const panel = pdoc.getElementById(PANEL_ID);
    if (!panel) return;
    const nativeName = selectedNativePresetName();
    panel.querySelector(`#${ID}-preset`).textContent = nativeName
      ? `当前酒馆预设：${nativeName}`
      : '当前预设：未命名 / in_use';
    const saveTarget = panel.querySelector(`#${ID}-save-target`);
    if (saveTarget) saveTarget.textContent = nativeName ? '自动保存已启用' : '请先在酒馆保存为预设';
    const counts = { structure: 0, function: 0, style: 0 };
    data.items.forEach((item) => { if (Object.prototype.hasOwnProperty.call(counts, item.layer)) counts[item.layer] += 1; });
    const canMutate = data.mode === 'api' && !!(hostFunction('updatePresetWith') || hostFunction('replacePreset'));
    const hasSections = layerHasSections(activeLayer);
    if (!hasSections) activeFunctionSection = '';
    else if (!activeFunctionSection) activeFunctionSection = 'overview';
    const functionOverview = hasSections && activeFunctionSection === 'overview';
    const addButton = panel.querySelector('[data-action="add"]');
    if (addButton) {
      const canAdd = canMutate && !functionOverview;
      addButton.disabled = !canAdd;
      addButton.title = functionOverview
        ? '先选择一个子区'
        : (canAdd ? `添加到${hasSections && activeFunctionSection !== 'plain' ? sectionLabel(activeLayer, activeFunctionSection) : layerLabel(activeLayer)}` : '当前环境只支持在酒馆预设管理器中添加');
    }
    LAYERS.forEach((layer) => {
      // 选择器必须限定 .tab：方案名横幅的分段按钮也带 data-layer，
      // 而横幅在 DOM 里排在 tabs 前面，不限定的话 aria-selected 会被设到横幅上，
      // 导致底部高光条不跟着切换。
      const countNode = panel.querySelector(`.tabs [data-count="${layer.id}"]`);
      if (countNode) countNode.textContent = counts[layer.id];
      const tabNode = panel.querySelector(`.tabs .tab[data-layer="${layer.id}"]`);
      if (tabNode) tabNode.setAttribute('aria-selected', layer.id === activeLayer ? 'true' : 'false');
    });
    renderSectionTabs(panel, activeLayer);
    const signatureCache = new Map();
    renderLayerPlanBar(panel, data, activeLayer, signatureCache);
    renderPlanBanner(panel, data, signatureCache);
    panel.querySelector(`#${ID}-hint`).textContent = functionOverview
      ? '选择一个子区后再管理其中的条目'
      : LAYERS.find((layer) => layer.id === activeLayer).hint;
    const { layerItems, searched, visible, displayedCount } = filterDisplayItems(data.items, {
      layer: activeLayer, section: activeFunctionSection, hasSections,
      query: searchText, searchBody: searchBodyEnabled, state: displayState,
    });
    const stateSelect = panel.querySelector(`#${ID}-display-state`);
    if (stateSelect) stateSelect.value = displayState;
    const searchBodyToggle = panel.querySelector(`#${ID}-search-body`);
    if (searchBodyToggle) searchBodyToggle.checked = searchBodyEnabled;
    const searchInput = panel.querySelector(`#${ID}-search`);
    if (searchInput) searchInput.placeholder = searchBodyEnabled ? '筛选名称或正文' : '筛选当前目录';
    panel.querySelector(`#${ID}-count`).textContent = `${displayedCount}/${layerItems.length} 项`;
    const container = panel.querySelector(`#${ID}-items`);
    if (data.mode === 'none') {
      container.innerHTML = '<div class="empty"><strong>未读取到预设条目</strong><button class="command" data-action="manager">打开预设管理器</button></div>';
    } else if (functionOverview) {
      renderFunctionHub(container, searched);
    } else if (!visible.length) {
      container.innerHTML = '<div class="empty">当前目录没有匹配的条目</div>';
    } else {
      container.innerHTML = visible.map((item) => {
        const canDelete = canMutate && !item.systemPrompt;
        const drag = canMutate && item.functionSection
          ? `<button class="item-drag" draggable="true" title="拖动调整${FUNCTION_SECTION_LABELS[item.functionSection]}顺序" aria-label="拖动调整${FUNCTION_SECTION_LABELS[item.functionSection]}顺序">≡</button>`
          : '<span class="item-drag-spacer" aria-hidden="true"></span>';
        return `<div class="item-row ${item.enabled ? 'on' : ''}" data-item-index="${item.index}">${drag}<button class="item-edit" data-action="edit" data-index="${item.index}" title="${canMutate ? '编辑' : '请在酒馆预设管理器中编辑'} ${esc(item.name)}" ${canMutate ? '' : 'disabled'}><span class="toggle-name">${esc(item.name)}</span><span class="edit-mark" aria-hidden="true">✎</span></button><button class="item-toggle" data-action="toggle" data-index="${item.index}" aria-pressed="${item.enabled}" aria-label="${item.enabled ? '停用' : '启用'} ${esc(item.name)}" title="${item.enabled ? '停用' : '启用'}"><span class="led"></span></button><button class="item-delete" data-action="delete-entry" data-index="${item.index}" aria-label="删除 ${esc(item.name)}" title="${item.systemPrompt ? '酒馆系统条目不可删除' : '删除 ' + esc(item.name)}" ${canDelete ? '' : 'disabled'}>×</button></div>`;
      }).join('');
    }
  }

  function refreshPanel(options = {}) {
    if (refreshTimer) {
      clearTimeout(refreshTimer);
      refreshTimer = null;
    }
    const data = options.promptData || promptData();
    // 正常刷新顺手更新「当前动态缓存」；还原/回退过程中会显式跳过，避免覆盖现场。
    if (options.skipSnapshotSync !== true) {
      try { syncSessionSnapshot(data); } catch (_) {}
    }
    // 每次刷新都反查一下各层命中的小方案，chip 高亮和横幅才不会过期。
    if (options.detectPlans !== false) {
      try { detectActiveLayerPlans(data); } catch (_) {}
    }
    knownToggleShape = data.items.length
      ? data.items.map((item) => `${item.id}|${item.name}|${item.enabled !== false ? 1 : 0}`).join('\n')
      : knownToggleShape;
    renderItems(data);
    renderPlanList(options.planList || plans());
    scheduleRegexLinkage();
    if (options.renderApi !== false) renderApiConfig(currentApiConfig);
  }

  function scheduleRefresh(delay = 180, options = {}) {
    clearTimeout(refreshTimer);
    refreshTimer = setTimeout(() => {
      refreshTimer = null;
      if (!stopped && panelOpen) refreshPanel(options);
    }, delay);
  }

  function initialPosition() {
    const viewport = viewportMetrics();
    const mobile = isMobileIconLayout();
    const fallback = mobile
      ? mobileCornerPosition(viewport)
      : { x: viewport.left + viewport.width - ICON_SIZE - 24, y: viewport.top + 140 };
    const store = storage();
    if (!store) return fallback;
    try {
      const key = mobile ? MOBILE_POSITION_KEY : POSITION_KEY;
      const saved = normalizeDockPosition(JSON.parse(store.getItem(key) || 'null'));
      return saved ? { ...saved, saved: true } : fallback;
    } catch (_) {
      return fallback;
    }
  }

  function viewportMetrics() {
    const visual = pwin && pwin.visualViewport;
    return {
      width: Math.max(1, Number(visual && visual.width) || pwin.innerWidth || 1),
      height: Math.max(1, Number(visual && visual.height) || pwin.innerHeight || 1),
      left: Math.max(0, Number(visual && visual.offsetLeft) || 0),
      top: Math.max(0, Number(visual && visual.offsetTop) || 0),
    };
  }

  function isMobileViewport(viewport = viewportMetrics()) {
    return viewport.width <= MOBILE_BREAKPOINT;
  }

  function isMobileIconLayout() {
    // Pinch zoom changes visualViewport width, not the CSS media query or store.
    return (Number(pwin.innerWidth) || viewportMetrics().width) <= MOBILE_BREAKPOINT;
  }

  function iconSize() {
    return isMobileIconLayout() ? MOBILE_ICON_SIZE : ICON_SIZE;
  }

  function mobileCornerPosition(viewport = viewportMetrics()) {
    const size = iconSize(viewport);
    return {
      x: Math.max(viewport.left + 4, viewport.left + viewport.width - size - MOBILE_ICON_EDGE),
      y: Math.max(viewport.top + 4, viewport.top + viewport.height - size - MOBILE_ICON_BOTTOM_GAP),
    };
  }

  function iconComputedStyle(element = icon) {
    try { return element && pwin.getComputedStyle(element); } catch (_) { return null; }
  }

  function iconSafeInsets() {
    const computed = iconComputedStyle();
    const insets = {};
    for (const side of ['left', 'right', 'top', 'bottom']) {
      insets[side] = Math.max(0, parseFloat(computed && computed.getPropertyValue(`--izumi-safe-${side}`)) || 0);
    }
    return insets;
  }

  // offset sizes are untransformed border boxes. Temporarily remove only the dock
  // class so a resize/breakpoint change never measures the tab as the avatar.
  function expandedIconSize() {
    const folded = icon && icon.classList.contains('edge-docked');
    if (folded) icon.classList.remove('edge-docked');
    try {
      const computed = iconComputedStyle();
      const mobileCSS = isMobileIconLayout();
      const fallback = (mobileCSS ? MOBILE_ICON_SIZE + 8 : ICON_SIZE + 10);
      const dimension = (axis, first, last) => {
        const layout = Number(icon && icon[axis === 'width' ? 'offsetWidth' : 'offsetHeight']);
        if (layout > 0 && Number.isFinite(layout)) return layout;
        let value = parseFloat(computed && computed[axis]);
        if (!(value > 0)) return fallback;
        if (computed.boxSizing !== 'border-box') {
          for (const property of [`padding${first}`, `padding${last}`, `border${first}Width`, `border${last}Width`]) value += parseFloat(computed[property]) || 0;
        }
        return value;
      };
      return { width: dimension('width', 'Left', 'Right'), height: dimension('height', 'Top', 'Bottom') };
    } finally {
      if (folded) icon.classList.add('edge-docked');
    }
  }

  function clamp(x, y) {
    return clampExpandedPosition({ x, y }, viewportMetrics(), expandedIconSize(), iconSafeInsets());
  }

  function updateIconDockAppearance() {
    icon.classList.toggle('edge-docked', !!iconDock);
    icon.classList.toggle('dock-left', iconDock === 'left');
    icon.setAttribute('aria-label', iconDock ? '展开泉此方悬浮头像' : '打开或关闭泉此方面板');
  }

  function layoutIcon() {
    const mobile = isMobileIconLayout();
    const visibleWidth = mobile ? MOBILE_ICON_SIZE / 3 : 20;
    const visibleHeight = mobile ? MOBILE_ICON_SIZE : 56;
    // Mobile keeps only a small inward/vertical touch margin around the slim handle.
    const hitSize = mobile ? { width: visibleWidth + 8, height: visibleHeight + 8 } : { width: 44, height: 56 };
    const next = iconDock
      ? getDockPosition(iconDock, iconAnchor.y, viewportMetrics(), hitSize, iconSafeInsets())
      : iconAnchor;
    if (iconDock) {
      icon.style.setProperty('--izumi-tab-width', `${next.width}px`);
      icon.style.setProperty('--izumi-tab-height', `${next.height}px`);
      icon.style.setProperty('--izumi-tab-visible-width', `${visibleWidth}px`);
      icon.style.setProperty('--izumi-tab-visible-height', `${visibleHeight}px`);
    }
    icon.style.left = `${next.x}px`;
    icon.style.top = `${next.y}px`;
    updateIconDockAppearance();
  }

  function restoreIcon() {
    iconDock = null;
    icon.classList.add('free-position');
    iconAnchor = clamp(iconAnchor.x, iconAnchor.y);
    layoutIcon();
    savePosition(icon);
  }

  function foldIcon(side, panel, quickMenu) {
    iconDock = side;
    panelOpen = false;
    panel.style.display = 'none';
    icon.classList.remove('panel-open');
    closeAllPanelOverlays(panel);
    closeQuickMenu(quickMenu);
    clearTimeout(playTimer);
    playTimer = null;
    const image = icon.querySelector('img');
    if (image) {
      image.onerror = null;
      image.classList.remove('is-playing');
      image.src = STATIC_SRC;
    }
    layoutIcon();
  }

  function resizeIconPosition() {
    if (cancelIconGesture) cancelIconGesture();
    const viewport = viewportMetrics();
    iconAnchor = !iconDock && isMobileIconLayout() && !icon.classList.contains('free-position')
      ? mobileCornerPosition(viewport)
      : clamp(iconAnchor.x, iconAnchor.y);
    layoutIcon();
  }

  function savePosition(element) {
    const store = storage();
    if (!store) return;
    try {
      const key = isMobileIconLayout() ? MOBILE_POSITION_KEY : POSITION_KEY;
      const position = iconAnchor || { x: parseFloat(element.style.left), y: parseFloat(element.style.top) };
      store.setItem(key, JSON.stringify({ x: position.x, y: position.y, ...(iconDock ? { dock: iconDock } : {}) }));
    } catch (_) {}
  }

  function storedPanelPosition() {
    const store = storage();
    if (!store) return null;
    try {
      const value = JSON.parse(store.getItem(PANEL_POSITION_KEY) || 'null');
      return value && Number.isFinite(Number(value.x)) && Number.isFinite(Number(value.y))
        ? { x: Number(value.x), y: Number(value.y) }
        : null;
    } catch (_) {
      return null;
    }
  }

  function panelSizeBounds(viewport = viewportMetrics()) {
    const maxWidth = Math.max(1, viewport.width - 12);
    const maxHeight = Math.max(1, viewport.height - 12);
    return {
      minWidth: Math.min(320, maxWidth),
      maxWidth,
      minHeight: Math.min(360, maxHeight),
      maxHeight,
    };
  }

  function clampPanelSize(width, height, viewport = viewportMetrics()) {
    const bounds = panelSizeBounds(viewport);
    return {
      width: Math.max(bounds.minWidth, Math.min(Number(width) || bounds.minWidth, bounds.maxWidth)),
      height: Math.max(bounds.minHeight, Math.min(Number(height) || bounds.minHeight, bounds.maxHeight)),
    };
  }

  function storedPanelSize() {
    const store = storage();
    if (!store) return null;
    try {
      const value = JSON.parse(store.getItem(PANEL_SIZE_KEY) || 'null');
      return value && Number.isFinite(Number(value.width)) && Number.isFinite(Number(value.height))
        ? { width: Number(value.width), height: Number(value.height) }
        : null;
    } catch (_) {
      return null;
    }
  }

  function applyPanelSize(panel, width, height) {
    const next = clampPanelSize(width, height);
    Object.assign(panel.style, {
      width: `${next.width}px`,
      height: `${next.height}px`,
      maxHeight: `${next.height}px`,
    });
    return next;
  }

  function savePanelSize(panel) {
    const store = storage();
    if (!store) return;
    const rect = panel.getBoundingClientRect();
    try {
      store.setItem(PANEL_SIZE_KEY, JSON.stringify({ width: Math.round(rect.width), height: Math.round(rect.height) }));
    } catch (_) {}
  }

  function clampPanelPosition(panel, x, y) {
    const rect = panel.getBoundingClientRect();
    const gap = 6;
    const viewport = viewportMetrics();
    const width = Math.min(rect.width || 320, Math.max(1, viewport.width - gap * 2));
    const height = Math.min(rect.height || 240, Math.max(1, viewport.height - gap * 2));
    return {
      x: Math.max(viewport.left + gap, Math.min(Number(x) || viewport.left + gap, Math.max(viewport.left + gap, viewport.left + viewport.width - width - gap))),
      y: Math.max(viewport.top + gap, Math.min(Number(y) || viewport.top + gap, Math.max(viewport.top + gap, viewport.top + viewport.height - height - gap))),
    };
  }

  function applyPanelPosition(panel, x, y) {
    const next = clampPanelPosition(panel, x, y);
    Object.assign(panel.style, { right: 'auto', bottom: 'auto', left: `${next.x}px`, top: `${next.y}px` });
    return next;
  }

  function savePanelPosition(panel) {
    const store = storage();
    if (!store) return;
    try {
      store.setItem(PANEL_POSITION_KEY, JSON.stringify({
        x: parseFloat(panel.style.left),
        y: parseFloat(panel.style.top),
      }));
    } catch (_) {}
  }

  function positionPanel(icon, panel) {
    if (!panelOpen) return;
    const viewport = viewportMetrics();
    if (isMobileViewport(viewport)) {
      panel.dataset.userPosition = 'false';
      panel.dataset.userSize = 'false';
      Object.assign(panel.style, {
        left: `${viewport.left + 8}px`,
        right: 'auto',
        top: `${viewport.top + 8}px`,
        bottom: 'auto',
        width: `${Math.max(280, viewport.width - 16)}px`,
        height: `${Math.max(240, viewport.height - 16)}px`,
        maxHeight: `${Math.max(240, viewport.height - 16)}px`,
      });
      return;
    }
    const rect = icon.getBoundingClientRect();
    const edge = 12;
    const gap = 12;
    const roomRight = Math.max(0, viewport.left + viewport.width - edge - rect.right - gap);
    const roomLeft = Math.max(0, rect.left - gap - viewport.left - edge);
    const openRight = roomRight >= roomLeft;
    const savedSize = storedPanelSize();
    if (panel.dataset.userSize === 'true') {
      const current = panel.getBoundingClientRect();
      applyPanelSize(panel, current.width, current.height);
    } else if (savedSize) {
      panel.dataset.userSize = 'true';
      applyPanelSize(panel, savedSize.width, savedSize.height);
    } else {
      const defaultSize = clampPanelSize(Math.min(520, Math.max(roomRight, roomLeft)), Math.min(680, viewport.height - 32), viewport);
      panel.dataset.userSize = 'false';
      applyPanelSize(panel, defaultSize.width, defaultSize.height);
    }
    if (panel.dataset.userPosition === 'true') {
      applyPanelPosition(panel, parseFloat(panel.style.left), parseFloat(panel.style.top));
      return;
    }
    const saved = storedPanelPosition();
    if (saved) {
      panel.dataset.userPosition = 'true';
      applyPanelPosition(panel, saved.x, saved.y);
      return;
    }
    const panelRect = panel.getBoundingClientRect();
    applyPanelPosition(
      panel,
      openRight ? rect.right + gap : rect.left - gap - panelRect.width,
      Math.max(viewport.top + 12, Math.min(rect.top - 8, viewport.top + viewport.height - panelRect.height - 12)),
    );
  }

  function bindPanelDrag(panel) {
    const handle = panel.querySelector('[data-drag-handle]');
    if (!handle) return;
    let drag = null;
    handle.addEventListener('pointerdown', (event) => {
      if (viewportMetrics().width <= 700 || event.button !== 0 || event.target.closest('button,a,input,select,textarea')) return;
      event.preventDefault();
      event.stopPropagation();
      const rect = panel.getBoundingClientRect();
      drag = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        x: rect.left,
        y: rect.top,
      };
      panel.dataset.userPosition = 'true';
      panel.classList.add('dragging');
      Object.assign(panel.style, { left: `${rect.left}px`, top: `${rect.top}px`, right: 'auto', bottom: 'auto', width: `${rect.width}px` });
      try { handle.setPointerCapture(event.pointerId); } catch (_) {}
    });
    handle.addEventListener('pointermove', (event) => {
      if (!drag || event.pointerId !== drag.pointerId) return;
      event.preventDefault();
      applyPanelPosition(panel, drag.x + event.clientX - drag.startX, drag.y + event.clientY - drag.startY);
    });
    const end = (event) => {
      if (!drag || event.pointerId !== drag.pointerId) return;
      try { handle.releasePointerCapture(event.pointerId); } catch (_) {}
      drag = null;
      panel.classList.remove('dragging');
      savePanelPosition(panel);
    };
    handle.addEventListener('pointerup', end);
    handle.addEventListener('pointercancel', end);
  }

  function bindPanelResize(panel) {
    const handle = panel.querySelector('[data-resize-handle]');
    if (!handle) return;
    let resize = null;
    handle.addEventListener('pointerdown', (event) => {
      if (viewportMetrics().width <= MOBILE_BREAKPOINT || event.button !== 0) return;
      event.preventDefault();
      event.stopPropagation();
      const rect = panel.getBoundingClientRect();
      resize = { pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, width: rect.width, height: rect.height };
      panel.dataset.userSize = 'true';
      try { handle.setPointerCapture(event.pointerId); } catch (_) {}
    });
    handle.addEventListener('pointermove', (event) => {
      if (!resize || event.pointerId !== resize.pointerId) return;
      event.preventDefault();
      applyPanelSize(panel, resize.width + event.clientX - resize.startX, resize.height + event.clientY - resize.startY);
      applyPanelPosition(panel, parseFloat(panel.style.left), parseFloat(panel.style.top));
    });
    const end = (event) => {
      if (!resize || event.pointerId !== resize.pointerId) return;
      try { handle.releasePointerCapture(event.pointerId); } catch (_) {}
      resize = null;
      savePanelSize(panel);
      savePanelPosition(panel);
    };
    handle.addEventListener('pointerup', end);
    handle.addEventListener('pointercancel', end);
  }

  let animatedImageUnavailable = false;

  function fallBackToStaticIcon(image) {
    animatedImageUnavailable = true;
    clearTimeout(playTimer);
    playTimer = null;
    if (!image) return;
    image.classList.remove('is-playing');
    image.src = STATIC_SRC;
  }

  function play(icon) {
    if (iconDock || stopped) return;
    try { if (pwin.matchMedia && pwin.matchMedia('(prefers-reduced-motion: reduce)').matches) return; } catch (_) {}
    const image = icon.querySelector('img');
    if (!image || image.classList.contains('is-playing') || animatedImageUnavailable) return;
    clearTimeout(playTimer);
    image.classList.add('is-playing');
    image.onerror = () => {
      image.onerror = null;
      fallBackToStaticIcon(image);
    };
    image.src = ANIMATED_SRC;
    playTimer = setTimeout(() => {
      if (stopped) return;
      image.onerror = null;
      image.classList.remove('is-playing');
      image.src = STATIC_SRC;
      playTimer = null;
    }, GIF_DURATION);
  }

  function createPromptIdentifier(prompts) {
    const existing = new Set((Array.isArray(prompts) ? prompts : []).map(promptIdentifier).filter(Boolean));
    for (let attempt = 0; attempt < 8; attempt += 1) {
      let value = '';
      try {
        const cryptoObject = (pwin && pwin.crypto) || (typeof crypto !== 'undefined' ? crypto : null);
        if (cryptoObject && typeof cryptoObject.randomUUID === 'function') value = cryptoObject.randomUUID();
      } catch (_) {}
      if (!value) value = `izumi-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
      if (!existing.has(value)) return value;
    }
    return `izumi-${Date.now()}-${existing.size}`;
  }

  // Preset.prompts is TavernHelper's live UI order. Mirror that order to the
  // native prompt_order records before saving, so reloading the same preset keeps it.

  async function reorderPrompt(draggedIndex, targetIndex, draggedName = '', targetName = '') {
    const data = promptData();
    const dragged = resolvePromptItem(data, draggedIndex, null, draggedName);
    const target = resolvePromptItem(data, targetIndex, null, targetName);
    if (!dragged || !target || !dragged.functionSection || dragged.functionSection !== target.functionSection) {
      return toast('只能在同一个子区里面调顺序哦～', 'error');
    }
    if (data.mode !== 'api' || !(hostFunction('updatePresetWith') || hostFunction('replacePreset'))) return toast('顺序动不了：读不到酒馆的预设接口，看看「酒馆助手」开着没～', 'error');
    let changed = false;
    let mutationApplied = false;
    try {
      await enqueueWrite(() => updatePresetCompat((preset) => {
        mutationApplied = movePresetPrompt(preset, dragged.id, target.id);
        return preset;
      }, { render: 'immediate' }));
      changed = mutationApplied;
    } catch (error) {
      console.warn('[Izumi floating window] prompt reorder failed', error);
    }
    if (!changed) return toast('顺序没有变化', 'error');
    refreshPanel();
    toast('已在' + FUNCTION_SECTION_LABELS[dragged.functionSection] + '调整顺序', 'success');
  }

  function bindItemReorder(panel) {
    const container = panel.querySelector(`#${ID}-items`);
    if (!container) return;
    let draggedIndex = null;
    let draggedName = '';
    const clear = () => container.querySelectorAll('.item-row.drag-over').forEach((row) => row.classList.remove('drag-over'));
    container.addEventListener('dragstart', (event) => {
      const handle = event.target.closest('.item-drag');
      const row = handle && handle.closest('.item-row[data-item-index]');
      if (!row) return;
      draggedIndex = Number(row.dataset.itemIndex);
      draggedName = normalizeName(row.querySelector('.toggle-name')?.textContent || '');
      if (!Number.isInteger(draggedIndex)) {
        event.preventDefault();
        return;
      }
      row.classList.add('dragging-item');
      try {
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', String(draggedIndex));
      } catch (_) {}
    });
    container.addEventListener('dragover', (event) => {
      const row = event.target.closest('.item-row[data-item-index]');
      if (!row || draggedIndex == null || Number(row.dataset.itemIndex) === draggedIndex) return;
      const data = promptData();
      const dragged = data.items.find((item) => item.index === draggedIndex);
      const target = data.items.find((item) => item.index === Number(row.dataset.itemIndex));
      if (!dragged || !target || !dragged.functionSection || dragged.functionSection !== target.functionSection) return;
      event.preventDefault();
      clear();
      row.classList.add('drag-over');
      try { event.dataTransfer.dropEffect = 'move'; } catch (_) {}
    });
    container.addEventListener('dragleave', (event) => {
      const row = event.target.closest('.item-row.drag-over');
      if (row && !row.contains(event.relatedTarget)) row.classList.remove('drag-over');
    });
    container.addEventListener('drop', async (event) => {
      const row = event.target.closest('.item-row[data-item-index]');
      if (!row || draggedIndex == null) return;
      event.preventDefault();
      const from = draggedIndex;
      const fromName = draggedName;
      const targetName = normalizeName(row.querySelector('.toggle-name')?.textContent || '');
      draggedIndex = null;
      draggedName = '';
      clear();
      await reorderPrompt(from, Number(row.dataset.itemIndex), fromName, targetName);
    });
    container.addEventListener('dragend', () => {
      draggedIndex = null;
      draggedName = '';
      clear();
      container.querySelectorAll('.item-row.dragging-item').forEach((row) => row.classList.remove('dragging-item'));
    });
  }

  function removePromptOrderReference(preset, identifier) {
    if (!identifier) return;
    promptOrderLists(preset).forEach((order) => {
      for (let index = order.length - 1; index >= 0; index -= 1) {
        if (String(order[index] && (order[index].identifier || order[index].id) || '') === identifier) order.splice(index, 1);
      }
    });
  }

  async function deletePrompt(index, button) {
    const data = promptData();
    const item = resolvePromptItem(data, index, button);
    if (!item) return toast('找不到这个条目了，点↻刷新一下～', 'error');
    if (item.systemPrompt) return toast('酒馆系统条目不能在悬浮窗中删除', 'error');
    if (data.mode !== 'api' || !(hostFunction('updatePresetWith') || hostFunction('replacePreset'))) return toast('这里删不了条目：读不到酒馆的预设接口，看看「酒馆助手」开着没～', 'error');
    const ask = pwin.confirm || (typeof confirm === 'function' ? confirm : null);
    if (ask && !ask.call(pwin, `删除${layerLabel(item.layer)}中的“${item.name}”？此操作会立即写回当前预设。`)) return;
    if (button) button.disabled = true;
    let changed = false;
    let mutationApplied = false;
    try {
      await enqueueWrite(() => updatePresetCompat((preset) => {
        const prompts = Array.isArray(preset.prompts) ? preset.prompts : [];
        const target = matchPrompt(prompts, item, true);
        const targetIndex = target ? prompts.indexOf(target) : -1;
        if (targetIndex < 0) return preset;
        const identifier = promptIdentifier(target);
        prompts.splice(targetIndex, 1);
        removePromptOrderReference(preset, identifier);
        mutationApplied = true;
        return preset;
      }, { render: 'immediate', removedPromptIds: [item.id] }));
      changed = mutationApplied;
    } catch (error) {
      console.warn('[Izumi floating window] prompt delete failed', error);
    } finally {
      if (button) button.disabled = false;
    }
    if (!changed) return toast('没删掉，点↻刷新再试一次看看～', 'error');
    refreshPanel();
    toast(`已删除“${item.name}”`, 'success');
  }

  async function togglePrompt(index, button) {
    const data = promptData();
    const item = resolvePromptItem(data, index, button);
    if (!item) return toast('找不到这个条目了，点↻刷新一下～', 'error');
    const desired = !item.enabled;
    const exclusive = item.functionSection === 'tucao' || item.functionSection === 'thinking';
    const siblings = exclusive
      ? data.items.filter((candidate) => candidate.functionSection === item.functionSection && !candidate.hiddenFromPanel
        && (item.functionSection !== 'thinking' || thinkingLanguageItem(candidate) === thinkingLanguageItem(item)))
      : [];
    if (!desired && item.functionSection === 'tucao' && !siblings.some((candidate) => candidate.index !== item.index && candidate.enabled)) {
      return toast('吐槽区至少要留一个开着，不然会出问题～', 'error');
    }
    button.disabled = true;
    let changed = false;
    const apiMode = data.mode === 'api' && (hostFunction('updatePresetWith') || hostFunction('replacePreset'));
    if (apiMode) {
      let mutationApplied = false;
      try {
        await enqueueWrite(() => updatePresetCompat((preset) => {
          const prompts = Array.isArray(preset.prompts) ? preset.prompts : [];
          const target = matchPrompt(prompts, item, true);
          if (!target) return preset;
          setPromptEnabled(preset, target, desired);
          if (desired && exclusive) siblings.forEach((candidate) => {
            if (candidate.index === item.index) return;
            const sibling = matchPrompt(prompts, candidate, true);
            if (sibling) setPromptEnabled(preset, sibling, false);
          });
          // 只处理白名单里的直接矛盾项：开一边时，另一边自然关掉。
          if (desired) findDirectConflicts(data.items, item.name).forEach((candidate) => {
            const conflict = matchPrompt(prompts, candidate, true);
            if (conflict) setPromptEnabled(preset, conflict, false);
          });
          mutationApplied = true;
          return preset;
        }, { render: 'immediate' }));
        changed = mutationApplied;
      } catch (error) { console.warn('[Izumi floating window] prompt toggle failed', error); }
    } else {
      changed = clickDomPrompt(findDomPrompt(item), desired);
    }
    button.disabled = false;
    if (changed) {
      refreshPanel();
      const closed = desired ? findDirectConflicts(data.items, item.name).filter((candidate) => candidate.enabled) : [];
      if (closed.length) toast(`已开启「${item.name}」，同时关掉了矛盾的「${closed.map((entry) => entry.name).join('、')}」～`, 'success');
    } else toast(apiMode ? '预设没保存上，点↻刷新再试试；还是不行就按 F12 看看控制台' : '没改成功，先把酒馆的预设管理器打开一下～', 'error');
  }

  function closePromptEditor(restoreFocus, options = {}) {
    const panel = pdoc.getElementById(PANEL_ID);
    const overlay = pdoc.getElementById(`${ID}-editor`);
    closePanelOverlay(overlay, panel, options);
    editingPrompt = null;
    if (restoreFocus !== false && editorOpener && typeof editorOpener.focus === 'function') {
      try { editorOpener.focus({ preventScroll: true }); } catch (_) { try { editorOpener.focus(); } catch (_) {} }
    }
    editorOpener = null;
  }

  function openPromptEditor(index, opener) {
    const data = promptData();
    const isNew = index == null;
    const defaultFunctionSection = normalizeSectionForLayer(activeLayer, activeFunctionSection);
    const item = isNew
      ? {
        id: createPromptIdentifier(data.preset && data.preset.prompts),
        name: `${layerLabel(activeLayer)}新条目`,
        index: data.items.length,
        contentKey: 'content',
        marker: false,
        role: 'system',
        triggers: [],
        injectionPosition: 0,
        injectionDepth: 4,
        injectionOrder: 100,
        content: '',
        layer: activeLayer,
        pinnedLayer: activeLayer,
        functionSection: defaultFunctionSection,
      }
      : data.items.find((candidate) => candidate.index === index);
    const overlay = pdoc.getElementById(`${ID}-editor`);
    const nameInput = pdoc.getElementById(`${ID}-editor-name`);
    const layerInput = pdoc.getElementById(`${ID}-editor-layer`);
    const sectionInput = pdoc.getElementById(`${ID}-editor-section`);
    const sectionField = pdoc.getElementById(`${ID}-editor-section-field`);
    const roleInput = pdoc.getElementById(`${ID}-editor-role`);
    const triggerInput = pdoc.getElementById(`${ID}-editor-trigger`);
    const positionInput = pdoc.getElementById(`${ID}-editor-position`);
    const depthInput = pdoc.getElementById(`${ID}-editor-depth`);
    const orderInput = pdoc.getElementById(`${ID}-editor-order`);
    const contentInput = pdoc.getElementById(`${ID}-editor-content`);
    const title = pdoc.getElementById(`${ID}-editor-title`);
    if (!item || !overlay || !nameInput || !contentInput) return toast('找不到这个条目了～', 'error');
    if (isNew && (data.mode !== 'api' || !(hostFunction('updatePresetWith') || hostFunction('replacePreset')))) return toast('这里加不了条目：读不到酒馆的预设接口，看看「酒馆助手」开着没～', 'error');
    editingPrompt = {
      owner: captureWriteOwner(),
      isNew,
      id: item.id,
      name: item.name,
      index: item.index,
      contentKey: item.contentKey || '',
      marker: item.marker,
      role: item.role,
      triggers: clone(item.triggers || []),
      injectionPosition: item.injectionPosition,
      injectionDepth: item.injectionDepth,
      injectionOrder: item.injectionOrder,
      content: item.content || '',
      layer: normalizeLayer(item.layer) || activeLayer,
      pinnedLayer: normalizeLayer(item.pinnedLayer),
      functionSection: normalizeSectionForLayer(normalizeLayer(item.layer) || activeLayer, item.functionSection),
    };
    editorOpener = opener || null;
    nameInput.value = item.name;
    if (layerInput) layerInput.value = editingPrompt.layer;
    fillEditorSectionOptions(editingPrompt.layer, editingPrompt.functionSection);
    if (sectionInput) sectionInput.value = editingPrompt.functionSection;
    if (roleInput) roleInput.value = ['system', 'user', 'assistant'].includes(item.role) ? item.role : 'system';
    if (triggerInput) Array.from(triggerInput.options).forEach((option) => { option.selected = item.triggers.includes(option.value); });
    if (positionInput) positionInput.value = String(item.injectionPosition);
    if (depthInput) depthInput.value = String(item.injectionDepth);
    if (orderInput) orderInput.value = String(item.injectionOrder);
    contentInput.value = item.content || '';
    contentInput.disabled = !isNew && (!item.contentKey || item.marker);
    contentInput.placeholder = item.marker
      ? '标记型条目正文由 SillyTavern 动态生成，不能编辑'
      : (item.contentKey ? '' : '此条目正文由 SillyTavern 动态生成');
    if (title) title.textContent = isNew ? `添加到${layerLabel(editingPrompt.layer)}` : `编辑：${item.name}`;
    const panel = pdoc.getElementById(PANEL_ID);
    if (panel) openPanelOverlay(overlay, panel);
    setTimeout(() => {
      try { nameInput.focus({ preventScroll: true }); nameInput.select(); }
      catch (_) { try { nameInput.focus(); nameInput.select(); } catch (_) {} }
    }, 0);
  }

  async function savePromptEditor() {
    if (!editingPrompt) return;
    // Freeze both the target and its originating preset before entering the queue.
    const editorSession = editingPrompt;
    const editSession = clone(editorSession);
    try { assertWriteOwner(editSession.owner); }
    catch (error) { return toast(error.message, 'error'); }
    const nameInput = pdoc.getElementById(ID + '-editor-name');
    const layerInput = pdoc.getElementById(ID + '-editor-layer');
    const sectionInput = pdoc.getElementById(ID + '-editor-section');
    const roleInput = pdoc.getElementById(ID + '-editor-role');
    const triggerInput = pdoc.getElementById(ID + '-editor-trigger');
    const positionInput = pdoc.getElementById(ID + '-editor-position');
    const depthInput = pdoc.getElementById(ID + '-editor-depth');
    const orderInput = pdoc.getElementById(ID + '-editor-order');
    const contentInput = pdoc.getElementById(ID + '-editor-content');
    const name = normalizeName(nameInput && nameInput.value).slice(0, 240);
    const layer = normalizeLayer(layerInput && layerInput.value) || editSession.layer || activeLayer;
    const functionSection = normalizeSectionForLayer(layer, sectionInput && sectionInput.value);
    const role = normalizeName(roleInput && roleInput.value) || 'system';
    const triggers = triggerInput ? Array.from(triggerInput.selectedOptions).map((option) => option.value) : [];
    const injectionPosition = positionInput && Number(positionInput.value) === 1 ? 1 : 0;
    const injectionDepth = depthInput && Number.isFinite(Number(depthInput.value)) ? Math.max(0, Math.round(Number(depthInput.value))) : 4;
    const injectionOrder = orderInput && Number.isFinite(Number(orderInput.value)) ? Math.round(Number(orderInput.value)) : 100;
    const content = String(contentInput && contentInput.value || '');
    const data = promptData();
    if (!name) return toast('名字还空着呢，填一个吧～', 'error');
    if (data.mode !== 'api' || !(hostFunction('updatePresetWith') || hostFunction('replacePreset'))) return toast('这里改不了条目：读不到酒馆的预设接口，看看「酒馆助手」开着没～', 'error');
    let changed = false;
    let mutationApplied = false;
    try {
      await enqueueWrite(() => updatePresetCompat((preset) => {
        const prompts = Array.isArray(preset.prompts) ? preset.prompts : (preset.prompts = []);
        assertWriteOwner(editSession.owner);
        const edit = {
          id: editSession.id,
          name,
          content,
          role,
          triggers,
          injectionPosition,
          injectionDepth,
          injectionOrder,
          marker: editSession.marker === true,
          functionSection,
        };
        if (editSession.isNew || editSession.pinnedLayer || layer !== editSession.layer) edit.layer = layer;
        if (editSession.isNew) {
          const created = newPresetPrompt(edit, { enabled: true }, prompts);
          insertPresetPromptAtSection(preset, created, functionSection);
          mutationApplied = true;
          return preset;
        }
        const target = matchPrompt(prompts, editSession, true);
        if (!target) return preset;
        mutationApplied = applyPromptEdit(target, edit);
        if (functionSection && functionSection !== editSession.functionSection) {
          insertPresetPromptAtSection(preset, target, functionSection);
          mutationApplied = true;
        }
        return preset;
      }, { render: 'immediate' }));
      changed = mutationApplied;
    } catch (error) {
      console.warn('[Izumi floating window] prompt edit failed', error);
    }
    if (!changed) return toast('没保存上，点↻刷新再试一次看看～', 'error');
    const wasNew = editSession.isNew;
    if (editingPrompt === editorSession) {
      activeLayer = layer;
      activeFunctionSection = layerHasSections(layer) ? functionSection || 'plain' : '';
      closePromptEditor(false);
    }
    refreshPanel();
    toast((wasNew ? '已添加' : '已保存') + '“' + name + '”', 'success');
  }

  async function openManager() {
    const context = hostContext();
    const manager = context && typeof context.getPresetManager === 'function'
      ? (() => { try { return context.getPresetManager(context.mainApi === 'openai' ? 'openai' : ''); } catch (_) { return null; } })()
      : null;
    const managerMethods = ['open', 'show', 'openManager', 'openPresetManager', 'showPresetManager', 'openPromptManager'];
    for (const method of managerMethods) {
      if (!manager || typeof manager[method] !== 'function') continue;
      try {
        await manager[method]();
        setTimeout(refreshPanel, 180);
        toast('已打开酒馆预设管理器', 'success');
        return true;
      } catch (_) {}
    }
    const selectors = [
      '#completion_prompt_manager_button', '#completion_prompt_manager', '#openai_prompt_manager',
      '[data-pm-action="open"]', '[id*="prompt_manager"][id*="button"]',
      'button[title*="提示词"]', 'button[aria-label*="提示词"]',
    ];
    for (const selector of selectors) {
      const button = pdoc.querySelector(selector);
      if (!button || button === pdoc.getElementById(`${ID}-panel`)) continue;
      try {
        const EventCtor = pwin.MouseEvent || MouseEvent;
        button.dispatchEvent(new EventCtor('click', { bubbles: true, cancelable: true, view: pwin }));
        if (typeof button.click === 'function') button.click();
        setTimeout(refreshPanel, 180);
        toast('已请求打开酒馆预设管理器', 'success');
        return true;
      } catch (_) {}
    }
    toast('找不到酒馆预设管理器的入口，用下面的导入/导出按钮也可以～', 'error');
    return false;
  }

  function bindPanel(panel, icon) {
    bindPanelDrag(panel);
    bindPanelResize(panel);
    panel.addEventListener('click', async (event) => {
      event.stopPropagation();
      const button = event.target.closest('[data-action]');
      if (!button) return;
      event.preventDefault();
      const action = button.dataset.action;
      if (action === 'close') {
        closeAllPanelOverlays(panel, { restoreScroll: false });
        panelOpen = false;
        panel.style.display = 'none';
        icon.classList.remove('panel-open');
      } else if (action === 'shutdown') {
        const ask = pwin.confirm || (typeof confirm === 'function' ? confirm : null);
        if (!ask || ask.call(pwin, '彻底关闭会移除图标和面板；重新运行此脚本即可恢复。确定关闭吗？')) cleanup();
      } else if (action === 'clear-search') {
        clearTimeout(searchInputTimer);
        searchInputTimer = null;
        searchText = '';
        const input = panel.querySelector(`#${ID}-search`);
        if (input) input.value = '';
        renderItems();
        if (input) input.focus();
      } else if (action === 'refresh') {
        invalidatePromptDataCache();
        refreshPanel();
        try { renderApiConfig(await readCurrentApiConfig()); } catch (_) {}
      } else if (action === 'night') {
        nightMode = !nightMode;
        persistNightMode();
        applyNightMode(panel, icon);
        scheduleRegexLinkage();
      } else if (action === 'sanitizer-toggle') {
        setSanitizerEnabled(!sanitizerEnabled);
      } else if (action === 'sanitizer-settings') {
        openSanitizerSettingsDialog(panel);
      } else if (action === 'sanitizer-settings-save') {
        saveSanitizerSettingsDialog(panel);
      } else if (action === 'sanitizer-settings-close') {
        closeSanitizerSettingsDialog(panel);
      } else if (action === 'advice-toggle') {
        setAdviceEnabled(!adviceEnabled);
      } else if (action === 'advice-settings') {
        openAdviceSettingsDialog(panel);
      } else if (action === 'advice-settings-save') {
        saveAdviceSettingsDialog(panel);
      } else if (action === 'advice-settings-close') {
        closeAdviceSettingsDialog(panel);
      } else if (action === 'advice-replacement-reset') {
        resetAdviceReplacementText();
      } else if (action === 'tab') {
        activeLayer = normalizeLayer(button.dataset.layer) || activeLayer;
        activeFunctionSection = layerHasSections(activeLayer) ? 'overview' : '';
        renderItems();
      } else if (action === 'function-section') {
        const section = button.dataset.section || '';
        if (section === 'overview' || layerSections(activeLayer).includes(section)) {
          activeFunctionSection = section;
          renderItems();
        }
      } else if (action === 'layer-plan-apply') {
        if (button.dataset.longPressed === 'true') {
          delete button.dataset.longPressed;
          return;
        }
        button.disabled = true;
        try { await applyLayerPlan(button.dataset.plan); } finally { button.disabled = false; }
      } else if (action === 'session-restore') {
        button.disabled = true;
        try { await restoreSessionBaseline(); } finally { button.disabled = false; }
      } else if (action === 'session-undo') {
        button.disabled = true;
        try { await undoSessionRestore(); } finally { button.disabled = false; }
      } else if (action === 'layer-plan-compare') {
        openLayerPlanComparison(activeLayer, panel);
      } else if (action === 'layer-compare-run') {
        runLayerPlanComparison(normalizeLayer(button.dataset.layer) || activeLayer);
      } else if (action === 'layer-plan-guide-close') {
        try {
          const local = storage();
          if (local) local.setItem(LAYER_PLAN_GUIDE_KEY, 'seen');
        } catch (_) {}
        const guide = button.closest('.layer-plan-guide');
        if (guide) guide.remove();
      } else if (action === 'layer-preview-close') {
        closeLayerPlanPreview(panel);
      } else if (action === 'layer-plan-save') {
        saveLayerPlanFromCurrent(activeLayer, normalizeSectionForLayer(activeLayer, activeFunctionSection));
      } else if (action === 'layer-plan-rename') {
        renameLayerPlan(button.dataset.plan);
      } else if (action === 'layer-plan-focus') {
        activeLayer = normalizeLayer(button.dataset.layer) || activeLayer;
        activeFunctionSection = layerHasSections(activeLayer) ? 'overview' : '';
        renderItems();
      } else if (action === 'layer-plan-menu') {
        const menuPlanId = button.dataset.plan;
        const menuPlan = layerPlans().find((candidate) => candidate.id === menuPlanId);
        if (menuPlan) {
          const askMenu = pwin.prompt || (typeof prompt === 'function' ? prompt : null);
          const inQuick = quickSlots().includes(menuPlanId);
          const choice = askMenu
            ? normalizeName(askMenu.call(pwin, `「${menuPlan.name}」要做什么？1 = 改名，2 = 切换严格/宽松（当前${menuPlan.strict ? '严格' : '宽松'}），3 = 删除，4 = ${inQuick ? '移出' : '加入'}快捷方案`, '1'))
            : '';
          if (choice === '1') renameLayerPlan(menuPlanId);
          else if (choice === '2') toggleLayerPlanStrict(menuPlanId);
          else if (choice === '3') deleteLayerPlan(menuPlanId);
          else if (choice === '4') {
            const result = toggleQuickSlot(menuPlanId);
            if (!result.ok) return toast(storageFailureMessage('快捷方案未保存'), 'error');
            renderItems();
            toast(result.added ? `已把「${menuPlan.name}」放进快捷方案～` : `已把「${menuPlan.name}」移出快捷方案～`, 'success');
          }
        }
      } else if (action === 'plan-rename-big') {
        await renameBigPlan();
      } else if (action === 'toggle-summary') {
        summaryOpen = !summaryOpen;
        renderItems();
      } else if (action === 'copy-config') {
        await copyCurrentConfig(promptData());
      } else if (action === 'add') {
        openPromptEditor(null, button);
      } else if (action === 'toggle') {
        await togglePrompt(Number(button.dataset.index), button);
      } else if (action === 'edit') {
        openPromptEditor(Number(button.dataset.index), button);
      } else if (action === 'delete-entry') {
        await deletePrompt(Number(button.dataset.index), button);
      } else if (action === 'editor-save') {
        button.disabled = true;
        try { await savePromptEditor(); } finally { button.disabled = false; }
      } else if (action === 'editor-cancel') {
        closePromptEditor();
      } else if (action === 'manager') {
        await openManager();
      } else if (action === 'save') {
        await saveCurrentPlan();
      } else if (action === 'save-current') {
        await saveCurrentNativePreset();
      } else if (action === 'api-read') {
        try {
          renderApiConfig(await readCurrentApiConfig());
          toast('已读取当前 API 连接', 'success');
        } catch (_) {
          toast('读取 API 连接失败', 'error');
        }
      } else if (action === 'api-apply') {
        try {
          const result = await applyApiConfig(readApiForm());
          toast(result.ok ? '当前设置已写回 SillyTavern' : `设置未保存：${result.errors.join('、')}`, result.ok ? 'success' : 'error');
        } catch (error) {
          toast(error && error.message ? error.message : '设置保存失败', 'error');
        }
      } else if (action === 'api-models') {
        const value = readApiForm();
        if (value.source === 'custom' && !value.apiUrl) {
          toast('请先填写接口地址', 'error');
        } else {
          button.disabled = true;
          const status = apiElement('status');
          if (status) {
            status.textContent = '正在拉取模型…';
            status.classList.remove('kagami');
          }
          try {
            const models = await fetchModelList(value);
            if (!models.length) throw new Error('酒馆后端没有返回可用模型');
            availableModels = models;
            renderModelOptions(models, value.model);
            toast(`已拉取 ${availableModels.length} 个模型`, 'success');
            if (status) {
              status.textContent = `已加载 ${availableModels.length} 个模型`;
              status.classList.remove('kagami');
            }
          } catch (error) {
            availableModels = [];
            renderModelOptions([], value.model);
            if (status) {
              status.textContent = '模型列表读取失败';
              status.classList.add('kagami');
            }
            toast(error && error.message ? error.message : '模型列表读取失败', 'error');
          } finally {
            button.disabled = false;
          }
        }
      } else if (action === 'export') {
        exportPlans();
      } else if (action === 'help') {
        const overlay = pdoc.getElementById(`${ID}-help`);
        openPanelOverlay(overlay, panel);
      } else if (action === 'help-close') {
        const overlay = pdoc.getElementById(`${ID}-help`);
        closePanelOverlay(overlay, panel);
      } else if (action === 'diagnostics') {
        openDiagnosticsDialog(panel);
      } else if (action === 'clean-junk') {
        const own = ownStorageKeys();
        const junk = storageGroups()
          .filter((group) => group.count >= 50 && !own.has(group.prefix))
          .slice(0, 8);
        if (!junk.length) {
          toast('没找到成堆的垃圾键，存储还算干净～', 'success');
        } else {
          const ask = pwin.prompt || (typeof prompt === 'function' ? prompt : null);
          const menu = junk.map((group, index) => `${index + 1}. ${group.prefix}*　${group.count} 个键　${formatBytes(group.chars)}`).join('\n');
          const pick = ask
            ? normalizeName(ask.call(pwin, `发现这些成规模的键族群（不属于本脚本）。\n输入序号删除对应族群的全部键：\n\n${menu}`, '1'))
            : '';
          const target = junk[Number(pick) - 1];
          if (target) {
            const confirmAsk = pwin.confirm || (typeof confirm === 'function' ? confirm : null);
            const warn = `将删除 ${target.count} 个以「${target.prefix}」开头的键，释放约 ${formatBytes(target.chars)}。\n这些键属于酒馆或其它扩展，删除后对应功能的历史缓存会丢失（一般会自动重建）。\n确定吗？`;
            if (!confirmAsk || confirmAsk.call(pwin, warn)) {
              const before = storageService.measuredChars != null ? storageService.measuredChars : storageChars();
              const result = purgeStorageFamily(target.prefix);
              renderPlanList();
              const summary = `已删除 ${result.removed} 个键：${formatBytes(before)} → ${formatBytes(storageService.measuredChars == null ? before : storageService.measuredChars)}`;
              const failure = result.failed ? `，${result.failed} 个删除失败` : '，清理未完成';
              toast(result.complete ? summary : summary + failure, result.complete ? 'success' : 'error');
            }
          }
        }
      } else if (action === 'storage-report') {
        openTransferDialog('export', storageReport(), `泉此方存储报告 ${new Date().toISOString().slice(0, 10)}.txt`);
        renderPlanList();
      } else if (action === 'purge-backups') {
        const ask = pwin.confirm || (typeof confirm === 'function' ? confirm : null);
        const count = plans().length;
        if (!count) {
          toast('本地已经没有大方案备份啦～', 'success');
        } else if (!ask || ask.call(pwin, `将删除本脚本的 ${count} 个本地大方案备份。\n酒馆里的预设和你的小方案都不受影响。\n建议先用「导出」存成文件。确定删除吗？`)) {
          const before = storageService.measuredChars != null ? storageService.measuredChars : storageChars();
          const result = storageService.remove(STORAGE_KEY);
          if (!result.complete) return toast(storageFailureMessage('本地备份未清空'), 'error');
          planCache = [];
          renderPlanList([]);
          toast(`已清空 ${count} 个本地备份：${formatBytes(before)} → ${formatBytes(storageService.measuredChars)}`, 'success');
        }
      } else if (action === 'compact-storage') {
        const before = storageService.measuredChars != null ? storageService.measuredChars : storageChars();
        const result = compactPlanStorage();
        renderPlanList();
        if (!result.touched) toast(`没有可精简的冗余副本（当前 ${formatBytes(before)}）`, 'success');
        else if (!result.ok) toast(storageFailureMessage('精简失败'), 'error');
        else toast(`已精简 ${result.touched} 个大方案备份，${formatBytes(before)} → ${formatBytes(storageService.measuredChars == null ? before : storageService.measuredChars)}`, 'success');
      } else if (action === 'export-current') {
        exportCurrentPreset();
      } else if (action === 'export-layer-plans') {
        exportLayerPlans();
      } else if (action === 'export-quick-plans') {
        exportQuickPlans();
      } else if (action === 'import') {
        openTransferDialog('import', '', '泉此方批量导入.json');
      } else if (action === 'transfer-paste') {
        await pasteTransferText();
      } else if (action === 'transfer-file') {
        panel.querySelector(`#${ID}-file`).click();
      } else if (action === 'transfer-copy') {
        await copyTransferText();
      } else if (action === 'transfer-download') {
        const overlay = panel.querySelector(`#${ID}-transfer`);
        const textarea = panel.querySelector(`#${ID}-transfer-text`);
        const ok = textarea && downloadText(textarea.value, overlay && overlay.dataset.filename || '泉此方方案.json');
        toast(ok ? '已重新下载 JSON' : '下载不可用，请复制文本导出', ok ? 'success' : 'error');
      } else if (action === 'transfer-import' || action === 'transfer-import-load') {
        const textarea = panel.querySelector(`#${ID}-transfer-text`);
        button.disabled = true;
        try {
          const imported = await importPlans(textarea ? textarea.value : '', { loadFirst: action === 'transfer-import-load' });
          if (imported.length) closeTransferDialog();
        } catch (_) {
        } finally {
          button.disabled = false;
        }
      } else if (action === 'transfer-close') {
        closeTransferDialog();
      } else if (action === 'load') {
        await applyPlan(plans()[Number(button.dataset.index)]);
      } else if (action === 'delete') {
        deletePlan(Number(button.dataset.index));
      }
    });
    // 长按小方案 450ms 只看预览，不应用。轻点仍然保持原来的切换行为。
    let layerPreviewTimer = null;
    let layerPreviewButton = null;
    const cancelLayerPreviewPress = () => {
      if (layerPreviewTimer) clearTimeout(layerPreviewTimer);
      layerPreviewTimer = null;
      layerPreviewButton = null;
    };
    panel.addEventListener('pointerdown', (event) => {
      const target = event.target.closest('.layer-chip-main[data-plan]');
      if (!target || event.button !== 0) return;
      cancelLayerPreviewPress();
      layerPreviewButton = target;
      layerPreviewTimer = setTimeout(() => {
        if (!layerPreviewButton) return;
        const pressed = layerPreviewButton;
        pressed.dataset.longPressed = 'true';
        setTimeout(() => { if (pressed.dataset.longPressed === 'true') delete pressed.dataset.longPressed; }, 800);
        openLayerPlanPreview(pressed.dataset.plan, panel);
        if (pwin.navigator && typeof pwin.navigator.vibrate === 'function') {
          try { pwin.navigator.vibrate(18); } catch (_) {}
        }
        cancelLayerPreviewPress();
      }, 450);
    });
    panel.addEventListener('pointerup', cancelLayerPreviewPress);
    panel.addEventListener('pointercancel', cancelLayerPreviewPress);
    panel.addEventListener('pointermove', (event) => {
      if (!layerPreviewButton) return;
      const rect = layerPreviewButton.getBoundingClientRect();
      if (event.clientX < rect.left - 8 || event.clientX > rect.right + 8 || event.clientY < rect.top - 8 || event.clientY > rect.bottom + 8) {
        cancelLayerPreviewPress();
      }
    });
    panel.addEventListener('change', (event) => {
      if (event.target.id === `${ID}-sanitizer-mode-select` && event.target.value === 'none') {
        const inputCheck = panel.querySelector(`#${ID}-sanitizer-input-only-check`);
        if (inputCheck) inputCheck.checked = true;
        return;
      }
      if (event.target.id === `${ID}-display-state`) {
        displayState = normalizeDisplayState(event.target.value);
        renderItems();
        return;
      }
      if (event.target.id === `${ID}-editor-layer`) {
        fillEditorSectionOptions(normalizeLayer(event.target.value), '');
        return;
      }
      if (event.target.id === `${ID}-advice-position-select`) {
        const stripCheck = pdoc.getElementById(`${ID}-advice-strip-model-check`);
        if (stripCheck) {
          const forced = event.target.value === 'head';
          if (forced) stripCheck.checked = true;
          stripCheck.disabled = forced;
        }
      }
    });
    bindItemReorder(panel);
    panel.querySelector(`#${ID}-search`).addEventListener('input', (event) => {
      const value = event.target.value || '';
      clearTimeout(searchInputTimer);
      searchInputTimer = setTimeout(() => {
        searchInputTimer = null;
        searchText = value;
        renderItems();
      }, 80);
    });
    const searchBodyToggle = panel.querySelector(`#${ID}-search-body`);
    if (searchBodyToggle) searchBodyToggle.addEventListener('change', (event) => {
      searchBodyEnabled = event.target.checked === true;
      renderItems();
    });
    const modelList = apiElement('model-list');
    if (modelList) modelList.addEventListener('change', (event) => {
      const model = apiElement('model');
      if (model) model.value = event.target.value || '';
    });
    const input = panel.querySelector(`#${ID}-file`);
    input.addEventListener('change', async () => {
      const files = Array.from(input.files || []);
      input.value = '';
      if (!files.length) return;
      const imported = await importPlanFiles(files);
      if (imported.length) closeTransferDialog();
    });
    panel.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape' || !anyPanelOverlayOpen()) return;
      event.preventDefault();
      event.stopPropagation();
      closeVisiblePanelOverlay(panel);
    });
    outsidePointerListener = (event) => {
      const quick = pdoc.getElementById(QUICK_ID);
      if (quick && !quick.hidden && !quick.contains(event.target) && !icon.contains(event.target)) closeQuickMenu(quick);
      if (panelOpen && !panel.contains(event.target) && !icon.contains(event.target)) {
        closeAllPanelOverlays(panel);
        panelOpen = false;
        panel.style.display = 'none';
        icon.classList.remove('panel-open');
      }
    };
    pdoc.addEventListener('pointerdown', outsidePointerListener, true);
    adviceEditorFocusListener = handleAdviceEditorFocus;
    pdoc.addEventListener('focusin', adviceEditorFocusListener, true);
  }

  // BEGIN WORDFLOW

  let wordflowPack = WORDFLOW_DEFAULT;
  try { const raw=storage() && storage().getItem(WORDFLOW_KEY); if(raw && raw.length<=400000) wordflowPack=validateWordflowPack(JSON.parse(raw)); } catch (_) {}
  let wordflowOptions = {level:1,char:'',target:'<user>',count:5,prefix:true};
  let wordflowResults = [];
  let wordflowScope = '';
  let wordflowBusy = false;
  let quickTab = 'words';
  const wordflowHistory = new Map();

  function currentWordflowScope() {
    return JSON.stringify([adviceChatKey(),normalizeName(presetName()),wordflowOptions.char.trim(),wordflowOptions.target.trim() || '<user>']);
  }

  function wordflowUsed() {
    const scope=currentWordflowScope();
    if (!wordflowHistory.has(scope)) {
      if(wordflowHistory.size>=12) wordflowHistory.delete(wordflowHistory.keys().next().value);
      wordflowHistory.set(scope,new Set());
    }
    return wordflowHistory.get(scope);
  }

  function wordflowMarkup() {
    const o=wordflowOptions;
    return `<div class="wf-form"><p class="wf-hint">先选关系、填写人物，再生成剧情建议。</p><div class="wf-fields">
      <label>亲密度<select data-wf-field="level">${[1,2,3,4,5].map(v=>`<option value="${v}" ${Number(o.level)===v?'selected':''}>${v} · ${['点头之交','熟悉','信赖','亲密','极亲密'][v-1]}</option>`).join('')}</select></label>
      <label>角色名<input data-wf-field="char" maxlength="80" value="${esc(o.char)}" placeholder="例如：泉此方"></label>
      <label>互动对象<input data-wf-field="target" maxlength="80" value="${esc(o.target)}" placeholder="默认 &lt;user&gt;"></label>
      <label>建议数量<input data-wf-field="count" type="number" min="1" max="20" value="${esc(o.count)}"></label>
      </div><label class="wf-prefix"><input data-wf-field="prefix" type="checkbox" ${o.prefix?'checked':''}>附加“结束当前事件，开启一个新事件”</label>
      <div class="wf-tools"><button data-wf="generate">生成／换一批</button><button data-wf="clear">清空本组已用记录</button></div>
      <details class="wf-library"><summary>词库管理</summary><small>当前词库：${esc(wordflowPack.name)}；默认5类词库，共${wordflowPack.nouns.length}类事物。重复过滤按名词＋事件，不按措辞。</small>
      <div class="wf-tools"><button data-wf="import">导入DIY词库</button><button data-wf="export">导出当前词库</button><button data-wf="reset">恢复默认词库</button></div>
      <input data-wf-file type="file" accept=".json,application/json" hidden></details>
      <div data-wf-results>${wordflowResults.map((r,i)=>`<div class="wf-result"><p>${esc(r.text)}</p><button data-wf="fill" data-wf-index="${i}">填入</button> <button data-wf="send" data-wf-index="${i}">发送</button></div>`).join('') || '<p>填写后点“生成”，这里显示建议。</p>'}</div></div>`;
  }

  function readWordflowForm(menu) {
    menu.querySelectorAll('[data-wf-field]').forEach(el=>{
      const key=el.dataset.wfField;
      wordflowOptions[key]=el.type==='checkbox'?el.checked:el.value;
    });
  }

  async function handleWordflowClick(event, menu, icon) {
    const button=event.target.closest('[data-wf]');
    if (!button || wordflowBusy) return;
    readWordflowForm(menu);
    const action=button.dataset.wf;
    try {
      if(action==='generate') {
        wordflowResults=generateWordflow(wordflowPack,wordflowOptions,wordflowUsed());
        wordflowScope=currentWordflowScope();
        if(!wordflowResults.length) toast('当前等级没有剩余可用组合，可提高等级、换词库或清空记录～','error');
        else if(wordflowResults.length<Number(wordflowOptions.count)) toast(`当前只剩 ${wordflowResults.length} 个合适组合～`);
      } else if(action==='clear') {
        if(!pwin.confirm('清空当前聊天、角色和互动对象的已用记录？')) return;
        wordflowHistory.delete(currentWordflowScope());wordflowResults=[];
      } else if(action==='import') {menu.querySelector('[data-wf-file]').click();return;
      } else if(action==='export') {
        if(!download(wordflowPack,'词库推进-'+wordflowPack.id+'.json')) {
          closeQuickMenu(menu);panelOpen=true;panel.style.display='flex';icon.classList.add('panel-open');
          positionPanel(icon,panel);openTransferDialog('export',JSON.stringify(wordflowPack,null,2),'词库推进.json');
        }
        return;
      } else if(action==='reset') {
        if(!pwin.confirm('恢复默认五类词库？已导入词库将被替换，可先导出备份。'))return;
        if(!writeStorageKey(WORDFLOW_KEY,JSON.stringify(WORDFLOW_DEFAULT))) throw new Error('默认词库未能保存');
        wordflowPack=WORDFLOW_DEFAULT;wordflowResults=[];
      } else if(action==='fill' || action==='send') {
        if(wordflowScope!==currentWordflowScope()) throw new Error('人物或聊天已变化，请重新生成建议');
        const item=wordflowResults[Number(button.dataset.wfIndex)];if(!item)return;
        if(action==='send' && /^\s*\//.test(item.text)) throw new Error('建议以斜杠开头，可能被酒馆当作命令；请改用填入并检查文本');
        const input=pdoc.querySelector('#send_textarea'),send=pdoc.querySelector('#send_but');
        if(!input || input.disabled || input.readOnly) throw new Error('找不到可用的酒馆输入框');
        if(action==='send' && (regexLinkageGenerating || !send || send.disabled || send.getAttribute('aria-disabled')==='true')) throw new Error('酒馆正在生成或发送入口不可用，可稍后重试');
        if(input.value.trim() && !pwin.confirm('输入框已有草稿，要替换为这条建议吗？'))return;
        wordflowBusy=true;
        // Fill native compose textarea only. Do not use slash commands/model APIs or touch chat arrays.
        input.value=item.text;
        input.dispatchEvent(new (pwin.Event || Event)('input',{bubbles:true}));
        if(action==='send') send.click(); else input.focus();
        const used=wordflowUsed();if(used.size>=1500)used.delete(used.values().next().value);used.add(item.key);
        wordflowResults=wordflowResults.filter(r=>r.key!==item.key);
        toast(action==='send'?'已交给酒馆发送；是否发送成功请查看聊天栏～':'建议已填入，可修改后再发送～');
        closeQuickMenu(menu);return;
      }
      renderQuickMenu(menu,icon);
    } catch(error) {toast(error.message || String(error),'error');}
    finally {wordflowBusy=false;}
  }

  async function importWordflowFile(file, menu, icon) {
    if(!file)return;
    const tokenScope=adviceChatKey();
    try {
      if(file.size>400000)throw new Error('词库文件不能超过400KB');
      const raw=await readFileText(file);
      if(!isCurrentIzumiInstance() || tokenScope!==adviceChatKey())return;
      if(raw.length>400000)throw new Error('词库文本过长');
      const pack=validateWordflowPack(JSON.parse(raw));
      if(!pwin.confirm(`用「${pack.name}」替换当前词库？需要保留原词库的话请先导出。`))return;
      if(!writeStorageKey(WORDFLOW_KEY,JSON.stringify(pack)))throw new Error('词库未能保存，原词库保持不变');
      wordflowPack=pack;wordflowResults=[];
      renderQuickMenu(menu,icon);toast('词库已导入～');
    }catch(error){toast(`导入失败：${error.message || error}`,'error');}
  }
  // END WORDFLOW

  function createQuickMenu() {
    const menu = pdoc.createElement('div');
    menu.id = QUICK_ID;
    menu.hidden = true;
    menu.style.width = 'min(420px, calc(100vw - 16px))';
    (pdoc.body || pdoc.documentElement).appendChild(menu);
    return menu;
  }

  function closeQuickMenu(menu) {
    if (menu) menu.hidden = true;
  }

  function positionQuickMenu(menu, icon) {
    if (!menu || !icon || menu.hidden) return;
    const viewport = viewportMetrics();
    const mobile = isMobileViewport(viewport);
    menu.classList.toggle('wf-fullscreen', mobile);
    if (mobile) {
      Object.assign(menu.style, {left: viewport.left + 'px', top: viewport.top + 'px',
        width: viewport.width + 'px', height: viewport.height + 'px', maxHeight: viewport.height + 'px'});
      return;
    }
    Object.assign(menu.style, {width:'min(460px, calc(100vw - 24px))',height:'auto',maxHeight:'min(82vh, 760px)'});
    const iconRect = icon.getBoundingClientRect();
    const rect = menu.getBoundingClientRect();
    let left = iconRect.left - rect.width - 8;
    if (left < viewport.left + 6) left = iconRect.right + 8;
    let top = iconRect.top + iconRect.height / 2 - rect.height / 2;
    top = Math.max(viewport.top + 6, Math.min(top, viewport.top + viewport.height - rect.height - 6));
    left = Math.max(viewport.left + 6, Math.min(left, viewport.left + viewport.width - rect.width - 6));
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
  }

  function openQuickMenu(menu, icon) {
    quickTab = 'words';
    if (wordflowScope !== currentWordflowScope()) wordflowResults = [];
    return renderQuickMenu(menu, icon);
  }

  function renderQuickMenu(menu, icon) {
    const list = quickSlotPlans();
    const plansMarkup = list.length
      ? list.map((plan, index) => `<button class="quick-plan" data-quick-plan="${esc(plan.id)}"><i>${index + 1}</i><span>${esc(plan.name)}</span><small>${esc(layerLabel(plan.layer))}</small></button>`).join('')
      : '<p class="quick-empty">快捷小方案还是空的，可以在小方案的「⋯」里添加～</p>';
    menu.innerHTML = `<div class="quick-title"><b>词库推进 / 快捷方案</b><button data-quick-close aria-label="关闭">×</button></div>`
      + `<div class="quick-controls"><div class="quick-sanitizer-group">${sanitizerControlMarkup('quick')}${sanitizerSettingsButtonMarkup('quick')}</div><div class="quick-advice-group">${adviceControlMarkup('quick')}${adviceSettingsButtonMarkup('quick')}</div></div>`
      + '<div class="wf-tabs"><button data-quick-tab="words" aria-pressed="' + (quickTab==='words') + '">词库推进</button><button data-quick-tab="plans" aria-pressed="' + (quickTab==='plans') + '">快捷方案</button></div>'
      + (quickTab === 'words' ? wordflowMarkup() : plansMarkup);
    menu.hidden = false;
    positionQuickMenu(menu, icon);
    return true;
  }

  function bindQuickMenu(menu, icon) {
    menu.addEventListener('input', () => { if(quickTab==='words') readWordflowForm(menu); });
    menu.addEventListener('change', event => {
      if(event.target.matches('[data-wf-file]')) { const file=event.target.files[0];event.target.value='';importWordflowFile(file,menu,icon); }
      else if(quickTab==='words') readWordflowForm(menu);
    });
    menu.addEventListener('click', async (event) => {
      event.stopPropagation();
      // Preserve native controls and details/summary toggling; only action buttons need cancellation.
      if(event.target.closest('input,select,label,summary')) return;
      event.preventDefault();
      const tab=event.target.closest('[data-quick-tab]');
      if(tab){if(quickTab==='words')readWordflowForm(menu);quickTab=tab.dataset.quickTab;renderQuickMenu(menu,icon);return;}
      if(event.target.closest('[data-wf]')){await handleWordflowClick(event,menu,icon);return;}
      event.stopPropagation();
      if (event.target.closest('[data-quick-close]')) return closeQuickMenu(menu);
      if (event.target.closest('[data-quick-sanitizer]')) {
        setSanitizerEnabled(!sanitizerEnabled);
        return;
      }
      if (event.target.closest('[data-quick-sanitizer-settings]')) {
        closeQuickMenu(menu);
        panelOpen = true;
        panel.style.display = 'flex';
        icon.classList.add('panel-open');
        refreshPanel();
        positionPanel(icon, panel);
        openSanitizerSettingsDialog(panel);
        return;
      }
      if (event.target.closest('[data-quick-advice]')) {
        setAdviceEnabled(!adviceEnabled);
        return;
      }
      if (event.target.closest('[data-quick-advice-settings]')) {
        closeQuickMenu(menu);
        panelOpen = true;
        panel.style.display = 'flex';
        icon.classList.add('panel-open');
        refreshPanel();
        positionPanel(icon, panel);
        openAdviceSettingsDialog(panel);
        return;
      }
      const button = event.target.closest('[data-quick-plan]');
      if (!button) return;
      button.disabled = true;
      try { await applyLayerPlan(button.dataset.quickPlan, { refresh: false }); }
      finally { button.disabled = false; closeQuickMenu(menu); }
    });
  }

  function bindIcon(icon, panel, quickMenu) {
    let gesture = null;
    let quickTimer = null;
    let keyboardClickUntil = 0;
    // Cancellation can precede pointerup by arbitrarily long (multi-touch,
    // resize or capture loss). Keep its terminal click owned until consumed or
    // a fresh primary pointerdown starts; a timeout alone cannot identify it.
    const cancelledPointerClicks = new Set();
    const listeners = [];
    const on = (type, handler) => {
      icon.addEventListener(type, handler);
      listeners.push([type, handler]);
    };
    const cancelQuickPress = () => {
      if (quickTimer !== null) clearTimeout(quickTimer);
      quickTimer = null;
    };
    const finishGesture = (cancelled) => {
      if (!gesture) return;
      const current = gesture;
      // Clear ownership before release: browsers may synchronously emit lostcapture.
      gesture = null;
      cancelQuickPress();
      if (cancelled) {
        cancelledPointerClicks.add(current.id);
        iconAnchor = current.anchor;
        iconDock = current.dock;
        icon.classList.toggle('free-position', current.free);
        layoutIcon();
        suppressClickUntil = Date.now() + 320;
      } else if (current.moved) {
        suppressClickUntil = Date.now() + 320;
        const side = getDockSide(iconAnchor, viewportMetrics(), expandedIconSize(), iconSafeInsets());
        if (side) foldIcon(side, panel, quickMenu);
        savePosition(icon);
      } else if (current.longPressed) {
        suppressClickUntil = Date.now() + 320;
      }
      try { icon.releasePointerCapture(current.id); } catch (_) {}
    };
    cancelIconGesture = () => finishGesture(true);
    lifecycle.add(() => {
      finishGesture(true);
      cancelQuickPress();
      cancelledPointerClicks.clear();
      for (const [type, handler] of listeners) icon.removeEventListener(type, handler);
      cancelIconGesture = null;
    });
    icon.setAttribute('role', 'button');
    icon.tabIndex = 0;
    updateIconDockAppearance();
    // Long press belongs to the quick menu, never to the browser image menu.
    on('contextmenu', (event) => { event.preventDefault(); event.stopPropagation(); });
    on('dragstart', (event) => event.preventDefault());
    on('pointerdown', (event) => {
      if (gesture) {
        if (event.pointerId !== gesture.id) {
          cancelledPointerClicks.add(event.pointerId);
          finishGesture(true);
        }
        return;
      }
      if (event.button !== 0 || event.isPrimary === false || stopped) return;
      if (cancelledPointerClicks.size) {
        cancelledPointerClicks.clear();
        suppressClickUntil = 0;
      }
      const mobile = isMobileIconLayout();
      if (!mobile) event.preventDefault();
      event.stopPropagation();
      const rect = icon.getBoundingClientRect();
      gesture = {
        id: event.pointerId, moved: false, longPressed: false,
        startX: event.clientX, startY: event.clientY,
        // Free-position avatars use their layout anchor, not hover/active scaling.
        offsetX: event.clientX - (iconDock || !icon.classList.contains('free-position') && mobile ? rect.left : iconAnchor.x),
        offsetY: event.clientY - (iconDock || !icon.classList.contains('free-position') && mobile ? rect.top : iconAnchor.y),
        anchor: { ...iconAnchor }, dock: iconDock, free: icon.classList.contains('free-position'),
      };
      if (!iconDock) {
        if (mobile) play(icon);
        quickTimer = setTimeout(() => {
          quickTimer = null;
          if (!gesture || gesture.moved || stopped || iconDock) return;
          gesture.longPressed = true;
          suppressClickUntil = Date.now() + 700;
          openQuickMenu(quickMenu, icon);
          if (pwin.navigator && typeof pwin.navigator.vibrate === 'function') {
            try { pwin.navigator.vibrate(20); } catch (_) {}
          }
        }, 500);
      }
      try { icon.setPointerCapture(event.pointerId); } catch (_) {}
    });
    on('pointermove', (event) => {
      if (!gesture || event.pointerId !== gesture.id) return;
      if (!gesture.moved) {
        if (Math.hypot(event.clientX - gesture.startX, event.clientY - gesture.startY) < 5) return;
        gesture.moved = true;
        cancelQuickPress();
        closeQuickMenu(quickMenu);
        iconDock = null;
        icon.classList.add('free-position');
        updateIconDockAppearance();
      }
      event.preventDefault();
      iconAnchor = clamp(event.clientX - gesture.offsetX, event.clientY - gesture.offsetY);
      layoutIcon();
    });
    on('pointerup', (event) => {
      if (gesture && event.pointerId === gesture.id) finishGesture(false);
    });
    for (const type of ['pointercancel', 'lostpointercapture']) on(type, (event) => {
      if (gesture && event.pointerId === gesture.id) finishGesture(true);
    });
    on('pointerenter', () => { if (!gesture && !iconDock) play(icon); });
    const activate = () => {
      if (stopped || gesture) return;
      if (iconDock) {
        restoreIcon();
        return;
      }
      closeQuickMenu(quickMenu);
      play(icon);
      panelOpen = !panelOpen;
      panel.style.display = panelOpen ? 'flex' : 'none';
      icon.classList.toggle('panel-open', panelOpen);
      if (!panelOpen) {
        closeAllPanelOverlays(panel);
        return;
      }
      refreshPanel();
      positionPanel(icon, panel);
      readCurrentApiConfig().then(renderApiConfig).catch(() => {
        const status = apiElement('status');
        if (status) {
          status.textContent = '无法读取酒馆连接';
          status.classList.add('kagami');
        }
      });
    };
    on('keydown', (event) => {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      event.preventDefault();
      event.stopPropagation();
      if (event.repeat) return;
      keyboardClickUntil = Date.now() + 700;
      activate();
    });
    on('keyup', (event) => {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      event.preventDefault();
      keyboardClickUntil = Date.now() + 320;
    });
    on('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (event.detail !== 0 && cancelledPointerClicks.size && (event.pointerId == null || cancelledPointerClicks.has(event.pointerId))) {
        if (event.pointerId == null) cancelledPointerClicks.clear();
        else cancelledPointerClicks.delete(event.pointerId);
        suppressClickUntil = 0;
        return;
      }
      if (Date.now() < suppressClickUntil || event.detail === 0 && Date.now() < keyboardClickUntil) return;
      activate();
    });
  }

  let icon;
  let panel;
  let quickMenu;
  let style;
  let toastElement;

  function cleanup() {
    if (stopped) return;
    // 关闭页面、切换预设或重载脚本前，再抓一次现场，尽量贴近「上次离开时」的状态。
    try { syncSessionSnapshot(promptData()); } catch (_) {}
    try { flushSessionSnapshotStore(); } catch (_) {}
    stopped = true;
    lifecycle.dispose();
    window.removeEventListener('pagehide', cleanup);
    if (pwin !== window) pwin.removeEventListener('pagehide', cleanup);
    clearTimeout(regexLinkageTimer);
    clearTimeout(playTimer);
    clearTimeout(searchInputTimer);
    clearTimeout(refreshTimer);
    clearInterval(presetPollTimer);
    if (presetChangeListener) pdoc.removeEventListener('change', presetChangeListener, true);
    if (outsidePointerListener) pdoc.removeEventListener('pointerdown', outsidePointerListener, true);
    if (adviceEditorFocusListener) pdoc.removeEventListener('focusin', adviceEditorFocusListener, true);
    adviceEditorFocusListener = null;
    if (resizeListener) pwin.removeEventListener('resize', resizeListener);
    if (resizeListener && viewportListenerTarget) {
      viewportListenerTarget.removeEventListener('resize', resizeListener);
      viewportListenerTarget.removeEventListener('scroll', resizeListener);
    }
    if (adviceMessageListener && typeof adviceMessageListener.stop === 'function') {
      try { adviceMessageListener.stop(); } catch (_) {}
    }
    adviceMessageListener = null;
    latestAdviceTransfer = null;
    adviceCapturedUserText = '';
    adviceUserEditDrafts.clear();
    adviceEditSyncing = false;
    advicePendingEditedMessageId = null;
    [icon, panel, quickMenu, style, toastElement].forEach((element) => {
      try { element && element.remove(); } catch (_) {}
    });
    try {
      if (pwin[GLOBAL_KEY] && pwin[GLOBAL_KEY].token === INSTANCE_TOKEN) delete pwin[GLOBAL_KEY];
    } catch (_) {}
  }

  function watchPresetSwitch() {
    knownPreset = presetName();
    knownPromptShape = promptShape();
    knownToggleShape = promptToggleShape();
    presetPollTimer = setInterval(() => {
      // 后台标签页和关闭的悬浮窗不做轮询；离开页面前 cleanup 仍会补记最终状态。
      if (!panelOpen || (pdoc.visibilityState && pdoc.visibilityState !== 'visible')) return;
      const current = presetName();
      const shape = knownPreset || current ? knownPromptShape : promptShape();
      if (knownPreset && current && current !== knownPreset) {
        if (nativePresetTransition && current === nativePresetTransition) {
          knownPreset = current;
          nativePresetTransition = '';
        } else {
          return cleanup();
        }
      }
      if (!knownPreset && !current && knownPromptShape && shape && shape !== knownPromptShape) return cleanup();

      let becameReady = false;
      if (!knownPreset && current) {
        knownPreset = current;
        becameReady = true;
      }
      if (!knownPromptShape && shape) {
        knownPromptShape = shape;
        becameReady = true;
      }
      const toggleShape = promptToggleShape();
      const toggleChanged = !!(knownToggleShape && toggleShape && toggleShape !== knownToggleShape);
      if (!knownToggleShape && toggleShape) knownToggleShape = toggleShape;
      if (toggleChanged) {
        knownToggleShape = toggleShape;
        refreshPanel();
      } else if (becameReady) {
        refreshPanel();
        readCurrentApiConfig().then(renderApiConfig).catch(() => {});
      }
    }, 1500);
    presetChangeListener = (event) => {
      const target = event.target;
      if (!target) return;
      invalidatePromptDataCache();
      scheduleRegexLinkage();
      const marker = `${target.id || ''} ${target.name || ''} ${target.className || ''}`;
      if (!/preset/i.test(marker)) return;
      if (adviceDisplayCompat) adviceDisplayCompat.reset();
      setTimeout(() => {
        const current = presetName();
        if (knownPreset && current && current !== knownPreset) {
          if (nativePresetTransition && current === nativePresetTransition) {
            knownPreset = current;
            nativePresetTransition = '';
            refreshPanel();
          } else {
            cleanup();
          }
        }
      }, 60);
    };
    pdoc.addEventListener('change', presetChangeListener, true);
  }

  async function waitForBody() {
    for (let index = 0; index < 120 && !pdoc.body && isCurrentIzumiInstance(); index += 1) await lifecycle.delay(25);
  }

  await waitForBody();
  if (!pdoc.body || !isCurrentIzumiInstance()) {
    lifecycle.dispose();
    return;
  }
  style = createStyle();
  const savedStart = initialPosition();
  icon = pdoc.createElement('div');
  icon.id = ID;
  if (isMobileIconLayout() && savedStart.saved) icon.classList.add('free-position');
  if (nightMode) icon.classList.add('night');
  icon.innerHTML = `<img src="${STATIC_SRC}" alt="泉此方" draggable="false" referrerpolicy="no-referrer">`;
  pdoc.body.appendChild(icon);
  iconAnchor = !savedStart.saved && isMobileIconLayout() ? savedStart : clamp(savedStart.x, savedStart.y);
  iconDock = savedStart.dock || null;
  layoutIcon();
  panel = createPanel();
  quickMenu = createQuickMenu();
  if (nightMode) quickMenu.classList.add('night');
  toastElement = pdoc.createElement('div');
  toastElement.id = TOAST_ID;
  pdoc.body.appendChild(toastElement);
  bindQuickMenu(quickMenu, icon);
  bindIcon(icon, panel, quickMenu);
  bindPanel(panel, icon);
  updateAdviceControls();
  adviceOwnerPreset = normalizeName(presetName());
  startAdviceFrontendCompat();
  if (adviceConfig.displayAdviceForUser && adviceRuntimeEnabled()) setTimeout(updateAdviceDisplayInChat, 120);
  adviceMessageListener = bindAdviceInterception();
  resizeListener = () => {
    resizeIconPosition();
    if (panel.dataset.userSize === 'true') {
      const rect = panel.getBoundingClientRect();
      applyPanelSize(panel, rect.width, rect.height);
    }
    positionPanel(icon, panel);
    positionQuickMenu(quickMenu, icon);
  };
  pwin.addEventListener('resize', resizeListener);
  viewportListenerTarget = pwin.visualViewport || null;
  if (viewportListenerTarget) {
    viewportListenerTarget.addEventListener('resize', resizeListener);
    viewportListenerTarget.addEventListener('scroll', resizeListener);
  }
  try { pwin[GLOBAL_KEY] = { token: INSTANCE_TOKEN, cleanup }; } catch (_) {}
  window.addEventListener('pagehide', cleanup, { once: true });
  if (pwin !== window) {
    pwin.addEventListener('pagehide', cleanup, { once: true });
  }
  watchPresetSwitch();
  refreshPanel();
  try {
    const preload = new Image();
    preload.onerror = () => { animatedImageUnavailable = true; };
    preload.src = ANIMATED_SRC;
  } catch (_) { animatedImageUnavailable = true; }
